#[derive(Subcommand)]
enum RunCommands {
    /// List saved workbench run records.
    List {
        /// Repository or system root used to locate the run directory.
        #[arg(long, default_value = ".")]
        root: PathBuf,

        /// Directory where run records are stored.
        #[arg(long)]
        run_root: Option<PathBuf>,
    },

    /// Inspect one saved workbench run record.
    Inspect {
        /// Run id or path to a run directory.
        run: PathBuf,

        /// Repository or system root used when resolving a run id.
        #[arg(long, default_value = ".")]
        root: PathBuf,

        /// Directory where run records are stored.
        #[arg(long)]
        run_root: Option<PathBuf>,
    },

    /// Inspect the newest saved workbench run record.
    Latest {
        /// Repository or system root used when resolving the run directory.
        #[arg(long, default_value = ".")]
        root: PathBuf,

        /// Directory where run records are stored.
        #[arg(long)]
        run_root: Option<PathBuf>,
    },
}

#[derive(Subcommand)]
enum TraceCommands {
    /// Regenerate declared traces from implementation-owned transition-record producers.
    Run {
        /// Path to implementation.yaml.
        implementation: PathBuf,

        /// Evidence profile to run.
        #[arg(long, value_enum, default_value_t = PropertyProfile::Smoke)]
        profile: PropertyProfile,

        /// Replace committed bundles after generated traces pass validation.
        #[arg(long)]
        record: bool,

        /// Print producer commands and output paths without executing project code.
        #[arg(long)]
        dry_run: bool,

        /// Emit machine-readable JSON.
        #[arg(long)]
        json: bool,

        /// Maximum duration for each producer command.
        #[arg(long, default_value_t = DEFAULT_PROOF_TIMEOUT_SECONDS)]
        timeout_seconds: u64,
    },

    /// Validate a local JSON/YAML trace bundle.
    Check {
        /// Path to a local trace bundle.
        bundle: PathBuf,

        /// Emit machine-readable JSON.
        #[arg(long)]
        json: bool,
    },

    /// Show a timeline reconstructed from recorded transition records.
    Show {
        /// Path to a local trace bundle.
        bundle: PathBuf,

        /// Emit machine-readable JSON.
        #[arg(long)]
        json: bool,
    },

    /// Find the first structurally bad transition in a trace bundle.
    Diagnose {
        /// Path to a local trace bundle.
        bundle: PathBuf,

        /// Emit machine-readable JSON.
        #[arg(long)]
        json: bool,
    },

    /// Stitch module-local trace bundles into one causally ordered system trace.
    Stitch {
        /// Two or more local trace bundles participating in one system flow.
        #[arg(required = true, num_args = 1..)]
        bundles: Vec<PathBuf>,

        /// Optional path for the generated rms/system-trace/v0.1 bundle.
        #[arg(long)]
        output: Option<PathBuf>,

        /// Emit machine-readable JSON.
        #[arg(long)]
        json: bool,
    },
}

#[derive(Subcommand)]
enum PropertyCommands {
    /// Check semantic property and fuzz target declarations.
    Check {
        /// Path to module.yaml or implementation.yaml.
        target: PathBuf,

        /// Treat property/fuzz production warnings as failures.
        #[arg(long)]
        strict: bool,

        /// Emit machine-readable JSON.
        #[arg(long)]
        json: bool,
    },

    /// Run declared property and fuzz verification commands for an implementation binding.
    Run {
        /// Path to implementation.yaml.
        implementation: PathBuf,

        /// Evidence profile to run.
        #[arg(long, value_enum, default_value_t = PropertyProfile::Smoke)]
        profile: PropertyProfile,

        /// Emit machine-readable JSON.
        #[arg(long)]
        json: bool,

        /// Print each exact realization command without executing project code.
        #[arg(long)]
        dry_run: bool,

        /// Maximum duration for each property realization command.
        #[arg(long, default_value_t = DEFAULT_PROOF_TIMEOUT_SECONDS)]
        timeout_seconds: u64,
    },

    /// Evaluate executable properties over a real RMS trace.
    Evaluate {
        /// Path to module.yaml or implementation.yaml.
        target: PathBuf,

        /// RMS trace bundle or probe system trace.
        #[arg(long)]
        trace: PathBuf,

        /// Select one or more property ids; omit to evaluate all executable properties.
        #[arg(long = "property")]
        properties: Vec<String>,

        /// Write rms/property-analysis/v0.2 evidence.
        #[arg(long)]
        out: Option<PathBuf>,

        /// Emit machine-readable JSON.
        #[arg(long)]
        json: bool,
    },

    /// Search a finite probe assembly for a witness or counterexample.
    Search {
        /// Path to module.yaml or implementation.yaml.
        target: PathBuf,

        /// Canonical rms/probe-assembly/v0.1, v0.2, or v0.3 input.
        #[arg(long)]
        assembly: PathBuf,

        /// Search for satisfaction or violation.
        #[arg(long, value_enum)]
        goal: PropertySearchGoal,

        /// Select one property id; omit when the target has exactly one executable property.
        #[arg(long = "property")]
        property: Option<String>,

        #[arg(long)]
        max_steps: Option<usize>,
        #[arg(long)]
        max_schedules: Option<usize>,
        #[arg(long)]
        max_states: Option<usize>,
        #[arg(long)]
        out: Option<PathBuf>,
        #[arg(long)]
        json: bool,
        #[arg(long, default_value_t = DEFAULT_PROOF_TIMEOUT_SECONDS)]
        timeout_seconds: u64,
    },

    /// Analyze finite relationships among executable properties.
    Analyze {
        /// Path to module.yaml or implementation.yaml.
        target: PathBuf,
        /// Canonical probe assembly; omit for SMT analysis of a contract v0.2 target.
        #[arg(long)]
        assembly: Option<PathBuf>,
        /// Select property ids; omit to analyze all executable properties.
        #[arg(long = "property")]
        properties: Vec<String>,
        #[arg(long)]
        max_steps: Option<usize>,
        #[arg(long)]
        max_schedules: Option<usize>,
        #[arg(long)]
        max_states: Option<usize>,
        #[arg(long)]
        out: Option<PathBuf>,
        #[arg(long)]
        json: bool,
        #[arg(long, default_value_t = DEFAULT_PROOF_TIMEOUT_SECONDS)]
        timeout_seconds: u64,
    },

    /// Incrementally evaluate a trace or normalized observation stream.
    Monitor {
        /// Path to module.yaml or implementation.yaml.
        target: PathBuf,
        /// Trace file, observation document, NDJSON stream, or `-` for stdin.
        #[arg(long)]
        input: PathBuf,
        /// Select one property id; omit when the target has exactly one executable property.
        #[arg(long = "property")]
        property: Option<String>,
        /// Treat the final input as a closed trace.
        #[arg(long)]
        complete: bool,
        #[arg(long)]
        out: Option<PathBuf>,
        #[arg(long)]
        json: bool,
    },

    /// Replay a recorded RMS property analysis or legacy fuzz counterexample.
    Replay {
        /// Path to rms/property-analysis/v0.1, v0.2, or a legacy property counterexample.
        analysis: PathBuf,

        /// Emit machine-readable JSON.
        #[arg(long)]
        json: bool,
    },
}

