impl PromptKind {
    fn label(self) -> &'static str {
        match self {
            PromptKind::Plan => "plan",
            PromptKind::Design => "design",
            PromptKind::Explain => "explain",
            PromptKind::Review => "review",
            PromptKind::Refactor => "refactor",
            PromptKind::Implement => "implement",
            PromptKind::Intent => "intent",
            PromptKind::EvolveContract => "evolve-contract",
            PromptKind::Prune => "prune",
            PromptKind::Evidence => "evidence",
            PromptKind::Drift => "drift",
        }
    }

    fn prompt_id(self) -> &'static str {
        match self {
            PromptKind::Plan => "rms.plan@v1",
            PromptKind::Design => "rms.design@v1",
            PromptKind::Explain => "rms.explain@v1",
            PromptKind::Review => "rms.review@v1",
            PromptKind::Refactor => "rms.refactor@v1",
            PromptKind::Implement => "rms.implement@v1",
            PromptKind::Intent => "rms.intent@v1",
            PromptKind::EvolveContract => "rms.evolve-contract@v1",
            PromptKind::Prune => "rms.prune@v1",
            PromptKind::Evidence => "rms.evidence@v1",
            PromptKind::Drift => "rms.drift@v1",
        }
    }

    fn default_task(self) -> Option<&'static str> {
        match self {
            PromptKind::Review => Some("review the diff for RMS conformance"),
            PromptKind::Explain => Some("explain how this module works"),
            PromptKind::Design => Some("design RMS module boundaries and semantic scaffold shapes"),
            PromptKind::Drift => {
                Some("identify drift between canonical RMS artifacts and implementation reality")
            }
            _ => None,
        }
    }

    fn includes_diff_by_default(self) -> bool {
        matches!(self, PromptKind::Review)
    }

    fn workflow(self) -> &'static [&'static str] {
        match self {
            PromptKind::Plan => &[
                "Treat RMS as the semantic and architecture gate: meaning or semantic-function binding changes require an RMS semantic-change object and `rms spec apply`; direct file edits may only fill declared role bodies.",
                "Restate the requested outcome in the owning context's domain language.",
                "Check whether the task reveals a new honest module boundary before assuming the current module is sufficient.",
                "Identify the owning module and smallest affected public semantic or runnable surface.",
                "Classify the change as private implementation, invariant/domain policy, public contract, dependency/effect, state/migration, or workflow.",
                "Name affected invariants, effects, compatibility promises, and recovery paths.",
                "Choose semantic shape before file layout: representation, message envelopes, transition outputs, transition records, ports, adapters, trace roles, and evidence.",
                "Close every affected public behavior as contract -> discharging semantic function -> classified machine inputs/outputs -> evidence, and every required capability as exact consumer -> provider contract or explicit external boundary.",
                "Choose representation obligations: closed variants, validated constructors, explicit results, boundary schemas, or lifecycle state when behavior depends on order.",
                "Keep binding container names separate from semantic alternatives: `types.state` names the ADT; `states` names its cases.",
                "Classify every machine input as exactly one command, observed event, or effect result, and name illegal state/input combinations.",
                "Keep expected rejection as an explicit transition output, and require replay records to match the exact canonical case outputs rather than a copied declaration list.",
                "When an effect outcome can change what happens next, plan one atomic request, one typed result, and a follow-up transition; do not hide sequencing in the executor.",
                "Classify versioned artifacts and transformations, cross-module protocols, resource ownership, elevated authority, and temporal guarantees before choosing binding files.",
                "Propose the smallest implementation and verification path.",
            ],
            PromptKind::Design => &[
                "Return only an `rms/intent-model/v0.1` extraction: facts, responsibilities, binding preferences, and material questions. Do not propose modules, shapes, topology, files, or scaffolds.",
                "Use exact source quotes for explicit facts and rationale for inferred facts; preserve negation as an absent disposition rather than a positive keyword signal.",
                "Leave every material uncertainty as `unknown`; RMS, not the provider, validates the model and deterministically selects `rms add-module` or `rms add-capability-tree`.",
                "Start from system purpose, contexts, existing modules, glossary language, and the requested task.",
                "Classify whether the task owns domain decisions, lifecycle, effects, a runnable surface, reuse, storage, integration, monitoring, or boundary adaptation without converting those facts into topology.",
                "Treat provider output and generated plans as advisory evidence until reflected in canonical artifacts.",
            ],
            PromptKind::Explain => &[
                "Answer from the bounded RMS context first: purpose, ownership, public contracts, invariants, effects, profiles, and verification.",
                "Keep the explanation intelligible, simple, and direct without dumbing down the module semantics.",
                "Use the user's question as the focus when supplied.",
                "Do not invent architecture that is absent from the manifest or contracts.",
                "Name uncertainty or missing artifacts instead of guessing.",
            ],
            PromptKind::Review => &[
                "Review the diff against the module manifest, public contracts, direct dependencies, declared effects, profiles, and verification evidence.",
                "Flag semantic roles, semantic-function authority bindings, state variants, transitions, effects, runnable surfaces, public entrypoints, parsers, or evidence added by hand instead of through RMS CLI artifacts as architecture-gate bypasses.",
                "Flag reusable-module consumers that import provider representation, transition, parser, adapter, or port internals instead of the declared public facade or contract-shaped entrypoint.",
                "Find behavioral regressions, boundary violations, undeclared effects or dependencies, compatibility drift, missing evidence, and stale canonical artifacts.",
                "Flag collapsed semantic variants, stateful transitions that omit state or classified input, effect results that bypass transition, executor-owned retry or sequencing, and corpus-only evidence presented as fuzzing.",
                "Flag typed rejections erased into replies or provenance strings, synthetic traces that do not match canonical outputs, boundary IO without effect protocols, and runnable delegation that names only a file.",
                "Flag implemented public behavior without one exact contract-to-function-to-machine binding, and required capabilities without an exact consumer-to-provider binding.",
                "Flag cross-module messages without protocol bindings, terminal resource leaks, undeclared privileged/unsafe/foreign operations, unversioned artifact transformations, and temporal claims backed by the wrong proof strategy.",
                "Prioritize findings by severity and include file or artifact references when possible.",
                "Do not treat generated prose, issue text, or incidental implementation shape as architectural authority.",
            ],
            PromptKind::Refactor => &[
                "Preserve public contracts, invariants, declared effects, compatibility, and verification meaning.",
                "If refactoring reveals new laws, contracts, states, commands, events, effects, runnable surfaces, public entrypoints, semantic roles, semantic-function bindings, or evidence obligations, return an RMS semantic-change object before editing files.",
                "Identify weak representation, duplicated concepts, decision/effect coupling, ownership confusion, boundary leakage, lifecycle clutter, or semantic residue.",
                "Preserve one canonical transition path for commands, observed events, and effect results; move sequencing policy out of executors and into transitions.",
                "Preserve protocol automata, resource ownership, artifact compatibility, authority containment, and temporal properties; revise them through `rms spec apply` when their meaning changes.",
                "Prefer semantic roles over conventional helper names: representation, message envelopes, transition output, transition records, ports, adapters, trace roles, and evidence.",
                "Prefer deletion, inlining, renaming, or representation strengthening before new abstractions.",
                "Escalate to implement-change or evolve-contract if public meaning must change.",
            ],
            PromptKind::Implement => &[
                "RMS owns semantics and architecture, and agents fill declared roles: use `rms spec plan/apply/check` when laws, contracts, machine structure, semantic-function bindings, runnable surfaces, effects, or evidence obligations change, then edit only declared role files.",
                "Never repair canonical manifests, contracts, roles, semantic-function bindings, surfaces, or evidence declarations by direct editing. Use `semantic_functions.add/set/remove` for exact symbols, authority owners, purity, discharged promises, assumptions, and evidence. If an RMS apply command cannot express the required change, stop and report that RMS gap.",
                "Restate the requested outcome in the owning context's domain language.",
                "Check whether accepted intent and rationale already exist for this semantic change; if not, stop and run intent capture before coding.",
                "Classify the change as private implementation, invariant or domain policy, public contract, dependency or effect, state or migration, or workflow.",
                "Check whether the task requires scope expansion or a module split before deepening the current module.",
                "Keep the change inside the owning module boundary.",
                "Update public contracts or manifests first when public meaning changes.",
                "Update linked intent, decision, contract, law, and evidence records together when accepted semantics evolve.",
                "Name affected invariants, contracts, effects, compatibility promises, and recovery paths.",
                "Keep the semantic chain complete: public contract -> discharging semantic function -> classified machine cases -> proof, and required capability -> exact consumer -> matching provider contract or explicit external boundary.",
                "Separate domain decisions from external effects where practical.",
                "Keep private helpers pure inside pure role files; model IO as declared effects/effect-results executed only in adapter, port, or effect-executor roles.",
                "For reusable modules, keep RMS capabilities/contracts and the declared public facade as the import surface; native package manifests are binding evidence only.",
                "Use semantic implementation roles before file-level code: representation, message envelopes, transition output, transition records, ports, adapters, trace roles, and evidence.",
                "Resolve semantic edge cases before implementation: impossible variants, invalid constructors, illegal transitions, malformed boundary input, stale or conflicting state, and terminal-state behavior.",
                "Test whether public constructors can create contradictory values, and replace boolean/nullable combinations with closed states when they can.",
                "Keep semantic case names separate from binding type names and dispatch every command, observed event, and effect result through the canonical transition.",
                "Return expected failure through the transition rejection channel, and generate replay records from the same transition path with exact canonical outputs.",
                "Effect executors perform one declared request and return one declared result; transitions own sequencing, retry, compensation, stop/continue policy, and progress.",
                "Model inspectable boundary IO as declared effects and typed results behind executors; runnable surfaces delegate to exact callables rather than source files.",
                "Implement declared artifact transformations, protocol message mappings, resource operations, authority facades, and temporal proof runners inside their exact semantic owners; do not infer them from helper names.",
                "Use the strongest available representation for invalid states, expected failures, boundary input, and lifecycle transitions.",
                "Add the smallest evidence that demonstrates the changed promise.",
                "Return concrete implementation instructions; do not claim edits were made unless the executing agent actually made them.",
            ],
            PromptKind::Intent => &[
                "Extract `rms/intent-model/v0.1` facts before deeper semantic planning; never put module names, shapes, topology, or scaffold recommendations in that model.",
                "Think before code: do not propose implementation steps until intent, rationale, contracts, and evidence obligations are understood.",
                "Normalize the human request into atomic stories with actors, state, actions, success results, failure results, and stale or conflicting-state behavior.",
                "Ask only the questions needed to resolve product, domain, ownership, source-of-truth, lifecycle, compatibility, or operational ambiguity.",
                "Synthesize accepted intent into candidate contracts, laws, invariants, glossary terms, ownership, effects, compatibility impact, and proof lanes.",
                "Enumerate accepted command, observed-event, and effect-result cases plus illegal transitions before proposing code.",
                "Identify the exact semantic-function owner and machine cases for each public behavior, plus the exact consumer and provider resolution for each required capability.",
                "Ask whether each external outcome can change the next decision; model such outcomes as typed effect results rather than executor control flow.",
                "Ask which artifacts cross boundaries or change form, which modules exchange ordered messages, which resources require ownership closure, which operations need elevated authority, and which facts must always or eventually hold.",
                "Separate raw conversation notes from accepted rationale; raw prompt output is evidence, not semantic authority.",
                "Name the canonical artifacts that must change before implementation: intent notes, decision records, glossary, module manifest, contracts, laws, semantic-function authority bindings, runnable surface declarations, and verification evidence.",
                "Stop at an implementation gate when accepted intent is missing or contradictions exist among canonical artifacts.",
            ],
            PromptKind::EvolveContract => &[
                "Identify all published contract versions and known consumers.",
                "Classify compatibility impact across shape, meaning, failures, authorization, idempotency, ordering, consistency, timeout, retry, stored state, and operations.",
                "Preserve the existing version when compatibility can be maintained cleanly.",
                "Introduce a new version for breaking changes and define migration, coexistence, translation, and deprecation behavior.",
            ],
            PromptKind::Prune => &[
                "Build a semantic root set from manifests, contracts, invariants, effects, profiles, compatibility policy, operational recovery, implementation binding, and verification evidence.",
                "Classify candidate artifacts by current semantic role.",
                "Delete, merge, inline, rename, or document residue before introducing replacements.",
                "Do not hide a semantic change as pruning.",
            ],
            PromptKind::Evidence => &[
                "Identify the changed promise and the evidence category it belongs to: law, contract, scenario, boundary, runnable surface, runtime, reconciliation, or migration.",
                "For machine-shaped behavior, request transition records, replay bundles, golden timelines, effect-result handling, and first-bad-transition proof where applicable.",
                "For system-shaped behavior, request artifact compatibility, protocol composition, stitched message causation, resource closure, authority containment, and temporal realization evidence where applicable.",
                "Require stateful traces to cover every declared transition and effect-result branch, with each record's state_after feeding the next state_before.",
                "Require each trace record to match its canonical case's exact state change, events, commands, effects, reply, and rejection, and reject declaration-derived synthetic traces as execution proof.",
                "Distinguish deterministic corpus, deterministic exhaustive, generated-property, and coverage-fuzzer evidence; a fixed corpus does not prove an open-ended fuzz claim.",
                "For reusable modules, request package/reuse evidence, run `rms package` so RMS records the verified result, independently recheck with `rms verify-package` when useful, and prove consumers use the public facade.",
                "Prefer the smallest evidence that strongly demonstrates the promise.",
                "Include negative evidence for impossible variants, invalid constructors, malformed boundary input, and illegal transitions when applicable.",
                "Name the manifest paths or implementation binding entries that should reference the evidence, and use `semantic_functions.add/set/remove` when the proof changes a function's discharged promise or evidence binding.",
                "Replace scaffold placeholder, bootstrap, unpinned, and semantic-shape-only evidence before marking implemented modules done.",
            ],
            PromptKind::Drift => &[
                "Compare manifest purpose, ownership, contracts, effects, profiles, compatibility policy, verification evidence, and glossary language against implementation reality.",
                "Identify contradictions among canonical artifacts as architectural drift, not a prompt-precedence problem.",
                "Separate deterministic validation failures from semantic suspicions requiring human review.",
                "Propose the smallest artifact or implementation correction for each drift item.",
            ],
        }
    }

    fn expected_output(self) -> &'static [&'static str] {
        match self {
            PromptKind::Plan => &[
                "Owning module and affected contract surface.",
                "Whether a new module boundary or semantic shape is required.",
                "Change classification and compatibility impact.",
                "Affected invariants, effects, dependencies, profiles, and recovery paths.",
                "Implementation outline inside the owning boundary.",
                "Focused verification plan and commands.",
            ],
            PromptKind::Design => &[
                "Exactly one `rms/intent-model/v0.1` object with no architecture fields.",
                "Required, absent, or unknown disposition for every material fact.",
                "Exact quotes for explicit facts and rationale for inferred facts.",
                "Responsibilities stated as semantic work, not module recommendations.",
                "Material open questions that must stop deterministic topology selection.",
            ],
            PromptKind::Explain => &[
                "Intelligible plain-language explanation of how the module works.",
                "Important public contracts and owned decisions.",
                "Effects, invariants, and verification evidence that shape behavior.",
                "Any missing or ambiguous canonical artifacts relevant to the question.",
            ],
            PromptKind::Review => &[
                "Findings first, ordered by severity.",
                "Each finding names the violated RMS artifact or missing evidence.",
                "Open questions or assumptions.",
                "Brief change summary only after findings.",
            ],
            PromptKind::Refactor => &[
                "Public semantics preserved.",
                "Internal shape changes proposed.",
                "Boundary, dependency, and effect impact.",
                "Verification needed to prove compatibility.",
            ],
            PromptKind::Implement => &[
                "Requested outcome in owning-context language.",
                "Scope expansion or module split decision.",
                "Change classification and compatibility impact.",
                "Concrete implementation steps.",
                "Contract/manifest updates required before code changes.",
                "Semantic structure before code: representation, command/state/result ADTs, transition model, parser boundaries, and evidence roles.",
                "Resolved edge cases before implementation: invalid commands, illegal transitions, malformed input, terminal states, stale or conflicting state, and expected effect failures.",
                "Representation choices for invalid states, failures, boundary schemas, or lifecycle transitions.",
                "Verification and conformance evidence.",
            ],
            PromptKind::Intent => &[
                "Normalized stories and accepted interpretation.",
                "Questions asked, answers accepted, and unresolved product decisions.",
                "Candidate contracts, laws, invariants, ownership, source of truth, effects, compatibility, and proof lanes.",
                "Rationale and rejected alternatives to preserve in decision records.",
                "Canonical artifacts to update before implementation.",
                "Implementation gate result: ready, blocked on questions, or drift detected.",
            ],
            PromptKind::EvolveContract => &[
                "Compatibility classification.",
                "Versioning decision.",
                "Migration, coexistence, translation, and deprecation plan.",
                "Provider and consumer evidence updates.",
            ],
            PromptKind::Prune => &[
                "Semantic root set.",
                "Artifacts to delete, merge, inline, rename, retain, or defer.",
                "Compatibility and evidence impact.",
                "Removal conditions for retained residue.",
            ],
            PromptKind::Evidence => &[
                "Evidence category and rationale.",
                "Positive and negative cases.",
                "Manifest or implementation binding references to update.",
                "Native command expected to run the evidence.",
                "Placeholder/bootstrap/source-pinning diagnostics resolved for modules claimed as implemented.",
            ],
            PromptKind::Drift => &[
                "Confirmed drift.",
                "Suspected drift requiring review.",
                "Canonical artifact or implementation source of each mismatch.",
                "Smallest correction path.",
            ],
        }
    }

    fn deterministic_checks(self) -> &'static [&'static str] {
        match self {
            PromptKind::Explain
            | PromptKind::Design
            | PromptKind::Plan
            | PromptKind::Intent
            | PromptKind::Evidence
            | PromptKind::Drift => &["rms validate --root <root>", "rms compose --root <root>"],
            PromptKind::Review
            | PromptKind::Refactor
            | PromptKind::Implement
            | PromptKind::Prune => &[
                "rms validate --root <root>",
                "rms spec check <module.yaml|implementation.yaml>",
                "rms machine check <implementation.yaml>",
                "rms verify <implementation.yaml|composite-module.yaml>",
                "rms compose --root <root>",
            ],
            PromptKind::EvolveContract => &[
                "rms check-compat <old-module.yaml> <new-module.yaml>",
                "rms validate --root <root>",
                "rms compose --root <root>",
            ],
        }
    }
}

impl Provider {
    fn label(self) -> &'static str {
        match self {
            Provider::None => "none",
            Provider::Codex => "codex",
        }
    }
}

impl CodexSandbox {
    fn as_str(self) -> &'static str {
        match self {
            CodexSandbox::ReadOnly => "read-only",
            CodexSandbox::WorkspaceWrite => "workspace-write",
        }
    }
}

impl ProviderWriteScope {
    fn as_str(self) -> &'static str {
        match self {
            ProviderWriteScope::Module => "module",
            ProviderWriteScope::Root => "root",
        }
    }
}

fn resolve_prompt_run_options(root: &Path, raw: RawPromptRunOptions) -> Result<PromptRunOptions> {
    if raw.ai && raw.provider.is_some() {
        bail!("use either `--ai` or `--provider`, not both");
    }

    let config = load_workbench_config(root)?;
    let config_value = config.as_ref().map(|loaded| &loaded.value);

    let provider = if raw.ai {
        let configured = config_value
            .and_then(|config| config.ai.default_provider.as_deref())
            .ok_or_else(|| {
                anyhow!(
                    "`--ai` requires `{}` with `ai.default_provider`",
                    root.join(WORKBENCH_CONFIG_PATH).display()
                )
            })?;
        let provider = parse_config_provider(configured, "ai.default_provider")?;
        if provider == Provider::None {
            bail!("`--ai` requires a non-`none` `ai.default_provider`");
        }
        provider
    } else {
        raw.provider.unwrap_or(Provider::None)
    };

    let run_root = raw
        .run_root
        .or_else(|| config_value.and_then(|config| config.runs.directory.clone()))
        .unwrap_or_else(|| PathBuf::from(DEFAULT_RUN_ROOT));

    let model = raw.model.or_else(|| {
        if provider == Provider::Codex {
            config_value.and_then(|config| config.ai.codex.model.clone())
        } else {
            None
        }
    });
    let profile = None;

    let sandbox = if let Some(sandbox) = raw.sandbox {
        sandbox
    } else if provider == Provider::Codex {
        config_value
            .and_then(|config| config.ai.codex.sandbox.as_deref())
            .map(|value| parse_config_sandbox(value, "ai.codex.sandbox"))
            .transpose()?
            .unwrap_or(CodexSandbox::ReadOnly)
    } else {
        CodexSandbox::ReadOnly
    };

    let write_scope = if let Some(write_scope) = raw.write_scope {
        write_scope
    } else if provider == Provider::Codex {
        config_value
            .and_then(|config| config.ai.codex.write_scope.as_deref())
            .map(|value| parse_config_write_scope(value, "ai.codex.write_scope"))
            .transpose()?
            .unwrap_or_else(|| {
                if matches!(sandbox, CodexSandbox::WorkspaceWrite) {
                    ProviderWriteScope::Module
                } else {
                    ProviderWriteScope::Root
                }
            })
    } else {
        ProviderWriteScope::Root
    };

    let provider_timeout_seconds = if let Some(timeout_seconds) = raw.provider_timeout_seconds {
        timeout_seconds
    } else if provider == Provider::Codex {
        config_value
            .and_then(|config| config.ai.codex.timeout_seconds)
            .map(|value| parse_config_timeout_seconds(value, "ai.codex.timeout_seconds"))
            .transpose()?
            .unwrap_or(DEFAULT_PROVIDER_TIMEOUT_SECONDS)
    } else {
        DEFAULT_PROVIDER_TIMEOUT_SECONDS
    };

    Ok(PromptRunOptions {
        provider,
        record: raw.record,
        run_root,
        model,
        profile,
        sandbox,
        write_scope,
        provider_timeout_seconds,
    })
}

fn resolve_run_root(root: &Path, explicit: Option<PathBuf>) -> Result<PathBuf> {
    if let Some(path) = explicit {
        return Ok(path);
    }
    Ok(load_workbench_config(root)?
        .and_then(|loaded| loaded.value.runs.directory)
        .unwrap_or_else(|| PathBuf::from(DEFAULT_RUN_ROOT)))
}

fn load_workbench_config(root: &Path) -> Result<Option<LoadedWorkbenchConfig>> {
    let path = root.join(WORKBENCH_CONFIG_PATH);
    if !path.exists() {
        return Ok(None);
    }
    let source = fs::read_to_string(&path)
        .with_context(|| format!("failed to read `{}`", path.display()))?;
    let value: WorkbenchConfig = serde_yaml::from_str(&source)
        .with_context(|| format!("failed to parse `{}`", path.display()))?;
    Ok(Some(LoadedWorkbenchConfig { path, value }))
}

fn run_config_init(
    root: &Path,
    provider: Provider,
    model: Option<&str>,
    run_root: &Path,
    force: bool,
) -> Result<()> {
    let path = root.join(WORKBENCH_CONFIG_PATH);
    if path.exists() && !force {
        bail!(
            "workbench config already exists at `{}`; pass `--force` to overwrite",
            path.display()
        );
    }
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)
            .with_context(|| format!("failed to create `{}`", parent.display()))?;
    }
    let rendered = render_workbench_config(provider, model, run_root);
    fs::write(&path, rendered).with_context(|| format!("failed to write `{}`", path.display()))?;
    println!("created {}", path.display());
    Ok(())
}

fn run_agent_diagnose(root: &Path, target: AgentTarget) -> Result<()> {
    let report = build_agent_integration_report(root, target);
    print_agent_integration_report(&report);
    Ok(())
}

fn run_agent_init(root: &Path, target: AgentTarget, force: bool) -> Result<()> {
    fs::create_dir_all(root)
        .with_context(|| format!("failed to create agent root `{}`", root.display()))?;
    write_agent_guidance(root, target, force, true)?;
    println!(
        "initialized {} agent guidance at {}",
        target.label(),
        root.display()
    );
    Ok(())
}

fn run_agent_sync(root: &Path, target: AgentTarget) -> Result<()> {
    fs::create_dir_all(root)
        .with_context(|| format!("failed to create agent root `{}`", root.display()))?;
    write_agent_guidance(root, target, true, false)?;
    sync_rms_gitignore(root)?;
    println!(
        "synced {} agent guidance at {}",
        target.label(),
        root.display()
    );
    Ok(())
}

fn sync_rms_gitignore(root: &Path) -> Result<()> {
    let path = root.join(".gitignore");
    if !path.exists() {
        return Ok(());
    }
    let existing = fs::read_to_string(&path)
        .with_context(|| format!("failed to read `{}`", path.display()))?;
    if existing == INIT_GITIGNORE {
        return Ok(());
    }
    let merged = merge_managed_section(
        &existing,
        RMS_MANAGED_GITIGNORE_START,
        RMS_MANAGED_GITIGNORE_END,
        INIT_ADOPTED_GITIGNORE_BLOCK,
    )?;
    if merged != existing {
        fs::write(&path, merged)
            .with_context(|| format!("failed to update `{}`", path.display()))?;
    }
    Ok(())
}

fn write_agent_guidance(
    root: &Path,
    target: AgentTarget,
    overwrite_guidance: bool,
    write_config: bool,
) -> Result<()> {
    write_primary_agent_guidance(&root.join("AGENTS.md"), overwrite_guidance)?;
    if target == AgentTarget::Claude {
        write_claude_guidance(&root.join("CLAUDE.md"), overwrite_guidance)?;
    }
    sync_agent_skills(root, target, overwrite_guidance)?;
    let config_path = root.join(WORKBENCH_CONFIG_PATH);
    if write_config || !config_path.exists() {
        write_agent_file(
            &config_path,
            &render_workbench_config(Provider::Codex, None, Path::new(DEFAULT_RUN_ROOT)),
            overwrite_guidance,
        )?;
    }
    Ok(())
}

fn write_primary_agent_guidance(path: &Path, overwrite: bool) -> Result<()> {
    if overwrite && path.exists() {
        let existing = fs::read_to_string(path)
            .with_context(|| format!("failed to read `{}`", path.display()))?;
        if existing == INIT_AGENTS_MD {
            return Ok(());
        }
        if existing.contains(RMS_FULL_GUIDANCE_SIGNATURE) {
            return fs::write(path, INIT_AGENTS_MD)
                .with_context(|| format!("failed to write `{}`", path.display()));
        }
        if existing.contains(RMS_MANAGED_AGENTS_START) || existing.contains(RMS_MANAGED_AGENTS_END)
        {
            let merged = merge_managed_section(
                &existing,
                RMS_MANAGED_AGENTS_START,
                RMS_MANAGED_AGENTS_END,
                INIT_ADOPTED_AGENTS_BLOCK,
            )?;
            return fs::write(path, merged)
                .with_context(|| format!("failed to write `{}`", path.display()));
        }
        let merged = merge_managed_section(
            &existing,
            RMS_MANAGED_AGENTS_START,
            RMS_MANAGED_AGENTS_END,
            INIT_ADOPTED_AGENTS_BLOCK,
        )?;
        return fs::write(path, merged)
            .with_context(|| format!("failed to write `{}`", path.display()));
    }
    write_agent_file(path, INIT_AGENTS_MD, overwrite)
}

fn write_claude_guidance(path: &Path, overwrite: bool) -> Result<()> {
    if overwrite && path.exists() {
        let existing = fs::read_to_string(path)
            .with_context(|| format!("failed to read `{}`", path.display()))?;
        if existing == INIT_CLAUDE_MD {
            return Ok(());
        }
        let merged = merge_managed_section(
            &existing,
            RMS_MANAGED_CLAUDE_START,
            RMS_MANAGED_CLAUDE_END,
            INIT_CLAUDE_MD,
        )?;
        return fs::write(path, merged)
            .with_context(|| format!("failed to write `{}`", path.display()));
    }
    write_agent_file(path, INIT_CLAUDE_MD, overwrite)
}

fn write_agent_file(path: &Path, contents: &str, overwrite: bool) -> Result<()> {
    if overwrite {
        if let Some(parent) = path.parent() {
            fs::create_dir_all(parent)?;
        }
        fs::write(path, contents)
            .with_context(|| format!("failed to write `{}`", path.display()))?;
        Ok(())
    } else {
        write_new_file(path, contents)
    }
}

fn sync_agent_skills(root: &Path, target: AgentTarget, overwrite: bool) -> Result<()> {
    let skills_root = target.skill_root(root);
    for (relative_path, contents) in INIT_AGENT_SKILLS {
        write_agent_file(&skills_root.join(relative_path), contents, overwrite)?;
    }
    Ok(())
}

fn build_agent_integration_report(root: &Path, target: AgentTarget) -> AgentIntegrationReport {
    let local_skills = agent_skills_readiness(root, target);
    let agent_instructions = agent_guidance_readiness(&root.join("AGENTS.md"));
    let config = diagnose_config(root);
    let target_tool = Some(target.target_tool());
    let skill_sources = detect_skill_sources(root, home_dir().ok().as_deref());
    let mut guidance = vec![
        "The RMS CLI is sufficient; plugins and global skills are optional adapters.".to_string(),
        format!(
            "Use `rms agent init --target {} --root .` to create missing project-local guidance.",
            target.label()
        ),
        format!(
            "Use `rms agent sync --target {} --root .` after upgrading RMS to refresh generated guidance.",
            target.label()
        ),
    ];
    if config.status == "missing" {
        guidance.push("Project-local `.rms/config.yaml` is missing; agent init will create safe read-only Codex defaults.".to_string());
    }
    if !local_skills.missing.is_empty() || !local_skills.drifted.is_empty() {
        guidance.push(format!(
            "Local RMS skills are missing or stale; run `rms agent sync --target {} --root .`.",
            target.label()
        ));
    }
    if target == AgentTarget::Claude && !root.join("CLAUDE.md").exists() {
        guidance.push(
            "Claude target expects project-local `CLAUDE.md` that imports `AGENTS.md`.".to_string(),
        );
    }

    if matches!(
        agent_instructions.status.as_str(),
        "drifted" | "malformed" | "unmanaged" | "missing"
    ) {
        guidance.push(format!(
            "Project guidance is {}; run `rms agent sync --target {} --root .` when RMS may manage it.",
            agent_instructions.status,
            target.label()
        ));
    }
    guidance.push(COMMIT_AUTHORITY_POLICY.to_string());

    AgentIntegrationReport {
        target: target.label().to_string(),
        root: root.display().to_string(),
        agent_instructions,
        target_instructions: match target {
            AgentTarget::Codex => None,
            AgentTarget::Claude => Some(exact_managed_file_readiness(
                "CLAUDE.md",
                &root.join("CLAUDE.md"),
                INIT_CLAUDE_MD,
            )),
        },
        local_skills,
        config,
        target_tool,
        plugin_required: false,
        skill_sources,
        guidance,
    }
}

fn agent_skills_readiness(root: &Path, target: AgentTarget) -> AgentSkillsReadiness {
    let skills_root = target.skill_root(root);
    let mut missing = Vec::new();
    let mut drifted = Vec::new();
    let mut expected = BTreeSet::new();

    for (relative_path, contents) in INIT_AGENT_SKILLS {
        expected.insert((*relative_path).to_string());
        let path = skills_root.join(relative_path);
        match fs::read_to_string(&path) {
            Ok(actual) if actual == *contents => {}
            Ok(_) => drifted.push((*relative_path).to_string()),
            Err(_) => missing.push((*relative_path).to_string()),
        }
    }

    let mut extra = Vec::new();
    collect_agent_skill_files(&skills_root, &skills_root, &mut extra).ok();
    extra.retain(|path| !expected.contains(path));

    let status = if !skills_root.exists() {
        "missing"
    } else if missing.is_empty() && drifted.is_empty() {
        "present"
    } else {
        "stale"
    };

    AgentSkillsReadiness {
        directory: skills_root.display().to_string(),
        status: status.to_string(),
        expected: INIT_AGENT_SKILLS.len(),
        missing,
        drifted,
        extra,
    }
}

fn detect_skill_sources(root: &Path, home: Option<&Path>) -> SkillSourceReport {
    let embedded_digest = embedded_skill_set_digest();
    let mut sources = vec![SkillSource {
        origin: "embedded-rms".to_string(),
        scope: "binary".to_string(),
        path: "rms://embedded/skills".to_string(),
        configured_state: "built-in".to_string(),
        digest: Some(embedded_digest.clone()),
        embedded_equivalence: "canonical".to_string(),
        runtime_activation: "unknown",
        precedence: "host-defined",
        status: "informational".to_string(),
        remediation: None,
    }];

    sources.push(filesystem_skill_source(
        "project-codex",
        "project",
        &root.join(".agents/skills"),
        None,
        "run `rms agent sync --target codex --root .`",
        &embedded_digest,
    ));
    sources.push(filesystem_skill_source(
        "project-claude",
        "project",
        &root.join(".claude/skills"),
        None,
        "run `rms agent sync --target claude --root .`",
        &embedded_digest,
    ));

    if let Some(home) = home {
        for (origin, path) in [
            ("user-codex", home.join(".codex/skills")),
            ("user-claude", home.join(".claude/skills")),
            ("user-agents", home.join(".agents/skills")),
        ] {
            sources.push(filesystem_skill_source(
                origin,
                "user",
                &path,
                None,
                "synchronize or remove the divergent direct RMS skill copy",
                &embedded_digest,
            ));
        }

        let marketplace_path = home.join(".agents/plugins/marketplace.json");
        let installed_status = codex_plugin_installed_status_at_home(home, "rms", "personal");
        let marketplace_configured = match marketplace_plugin_presence(&marketplace_path, "rms") {
            MarketplacePluginPresence::Present => {
                format!("marketplace-entry;{installed_status}")
            }
            MarketplacePluginPresence::MissingEntry => {
                format!("marketplace-entry-missing;{installed_status}")
            }
            MarketplacePluginPresence::Missing => {
                format!("marketplace-missing;{installed_status}")
            }
            MarketplacePluginPresence::Malformed => {
                format!("marketplace-malformed;{installed_status}")
            }
            MarketplacePluginPresence::Unreadable => {
                format!("marketplace-unreadable;{installed_status}")
            }
        };
        let plugin_root = marketplace_rms_plugin_root(&marketplace_path)
            .unwrap_or_else(|| home.join("plugins/rms"));
        sources.push(filesystem_skill_source(
            "personal-marketplace",
            "plugin",
            &plugin_root.join("skills"),
            Some(marketplace_configured),
            "run `rms agent plugin sync --target codex`",
            &embedded_digest,
        ));

        let cache_root = home.join(".codex/plugins/cache/personal/rms");
        match fs::read_dir(&cache_root) {
            Ok(entries) => {
                let mut versions = entries
                    .filter_map(Result::ok)
                    .filter(|entry| entry.path().is_dir())
                    .map(|entry| entry.path())
                    .collect::<Vec<_>>();
                versions.sort();
                for version in versions {
                    let label = version
                        .file_name()
                        .and_then(|name| name.to_str())
                        .unwrap_or("<unknown>");
                    sources.push(filesystem_skill_source(
                        &format!("plugin-cache:{label}"),
                        "plugin-cache",
                        &version.join("skills"),
                        Some(codex_plugin_installed_status_at_home(
                            home, "rms", "personal",
                        )),
                        "run `rms agent plugin sync --target codex`, then start a new host thread",
                        &embedded_digest,
                    ));
                }
            }
            Err(_) => sources.push(SkillSource {
                origin: "plugin-cache".to_string(),
                scope: "plugin-cache".to_string(),
                path: cache_root.display().to_string(),
                configured_state: "missing".to_string(),
                digest: None,
                embedded_equivalence: "unavailable".to_string(),
                runtime_activation: "unknown",
                precedence: "host-defined",
                status: "informational".to_string(),
                remediation: None,
            }),
        }
    } else {
        sources.push(SkillSource {
            origin: "user-home".to_string(),
            scope: "user".to_string(),
            path: "<HOME-unavailable>".to_string(),
            configured_state: "unknown".to_string(),
            digest: None,
            embedded_equivalence: "unavailable".to_string(),
            runtime_activation: "unknown",
            precedence: "host-defined",
            status: "informational".to_string(),
            remediation: None,
        });
    }

    sources.sort_by(|left, right| {
        left.origin
            .cmp(&right.origin)
            .then_with(|| left.path.cmp(&right.path))
    });
    let informational = sources
        .iter()
        .filter(|source| source.status == "informational")
        .count();
    let review_required = sources
        .iter()
        .filter(|source| source.status == "review-required")
        .count();
    SkillSourceReport {
        runtime_activation: "unknown",
        precedence: "host-defined",
        sources,
        informational,
        review_required,
    }
}

fn filesystem_skill_source(
    origin: &str,
    scope: &str,
    path: &Path,
    configured_state: Option<String>,
    remediation: &str,
    embedded_digest: &str,
) -> SkillSource {
    let observation = observe_skill_set(path, embedded_digest);
    let configured_state = configured_state.unwrap_or_else(|| {
        if path.is_dir() && observation.equivalence == "unavailable" {
            "no-rms-copy".to_string()
        } else if path.is_dir() {
            "detected".to_string()
        } else {
            "not-configured".to_string()
        }
    });
    let configured_inconsistency = configured_state.contains("marketplace-malformed")
        || configured_state.contains("marketplace-unreadable")
        || ((configured_state.starts_with("marketplace-entry;")
            || configured_state.contains("installed-enabled")
            || configured_state.contains("installed-disabled"))
            && observation.equivalence == "unavailable");
    let status = if configured_inconsistency
        || matches!(
            observation.equivalence.as_str(),
            "divergent" | "incomplete" | "unreadable"
        ) {
        "review-required"
    } else {
        "informational"
    };
    SkillSource {
        origin: origin.to_string(),
        scope: scope.to_string(),
        path: path.display().to_string(),
        configured_state,
        digest: observation.digest,
        embedded_equivalence: observation.equivalence,
        runtime_activation: "unknown",
        precedence: "host-defined",
        status: status.to_string(),
        remediation: (status == "review-required").then(|| remediation.to_string()),
    }
}

struct SkillSetObservation {
    digest: Option<String>,
    equivalence: String,
}

fn observe_skill_set(root: &Path, embedded_digest: &str) -> SkillSetObservation {
    if !root.is_dir() {
        return SkillSetObservation {
            digest: None,
            equivalence: "unavailable".to_string(),
        };
    }
    let mut hasher = Sha256::new();
    let mut complete = true;
    let mut readable = true;
    let mut present = 0usize;
    for (relative_path, _) in INIT_AGENT_SKILLS {
        hasher.update(relative_path.as_bytes());
        hasher.update([0]);
        match fs::read(root.join(relative_path)) {
            Ok(bytes) => {
                present += 1;
                hasher.update(bytes);
            }
            Err(error) => {
                complete = false;
                readable &= error.kind() == std::io::ErrorKind::NotFound;
                hasher.update(format!("<{}>", error.kind()).as_bytes());
            }
        }
        hasher.update([0xff]);
    }
    if present == 0 {
        return SkillSetObservation {
            digest: None,
            equivalence: "unavailable".to_string(),
        };
    }
    let digest = format!("sha256:{:x}", hasher.finalize());
    let equivalence = if complete && digest == embedded_digest {
        "equivalent"
    } else if !complete && readable {
        "incomplete"
    } else if !readable {
        "unreadable"
    } else {
        "divergent"
    };
    SkillSetObservation {
        digest: Some(digest),
        equivalence: equivalence.to_string(),
    }
}

fn embedded_skill_set_digest() -> String {
    let mut hasher = Sha256::new();
    for (relative_path, contents) in INIT_AGENT_SKILLS {
        hasher.update(relative_path.as_bytes());
        hasher.update([0]);
        hasher.update(contents.as_bytes());
        hasher.update([0xff]);
    }
    format!("sha256:{:x}", hasher.finalize())
}

fn marketplace_rms_plugin_root(marketplace_path: &Path) -> Option<PathBuf> {
    let source = fs::read_to_string(marketplace_path).ok()?;
    let value = serde_json::from_str::<JsonValue>(&source).ok()?;
    let relative = value
        .get("plugins")?
        .as_array()?
        .iter()
        .find(|plugin| plugin.get("name").and_then(JsonValue::as_str) == Some("rms"))?
        .get("source")?
        .get("path")?
        .as_str()?;
    Some(marketplace_source_root(marketplace_path).join(relative))
}

fn collect_agent_skill_files(root: &Path, path: &Path, output: &mut Vec<String>) -> Result<()> {
    if !path.exists() {
        return Ok(());
    }
    for entry in
        fs::read_dir(path).with_context(|| format!("failed to read `{}`", path.display()))?
    {
        let entry = entry?;
        let entry_path = entry.path();
        if entry_path.is_dir() {
            collect_agent_skill_files(root, &entry_path, output)?;
        } else if entry_path.file_name().and_then(|name| name.to_str()) == Some("SKILL.md") {
            if let Ok(relative) = entry_path.strip_prefix(root) {
                output.push(relative.display().to_string());
            }
        }
    }
    Ok(())
}

fn print_agent_integration_report(report: &AgentIntegrationReport) {
    println!("# RMS Agent Integration");
    println!();
    println!("Target: {}", report.target);
    println!("Root: {}", report.root);
    println!("Plugin required: {}", report.plugin_required);
    println!();

    println!("## Project Guidance");
    println!(
        "{}: {} ({})",
        report.agent_instructions.name,
        report.agent_instructions.status,
        report.agent_instructions.path
    );
    if let Some(target_instructions) = &report.target_instructions {
        println!(
            "{}: {} ({})",
            target_instructions.name, target_instructions.status, target_instructions.path
        );
    }
    println!(
        "local skills: {} ({}, expected {})",
        report.local_skills.status, report.local_skills.directory, report.local_skills.expected
    );
    print_string_list("missing skills", &report.local_skills.missing);
    print_string_list("drifted skills", &report.local_skills.drifted);
    print_string_list("extra skills", &report.local_skills.extra);
    println!();

    println!("## Detected RMS Skill Origins");
    println!(
        "Runtime activation: {}",
        report.skill_sources.runtime_activation
    );
    println!("Precedence: {}", report.skill_sources.precedence);
    for source in &report.skill_sources.sources {
        println!(
            "- {} scope={} configured={} equivalence={} status={} path={}",
            source.origin,
            source.scope,
            source.configured_state,
            source.embedded_equivalence,
            source.status,
            source.path
        );
        println!(
            "  digest={} runtime_activation={} precedence={}",
            source.digest.as_deref().unwrap_or("<none>"),
            source.runtime_activation,
            source.precedence
        );
        if let Some(remediation) = &source.remediation {
            println!("  remediation: {remediation}");
        }
    }
    println!();

    println!("## Workbench Config");
    println!("{}: {}", report.config.path, report.config.status);
    if let Some(message) = &report.config.message {
        println!("Message: {message}");
    }
    println!(
        "Default provider: {}",
        report
            .config
            .default_provider
            .as_deref()
            .unwrap_or("<none>")
    );
    println!(
        "Codex sandbox: {}",
        report
            .config
            .codex_sandbox
            .as_deref()
            .unwrap_or("read-only")
    );
    println!(
        "Codex write scope: {}",
        report
            .config
            .codex_write_scope
            .as_deref()
            .unwrap_or("<default>")
    );
    println!("Run directory: {}", report.config.run_directory);
    println!();

    println!("## Target Tool");
    if let Some(readiness) = &report.target_tool {
        print_command_readiness(readiness);
    }
    println!();

    println!("## Guidance");
    for item in &report.guidance {
        println!("- {item}");
    }
}

fn run_agent_plugin_diagnose(target: AgentTarget, marketplace_path: Option<&Path>) -> Result<()> {
    let report = build_agent_plugin_report(target, marketplace_path)?;
    print_agent_plugin_report(&report);
    Ok(())
}

fn run_agent_plugin_install(
    target: AgentTarget,
    marketplace_path: Option<&Path>,
    skip_codex_add: bool,
) -> Result<()> {
    ensure_agent_plugin_supported(target)?;
    let paths = agent_plugin_paths(marketplace_path)?;
    write_codex_plugin_package(&paths, true)?;
    ensure_personal_marketplace_entry(&paths)?;
    if !skip_codex_add {
        run_codex_plugin_add("rms", "personal")?;
        prune_stale_codex_plugin_cache()?;
    }
    let report = build_agent_plugin_report(target, Some(&paths.marketplace_path))?;
    print_agent_plugin_report(&report);
    Ok(())
}

fn run_agent_plugin_sync(
    target: AgentTarget,
    marketplace_path: Option<&Path>,
    skip_codex_add: bool,
) -> Result<()> {
    ensure_agent_plugin_supported(target)?;
    let paths = agent_plugin_paths(marketplace_path)?;
    write_codex_plugin_package(&paths, true)?;
    ensure_personal_marketplace_entry(&paths)?;
    if !skip_codex_add {
        run_codex_plugin_add("rms", "personal")?;
        prune_stale_codex_plugin_cache()?;
    }
    let report = build_agent_plugin_report(target, Some(&paths.marketplace_path))?;
    print_agent_plugin_report(&report);
    Ok(())
}

fn ensure_agent_plugin_supported(target: AgentTarget) -> Result<()> {
    match target {
        AgentTarget::Codex => Ok(()),
        AgentTarget::Claude => bail!(
            "Claude plugin installation is not implemented; use `rms agent init --target claude --root .` for project-local scaffolding"
        ),
    }
}

struct AgentPluginPaths {
    marketplace_path: PathBuf,
    plugin_root: PathBuf,
}

fn agent_plugin_paths(marketplace_path: Option<&Path>) -> Result<AgentPluginPaths> {
    let marketplace_path = match marketplace_path {
        Some(path) => expand_tilde(path),
        None => home_dir()?.join(".agents/plugins/marketplace.json"),
    };
    let marketplace_root = marketplace_source_root(&marketplace_path);
    Ok(AgentPluginPaths {
        plugin_root: marketplace_root.join("plugins/rms"),
        marketplace_path,
    })
}

fn marketplace_source_root(marketplace_path: &Path) -> PathBuf {
    let components = marketplace_path
        .components()
        .map(|component| component.as_os_str().to_string_lossy().to_string())
        .collect::<Vec<_>>();
    if components.len() >= 3
        && components[components.len() - 1] == "marketplace.json"
        && components[components.len() - 2] == "plugins"
        && components[components.len() - 3] == ".agents"
    {
        return marketplace_path
            .parent()
            .and_then(Path::parent)
            .and_then(Path::parent)
            .map(Path::to_path_buf)
            .unwrap_or_else(|| PathBuf::from("."));
    }
    marketplace_path
        .parent()
        .map(Path::to_path_buf)
        .unwrap_or_else(|| PathBuf::from("."))
}

fn expand_tilde(path: &Path) -> PathBuf {
    let raw = path.to_string_lossy();
    if raw == "~" {
        home_dir().unwrap_or_else(|_| PathBuf::from(raw.as_ref()))
    } else if let Some(rest) = raw.strip_prefix("~/") {
        home_dir()
            .map(|home| home.join(rest))
            .unwrap_or_else(|_| PathBuf::from(raw.as_ref()))
    } else {
        path.to_path_buf()
    }
}

fn home_dir() -> Result<PathBuf> {
    std::env::var_os("HOME")
        .map(PathBuf::from)
        .ok_or_else(|| anyhow!("HOME is not set; pass --marketplace-path explicitly"))
}

fn write_codex_plugin_package(paths: &AgentPluginPaths, overwrite: bool) -> Result<()> {
    if paths.plugin_root.exists() && overwrite {
        fs::remove_dir_all(&paths.plugin_root)
            .with_context(|| format!("failed to remove `{}`", paths.plugin_root.display()))?;
    }
    fs::create_dir_all(paths.plugin_root.join(".codex-plugin"))?;
    fs::create_dir_all(paths.plugin_root.join("skills"))?;
    fs::write(
        paths.plugin_root.join(".codex-plugin/plugin.json"),
        render_codex_plugin_manifest(),
    )
    .with_context(|| {
        format!(
            "failed to write `{}`",
            paths
                .plugin_root
                .join(".codex-plugin/plugin.json")
                .display()
        )
    })?;
    fs::write(paths.plugin_root.join("README.md"), CODEX_PLUGIN_README).with_context(|| {
        format!(
            "failed to write `{}`",
            paths.plugin_root.join("README.md").display()
        )
    })?;
    for (relative_path, contents) in INIT_AGENT_SKILLS {
        write_agent_file(
            &paths.plugin_root.join("skills").join(relative_path),
            contents,
            true,
        )?;
    }
    validate_generated_codex_plugin(&paths.plugin_root)?;
    Ok(())
}

fn render_codex_plugin_manifest() -> String {
    let version = format!(
        "{}+codex.{}",
        env!("CARGO_PKG_VERSION")
            .split('+')
            .next()
            .unwrap_or(env!("CARGO_PKG_VERSION")),
        plugin_cachebuster()
    );
    serde_json::to_string_pretty(&json!({
        "name": "rms",
        "version": version,
        "description": "Codex adapter for Reliable Modular Systems skills and workflows.",
        "author": {
            "name": "Reliable Modular Systems",
            "url": "https://github.com/reliable-modular-systems/reliable-modular-systems"
        },
        "homepage": "https://github.com/reliable-modular-systems/reliable-modular-systems",
        "repository": "https://github.com/reliable-modular-systems/reliable-modular-systems",
        "license": "Apache-2.0",
        "keywords": ["architecture", "modularity", "agents", "validation", "reliability"],
        "skills": "./skills/",
        "interface": {
            "displayName": "Reliable Modular Systems",
            "shortDescription": "Build software through explicit module contracts.",
            "longDescription": "RMS gives Codex bounded workflows for inspecting modules, implementing changes, pruning semantic residue, evolving contracts, composing modules, verifying conformance, and running replayable proof-first bug hunts against canonical manifests.",
            "developerName": "Reliable Modular Systems",
            "category": "Developer Tools",
            "capabilities": ["Code", "Review", "Workflow"],
            "defaultPrompt": [
                "Inspect this RMS module before changing it.",
                "Implement this change within the owning module.",
                "Prune semantic residue from this module without changing public behavior.",
                "Verify this module against its RMS contracts.",
                "Find and replay bugs with the risk-derived RMS hunt lanes."
            ],
            "brandColor": "#2563EB"
        }
    }))
    .unwrap_or_else(|_| "{}".to_string())
        + "\n"
}

fn plugin_cachebuster() -> String {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_secs().to_string())
        .unwrap_or_else(|_| "0".to_string())
}

fn validate_generated_codex_plugin(plugin_root: &Path) -> Result<()> {
    let manifest_path = plugin_root.join(".codex-plugin/plugin.json");
    let manifest_source = fs::read_to_string(&manifest_path)
        .with_context(|| format!("failed to read `{}`", manifest_path.display()))?;
    let manifest: JsonValue = serde_json::from_str(&manifest_source)
        .with_context(|| format!("failed to parse `{}`", manifest_path.display()))?;
    for field in ["name", "version", "description", "skills", "interface"] {
        if manifest.get(field).is_none() {
            bail!("generated Codex plugin manifest missing `{field}`");
        }
    }
    if manifest.get("skills").and_then(JsonValue::as_str) != Some("./skills/") {
        bail!("generated Codex plugin manifest must use skills path `./skills/`");
    }
    for (relative_path, contents) in INIT_AGENT_SKILLS {
        let actual = fs::read_to_string(plugin_root.join("skills").join(relative_path))
            .with_context(|| format!("failed to read generated plugin skill `{relative_path}`"))?;
        if actual != *contents {
            bail!("generated plugin skill `{relative_path}` drifted from embedded RMS skill");
        }
    }
    Ok(())
}

fn ensure_personal_marketplace_entry(paths: &AgentPluginPaths) -> Result<()> {
    if let Some(parent) = paths.marketplace_path.parent() {
        fs::create_dir_all(parent)?;
    }
    let mut marketplace = if paths.marketplace_path.exists() {
        let source = fs::read_to_string(&paths.marketplace_path)
            .with_context(|| format!("failed to read `{}`", paths.marketplace_path.display()))?;
        serde_json::from_str::<JsonValue>(&source)
            .with_context(|| format!("failed to parse `{}`", paths.marketplace_path.display()))?
    } else {
        json!({
            "name": "personal",
            "interface": { "displayName": "Personal" },
            "plugins": []
        })
    };

    if marketplace
        .get("name")
        .and_then(JsonValue::as_str)
        .is_none()
    {
        marketplace["name"] = JsonValue::String("personal".to_string());
    }
    if marketplace
        .get("interface")
        .and_then(JsonValue::as_object)
        .is_none()
    {
        marketplace["interface"] = json!({ "displayName": "Personal" });
    }
    if marketplace
        .get("plugins")
        .and_then(JsonValue::as_array)
        .is_none()
    {
        marketplace["plugins"] = JsonValue::Array(Vec::new());
    }
    let plugins = marketplace
        .get_mut("plugins")
        .and_then(JsonValue::as_array_mut)
        .ok_or_else(|| anyhow!("marketplace plugins must be an array"))?;
    let entry = json!({
        "name": "rms",
        "source": {
            "source": "local",
            "path": "./plugins/rms"
        },
        "policy": {
            "installation": "AVAILABLE",
            "authentication": "ON_INSTALL"
        },
        "category": "Developer Tools"
    });
    if let Some(existing) = plugins
        .iter_mut()
        .find(|plugin| plugin.get("name").and_then(JsonValue::as_str) == Some("rms"))
    {
        *existing = entry;
    } else {
        plugins.push(entry);
    }
    fs::write(
        &paths.marketplace_path,
        serde_json::to_string_pretty(&marketplace)? + "\n",
    )
    .with_context(|| format!("failed to write `{}`", paths.marketplace_path.display()))?;
    Ok(())
}

fn run_codex_plugin_add(plugin_name: &str, marketplace_name: &str) -> Result<()> {
    let status = Command::new("codex")
        .args([
            "plugin",
            "add",
            &format!("{plugin_name}@{marketplace_name}"),
        ])
        .status()
        .with_context(|| "failed to start `codex plugin add`")?;
    if !status.success() {
        bail!("`codex plugin add {plugin_name}@{marketplace_name}` failed");
    }
    Ok(())
}

fn build_agent_plugin_report(
    target: AgentTarget,
    marketplace_path: Option<&Path>,
) -> Result<AgentPluginReport> {
    let paths = agent_plugin_paths(marketplace_path)?;
    let marketplace_status = match marketplace_plugin_presence(&paths.marketplace_path, "rms") {
        MarketplacePluginPresence::Present => "present",
        MarketplacePluginPresence::MissingEntry => "missing-entry",
        MarketplacePluginPresence::Missing => "missing",
        MarketplacePluginPresence::Malformed => "malformed",
        MarketplacePluginPresence::Unreadable => "unreadable",
    };
    let plugin_status = if validate_generated_codex_plugin(&paths.plugin_root).is_ok() {
        "present"
    } else if paths.plugin_root.exists() {
        "invalid"
    } else {
        "missing"
    };
    let installed_status = if marketplace_path.is_some() {
        codex_plugin_installed_status_at_home(
            &marketplace_source_root(&paths.marketplace_path),
            "rms",
            "personal",
        )
    } else {
        codex_plugin_installed_status("rms", "personal")
    };
    let mut guidance = vec![
        "Project-local RMS guidance remains sufficient; plugin installation is optional.".to_string(),
        "Use `rms agent plugin install --target codex` to write the personal plugin and run `codex plugin add rms@personal`.".to_string(),
        "Use `rms agent plugin sync --target codex` after upgrading RMS so Codex sees refreshed skills.".to_string(),
        "Start a new Codex thread after plugin install or sync to load updated skills.".to_string(),
    ];
    if target != AgentTarget::Codex {
        guidance.push("Only Codex plugin packaging is currently implemented.".to_string());
    }
    Ok(AgentPluginReport {
        target: target.label().to_string(),
        plugin_required: false,
        marketplace_path: paths.marketplace_path.display().to_string(),
        marketplace_status: marketplace_status.to_string(),
        plugin_root: paths.plugin_root.display().to_string(),
        plugin_status: plugin_status.to_string(),
        installed_status,
        cache: codex_plugin_cache_readiness(),
        target_tool: target.target_tool(),
        guidance,
    })
}

fn codex_plugin_cache_readiness() -> CodexPluginCacheReadiness {
    let directory = match home_dir() {
        Ok(home) => home.join(".codex/plugins/cache/personal/rms"),
        Err(_) => PathBuf::from("<HOME-unavailable>"),
    };
    let mut matching_versions = Vec::new();
    let mut stale_versions = Vec::new();
    if !directory.is_dir() {
        return CodexPluginCacheReadiness {
            directory: directory.display().to_string(),
            status: "missing".to_string(),
            matching_versions,
            stale_versions,
        };
    }
    let Ok(entries) = fs::read_dir(&directory) else {
        return CodexPluginCacheReadiness {
            directory: directory.display().to_string(),
            status: "unreadable".to_string(),
            matching_versions,
            stale_versions,
        };
    };
    for entry in entries.filter_map(Result::ok) {
        let path = entry.path();
        if !path.is_dir() {
            continue;
        }
        let version = path
            .file_name()
            .and_then(|name| name.to_str())
            .unwrap_or("<unknown>")
            .to_string();
        if codex_plugin_cached_skills_match_embedded(&path) {
            matching_versions.push(version);
        } else {
            stale_versions.push(version);
        }
    }
    matching_versions.sort();
    stale_versions.sort();
    let status = match (matching_versions.is_empty(), stale_versions.is_empty()) {
        (true, true) => "missing",
        (false, true) => "present",
        (false, false) => "mixed",
        (true, false) => "stale",
    };
    CodexPluginCacheReadiness {
        directory: directory.display().to_string(),
        status: status.to_string(),
        matching_versions,
        stale_versions,
    }
}

fn prune_stale_codex_plugin_cache() -> Result<()> {
    prune_stale_codex_plugin_cache_at(&home_dir()?)
}

fn prune_stale_codex_plugin_cache_at(home: &Path) -> Result<()> {
    let cache_root = home.join(".codex/plugins/cache/personal/rms");
    if !cache_root.is_dir() {
        return Ok(());
    }
    for entry in fs::read_dir(&cache_root)? {
        let entry = entry?;
        if !entry.file_type()?.is_dir() {
            continue;
        }
        if !codex_plugin_cached_skills_match_embedded(&entry.path()) {
            fs::remove_dir_all(entry.path()).with_context(|| {
                format!(
                    "failed to remove stale RMS-owned plugin cache `{}`",
                    entry.path().display()
                )
            })?;
        }
    }
    Ok(())
}

fn codex_plugin_cached_skills_match_embedded(cache_version_root: &Path) -> bool {
    let Ok(actual) = collect_distribution_files(&cache_version_root.join("skills")) else {
        return false;
    };
    let expected = INIT_AGENT_SKILLS
        .iter()
        .map(|(relative_path, contents)| {
            (PathBuf::from(relative_path), contents.as_bytes().to_vec())
        })
        .collect::<BTreeMap<_, _>>();
    actual == expected
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum MarketplacePluginPresence {
    Present,
    MissingEntry,
    Missing,
    Malformed,
    Unreadable,
}

fn marketplace_plugin_presence(marketplace_path: &Path, name: &str) -> MarketplacePluginPresence {
    let source = match fs::read_to_string(marketplace_path) {
        Ok(source) => source,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            return MarketplacePluginPresence::Missing;
        }
        Err(_) => return MarketplacePluginPresence::Unreadable,
    };
    let value = match serde_json::from_str::<JsonValue>(&source) {
        Ok(value) => value,
        Err(_) => return MarketplacePluginPresence::Malformed,
    };
    let Some(plugins) = value.get("plugins").and_then(JsonValue::as_array) else {
        return MarketplacePluginPresence::Malformed;
    };
    if plugins
        .iter()
        .any(|plugin| plugin.get("name").and_then(JsonValue::as_str) == Some(name))
    {
        MarketplacePluginPresence::Present
    } else {
        MarketplacePluginPresence::MissingEntry
    }
}

fn codex_plugin_installed_status(plugin_name: &str, marketplace_name: &str) -> String {
    let Ok(home) = home_dir() else {
        return "unknown".to_string();
    };
    codex_plugin_installed_status_at_home(&home, plugin_name, marketplace_name)
}

fn codex_plugin_installed_status_at_home(
    home: &Path,
    plugin_name: &str,
    marketplace_name: &str,
) -> String {
    let config_path = home.join(".codex/config.toml");
    let Ok(config) = load_toml(&config_path) else {
        return "unknown".to_string();
    };
    let key = format!("{plugin_name}@{marketplace_name}");
    let enabled = config
        .get("plugins")
        .and_then(TomlValue::as_table)
        .and_then(|plugins| plugins.get(&key))
        .and_then(TomlValue::as_table)
        .and_then(|plugin| plugin.get("enabled"))
        .and_then(TomlValue::as_bool);
    match enabled {
        Some(true) => "installed-enabled".to_string(),
        Some(false) => "installed-disabled".to_string(),
        None => "not-installed".to_string(),
    }
}

fn print_agent_plugin_report(report: &AgentPluginReport) {
    println!("# RMS Agent Plugin");
    println!();
    println!("Target: {}", report.target);
    println!("Plugin required: {}", report.plugin_required);
    println!();
    println!("## Codex Plugin");
    println!(
        "marketplace: {} ({})",
        report.marketplace_status, report.marketplace_path
    );
    println!(
        "plugin package: {} ({})",
        report.plugin_status, report.plugin_root
    );
    println!("installed: {}", report.installed_status);
    println!(
        "cache: {} ({})",
        report.cache.status, report.cache.directory
    );
    print_string_list("matching cache versions", &report.cache.matching_versions);
    print_string_list("stale cache versions", &report.cache.stale_versions);
    if report.cache.status == "stale" || report.cache.status == "mixed" {
        println!("Fix: run `rms agent plugin sync --target codex`, then start a new Codex thread.");
    }
    print_command_readiness(&report.target_tool);
    println!();
    println!("## Guidance");
    for item in &report.guidance {
        println!("- {item}");
    }
}

fn run_release_check(root: &Path, skip_cargo_package: bool) -> Result<()> {
    println!("# RMS Release Check");
    println!();
    println!("Root: {}", root.display());
    println!();

    let rms_exe = std::env::current_exe().with_context(|| "failed to locate current rms binary")?;
    let source_revision = source_revision(root).unwrap_or_else(|| "uncommitted".to_string());
    let input_digest = release_input_digest(root, skip_cargo_package)?;
    let tool_digest = release_tool_digest(&rms_exe)?;
    let phase_count = if skip_cargo_package { 12 } else { 13 };
    let mut session = verification::VerificationSession::acquire(
        root,
        "release-check",
        &source_revision,
        &input_digest,
        &tool_digest,
        None,
        phase_count,
    )?;
    eprintln!("verification run identity: {}", session.identity());

    session.run_phase("metadata", "release metadata", || {
        run_release_metadata_check(root)
    })?;
    session.run_phase("format", "cargo fmt", || {
        run_release_step(
            "cargo fmt",
            command_with_args("cargo", &["fmt", "--all", "--check"], root),
        )
    })?;
    session.run_phase("native-tests", "cargo test --workspace --locked", || {
        run_release_step(
            "cargo test",
            command_with_args("cargo", &["test", "--workspace", "--locked"], root),
        )
    })?;
    session.run_phase("canonical-validate", "rms validate", || {
        run_release_step(
            "rms validate",
            command_with_args(
                &rms_exe,
                &["validate", "--root", root.to_string_lossy().as_ref()],
                root,
            ),
        )
    })?;
    session.run_phase("canonical-verify", "rms verify rms-cli", || {
        run_release_step(
            "rms verify rms-cli",
            command_with_args(
                &rms_exe,
                &["verify", "tooling/rust/rms/implementation.yaml"],
                root,
            ),
        )
    })?;
    session.run_phase("example-composition", "compose and verify examples", || {
        run_release_step(
            "rms compose examples/minimal",
            command_with_args(&rms_exe, &["compose", "--root", "examples/minimal"], root),
        )?;
        run_release_step(
            "rms compose examples/rust",
            command_with_args(&rms_exe, &["compose", "--root", "examples/rust"], root),
        )?;
        run_release_step(
            "rms compose examples/swift",
            command_with_args(&rms_exe, &["compose", "--root", "examples/swift"], root),
        )?;
        run_release_step(
            "rms compose examples/python",
            command_with_args(&rms_exe, &["compose", "--root", "examples/python"], root),
        )?;
        let mut verify_python = command_with_args(
            &rms_exe,
            &["verify", "examples/python/implementation.yaml"],
            root,
        );
        verify_python.env("PYTHONDONTWRITEBYTECODE", "1");
        run_release_step("rms verify examples/python", verify_python)?;
        run_release_step(
            "rms compose examples/tic-tac-toe",
            command_with_args(
                &rms_exe,
                &["compose", "--root", "examples/tic-tac-toe"],
                root,
            ),
        )
    })?;
    session.run_phase("compatibility", "rms check-compat smoke", || {
        run_release_step(
            "rms check-compat smoke",
            command_with_args(
                &rms_exe,
                &[
                    "check-compat",
                    "examples/rust/module.yaml",
                    "examples/rust/module.yaml",
                ],
                root,
            ),
        )
    })?;
    session.run_phase("package-smoke", "RMS package smoke", || {
        run_release_package_smoke(root, &rms_exe)
    })?;
    session.run_phase("scaffold-roundtrip", "RMS scaffold roundtrip", || {
        run_release_scaffold_roundtrip(root, &rms_exe)
    })?;
    session.run_phase("example-tests", "example binding tests", || {
        run_release_step(
            "example Rust binding tests",
            command_with_args(
                "cargo",
                &[
                    "test",
                    "--manifest-path",
                    "examples/rust/Cargo.toml",
                    "--locked",
                ],
                root,
            ),
        )?;
        let mut python_tests = command_with_args(
            "python",
            &["-m", "unittest", "discover", "-s", "tests"],
            &root.join("examples/python"),
        );
        python_tests.env("PYTHONDONTWRITEBYTECODE", "1");
        run_release_step("example Python binding tests", python_tests)
    })?;
    session.run_phase("release-binary", "release binary smoke", || {
        run_release_binary_smoke(root)
    })?;
    if !skip_cargo_package {
        session.run_phase("cargo-package", "cargo package", || {
            run_release_step(
                "cargo package",
                command_with_args(
                    "cargo",
                    &[
                        "package",
                        "--manifest-path",
                        "tooling/rust/rms/Cargo.toml",
                        "--allow-dirty",
                        "--no-verify",
                    ],
                    root,
                ),
            )
        })?;
    }
    session.run_phase("plugin", "Codex plugin distribution", || {
        run_release_plugin_check(root, &release_binary_path(root))
    })?;

    println!();
    println!("pass: release check");
    Ok(())
}

fn release_input_digest(root: &Path, skip_cargo_package: bool) -> Result<String> {
    let mut digest = Sha256::new();
    digest.update(if skip_cargo_package {
        b"skip-cargo-package".as_slice()
    } else {
        b"include-cargo-package".as_slice()
    });
    let mut files = git_release_input_files(root).unwrap_or_else(|| walk_release_input_files(root));
    files.sort();
    for path in files {
        let relative = path.strip_prefix(root).unwrap_or(&path);
        digest.update(relative.to_string_lossy().as_bytes());
        digest.update([0]);
        digest.update(
            fs::read(&path)
                .with_context(|| format!("failed to hash release input `{}`", path.display()))?,
        );
        digest.update([0]);
    }
    Ok(format!("{:x}", digest.finalize()))
}

fn git_release_input_files(root: &Path) -> Option<Vec<PathBuf>> {
    let output = Command::new("git")
        .args(["-C"])
        .arg(root)
        .args([
            "ls-files",
            "-z",
            "--cached",
            "--others",
            "--exclude-standard",
        ])
        .output()
        .ok()?;
    if !output.status.success() {
        return None;
    }
    let paths = String::from_utf8(output.stdout).ok()?;
    Some(
        paths
            .split('\0')
            .filter(|path| !path.is_empty())
            .map(Path::new)
            .filter(|path| !release_input_path_is_excluded(path))
            .map(|path| root.join(path))
            .filter(|path| path.is_file())
            .collect(),
    )
}

fn walk_release_input_files(root: &Path) -> Vec<PathBuf> {
    WalkDir::new(root)
        .follow_links(false)
        .into_iter()
        .filter_entry(|entry| {
            entry.depth() == 0
                || !entry.file_type().is_dir()
                || !release_input_name_is_excluded(entry.file_name().to_str())
        })
        .filter_map(std::result::Result::ok)
        .filter(|entry| entry.file_type().is_file())
        .map(|entry| entry.into_path())
        .collect()
}

fn release_input_path_is_excluded(path: &Path) -> bool {
    path.parent().is_some_and(|parent| {
        parent
            .components()
            .any(|component| release_input_name_is_excluded(component.as_os_str().to_str()))
    })
}

fn release_input_name_is_excluded(name: Option<&str>) -> bool {
    matches!(
        name,
        Some(".git")
            | Some(".rms")
            | Some("target")
            | Some(".build")
            | Some("build")
            | Some("dist")
            | Some("node_modules")
            | Some("__pycache__")
            | Some(".pytest_cache")
            | Some(".swiftpm")
    )
}

fn release_tool_digest(rms_exe: &Path) -> Result<String> {
    let mut digest = Sha256::new();
    digest.update(
        fs::read(rms_exe)
            .with_context(|| format!("failed to hash RMS executable `{}`", rms_exe.display()))?,
    );
    for (program, args) in [
        ("cargo", &["--version"][..]),
        ("rustc", &["--version"][..]),
        ("swift", &["--version"][..]),
        ("python", &["--version"][..]),
        ("node", &["--version"][..]),
    ] {
        digest.update(program.as_bytes());
        match Command::new(program).args(args).output() {
            Ok(output) => {
                digest.update(output.stdout);
                digest.update(output.stderr);
                digest.update(output.status.code().unwrap_or(-1).to_le_bytes());
            }
            Err(error) => digest.update(error.to_string().as_bytes()),
        }
        digest.update([0]);
    }
    Ok(format!("{:x}", digest.finalize()))
}

fn proof_cache_for_root(project_root: &Path) -> Result<verification::ProofCache> {
    let input_digest = release_input_digest(project_root, false)?;
    let executable = std::env::current_exe()?;
    let tool_digest = release_tool_digest(&executable)?;
    let seed = std::env::var("RMS_PROPERTY_SEED")
        .ok()
        .and_then(|value| value.parse::<u64>().ok());
    verification::ProofCache::new(project_root, &input_digest, &tool_digest, seed)
}

fn run_release_metadata_check(root: &Path) -> Result<()> {
    println!("## release metadata");
    validate_release_metadata(root)?;
    validate_command_surface()?;
    println!("pass");
    println!();
    Ok(())
}

fn validate_command_surface() -> Result<()> {
    let primary = render_primary_help();
    ensure_document_markers(
        "default command help",
        &primary,
        &[
            "\n  init ",
            "\n  next ",
            "\n  explain ",
            "\n  check ",
            "\n  view ",
            "\n  help ",
        ],
    )?;
    for specialist in COMMAND_GROUPS
        .iter()
        .filter(|(group, _)| !matches!(*group, "Primary" | "Meta"))
        .flat_map(|(_, commands)| commands.iter().copied())
    {
        if primary.contains(&format!("\n  {specialist} ")) {
            bail!("default command help exposes specialist command `{specialist}`");
        }
    }

    let all = render_all_help()?;
    for (group, commands) in COMMAND_GROUPS {
        if !all.contains(&format!("\n{group}:\n")) {
            bail!("complete command help is missing group `{group}`");
        }
        for command in *commands {
            if all.matches(&format!("  {command:<18} ")).count() != 1 {
                bail!("complete command help must list `{command}` exactly once");
            }
        }
    }
    Ok(())
}

fn run_release_design_scaffold(
    root: &Path,
    rms_exe: &Path,
    app: &Path,
    label: &str,
    task: &str,
    intent_model: &str,
) -> Result<()> {
    let app_arg = app.to_string_lossy().to_string();
    let design_output = run_release_step_capture(
        &format!("{label} design"),
        command_with_args(
            rms_exe,
            &[
                "design",
                "--root",
                app_arg.as_str(),
                "--task",
                task,
                "--intent-json",
                intent_model,
                "--json",
            ],
            root,
        ),
    )?;
    let design: JsonValue = serde_json::from_str(&design_output)
        .with_context(|| format!("{label} design did not return JSON"))?;
    if design.get("result").and_then(JsonValue::as_str) != Some("ready") {
        bail!("{label} design did not return a ready result");
    }
    let receipt = design
        .get("run_id")
        .and_then(JsonValue::as_str)
        .ok_or_else(|| anyhow!("{label} design omitted run_id"))?;
    let mut scaffold_args = design
        .get("decision")
        .and_then(|value| value.get("scaffold"))
        .and_then(|value| value.get("args"))
        .and_then(JsonValue::as_array)
        .ok_or_else(|| anyhow!("{label} design omitted scaffold args"))?
        .iter()
        .map(|value| {
            value
                .as_str()
                .map(ToString::to_string)
                .ok_or_else(|| anyhow!("{label} scaffold argument is not a string"))
        })
        .collect::<Result<Vec<_>>>()?;
    scaffold_args.extend([
        "--root".to_string(),
        app_arg,
        "--route-receipt".to_string(),
        receipt.to_string(),
    ]);
    let scaffold_arg_refs = scaffold_args.iter().map(String::as_str).collect::<Vec<_>>();
    run_release_step(label, command_with_args(rms_exe, &scaffold_arg_refs, app))
}

