fn run_release_binary_smoke(root: &Path) -> Result<()> {
    run_release_step(
        "release binary build",
        command_with_args(
            "cargo",
            &["build", "--release", "-p", "rms", "--locked"],
            root,
        ),
    )?;

    let binary = release_binary_path(root);
    if !binary.exists() {
        bail!("release binary smoke missing `{}`", binary.display());
    }

    for command in ["init", "next", "explain", "check", "view"] {
        run_release_step(
            &format!("release binary {command} help"),
            command_with_args(&binary, &[command, "--help"], root),
        )?;
    }
    run_release_step(
        "release binary complete command help",
        command_with_args(&binary, &["help", "--all"], root),
    )?;

    run_release_step(
        "release binary diagnose",
        command_with_args(&binary, &["diagnose", "--root", ".", "--json"], root),
    )?;
    let untyped_next = run_release_step_expect_status(
        "release binary untyped next",
        command_with_args(
            &binary,
            &[
                "next",
                "inspect RMS readiness",
                "--root",
                ".",
                "--module",
                "tooling/rust/rms/module.yaml",
                "--json",
            ],
            root,
        ),
        2,
    )?;
    ensure_output_contains(
        "release binary untyped next",
        &untyped_next,
        "intent-model-required",
    )?;
    run_release_step(
        "release binary explain",
        command_with_args(
            &binary,
            &[
                "explain",
                "what public behavior is declared?",
                "--root",
                ".",
                "--module",
                "tooling/rust/rms/module.yaml",
                "--json",
            ],
            root,
        ),
    )?;
    run_release_step(
        "release binary project check",
        command_with_args(&binary, &["check", "--root", ".", "--json"], root),
    )?;
    run_release_step(
        "release binary validate minimal",
        command_with_args(&binary, &["validate", "--root", "examples/minimal"], root),
    )?;
    run_release_install_smoke(root, &binary)?;
    run_release_clean_room_dogfood(root, &binary)?;
    Ok(())
}

fn release_binary_path(root: &Path) -> PathBuf {
    root.join("target")
        .join("release")
        .join(format!("rms{}", std::env::consts::EXE_SUFFIX))
}

fn run_release_install_smoke(root: &Path, binary: &Path) -> Result<()> {
    let temp = std::env::temp_dir().join(format!(
        "rms-release-install-{}-{}",
        std::process::id(),
        SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|duration| duration.as_secs())
            .unwrap_or(0)
    ));
    let bin_dir = temp.join("bin");
    fs::create_dir_all(&bin_dir)
        .with_context(|| format!("failed to create `{}`", bin_dir.display()))?;
    let installed_binary = bin_dir.join(format!("rms{}", std::env::consts::EXE_SUFFIX));
    fs::copy(binary, &installed_binary).with_context(|| {
        format!(
            "failed to copy `{}` to `{}`",
            binary.display(),
            installed_binary.display()
        )
    })?;
    make_executable(&installed_binary)?;

    let result = (|| -> Result<()> {
        for command in ["init", "next", "explain", "check", "view"] {
            run_release_step(
                &format!("clean-room installed binary {command} help"),
                command_with_path("rms", &[command, "--help"], root, &bin_dir)?,
            )?;
        }
        run_release_step(
            "clean-room installed binary complete command help",
            command_with_path("rms", &["help", "--all"], root, &bin_dir)?,
        )?;
        run_release_step(
            "clean-room installed binary diagnose",
            command_with_path(
                "rms",
                &["diagnose", "--root", ".", "--json"],
                root,
                &bin_dir,
            )?,
        )?;
        run_release_step(
            "clean-room installed binary validate minimal",
            command_with_path(
                "rms",
                &["validate", "--root", "examples/minimal"],
                root,
                &bin_dir,
            )?,
        )?;
        let next_args = release_install_next_args();
        run_release_step(
            "clean-room installed binary next",
            command_with_path("rms", &next_args, root, &bin_dir)?,
        )?;
        let mut detailed_next_args = next_args.to_vec();
        detailed_next_args.push("--details");
        run_release_step(
            "clean-room installed binary detailed next",
            command_with_path("rms", &detailed_next_args, root, &bin_dir)?,
        )?;
        Ok(())
    })();

    let _ = fs::remove_dir_all(&temp);
    result
}

