fn render_js_effect_executor_mjs(names: &InnerStructureNames) -> String {
    format!(
        r#"import {{ make{effect_result}Failed, make{effect_result}Succeeded }} from "./representation.mjs";

export function executeEffect(effect) {{
  if (effect?.tag === "{effect}.Execute") {{
    return make{effect_result}Succeeded();
  }}
  return make{effect_result}Failed("unknown-effect");
}}
"#,
        effect = names.effect,
        effect_result = names.effect_result,
    )
}

fn render_js_machine_driver_mjs(names: &InnerStructureNames) -> String {
    format!(
        r#"import {{ executeEffect }} from "./effect_executor.mjs";
import {{ make{input}EffectResult }} from "./representation.mjs";
import {{ transitionRecord }} from "./transition.mjs";

export function driveMachine(initialState, initialInput) {{
  let state = initialState;
  const pending = [initialInput];
  const records = [];
  while (pending.length > 0) {{
    const input = pending.shift();
    const record = transitionRecord(state, input);
    state = record.state_after;
    records.push(record);
    for (const effect of record.output.effects) {{
      pending.push(make{input}EffectResult(executeEffect(effect)));
    }}
  }}
  return Object.freeze(records);
}}
"#,
        input = names.input,
    )
}

fn render_js_transition_mjs(model: &BindingScaffoldModel) -> String {
    let names = &model.names;
    let states = starter_states_for_shape(model.shape);
    let initial = states.first().map(String::as_str).unwrap_or("Ready");
    let completed = states
        .iter()
        .find(|state| state.as_str() == "Completed")
        .map(String::as_str)
        .unwrap_or(initial);
    let rejected = states
        .iter()
        .find(|state| matches!(state.as_str(), "Rejected" | "Failed"))
        .map(String::as_str)
        .unwrap_or(initial);
    let waiting = states
        .iter()
        .find(|state| state.as_str() == "WaitingForEffect")
        .map(String::as_str)
        .unwrap_or(completed);
    let mut imports = vec![
        initial.to_string(),
        completed.to_string(),
        rejected.to_string(),
        format!("make{}Accepted", names.event),
        format!("make{}Rejected", names.event),
        format!("make{}InvalidCommand", names.rejection),
        format!("make{}IllegalTransition", names.rejection),
        format!("make{}Accepted", names.reply),
    ];
    if model.declares_effects {
        imports.extend([
            waiting.to_string(),
            format!("make{}EffectRequested", names.event),
            format!("make{}EffectCompleted", names.event),
            format!("make{}Execute", names.effect),
        ]);
    }
    imports.sort();
    imports.dedup();
    let imports = imports
        .iter()
        .map(|name| format!("  {name},"))
        .collect::<Vec<_>>()
        .join("\n");

    if !model.stateful() {
        return format!(
            r#"import {{
{imports}
}} from "./representation.mjs";

export function transition(command) {{
  return transitionRecord(command).output;
}}

export function transitionRecord(command) {{
  const stateBefore = {initial};
  let reply;
  let rejectionValue;
  let event;
  let branch;
  if (command?.tag === "{command}.Accept") {{
    reply = make{reply}Accepted();
    rejectionValue = null;
    event = make{event}Accepted();
    branch = "Accept";
  }} else {{
    const rejection = make{rejection}InvalidCommand(command?.reason);
    reply = null;
    rejectionValue = rejection;
    event = make{event}Rejected(rejection);
    branch = "Reject";
  }}
  const output = Object.freeze({{
    tag: "{transition}", next_state: {initial}, events: Object.freeze([event]),
    commands: Object.freeze([]), effects: Object.freeze([]), reply, rejection: rejectionValue,
  }});
  return Object.freeze({{
    tag: "{transition_record}", state_before: stateBefore, state_after: {initial}, input: command, output,
    source: Object.freeze({{ tag: "{source_provenance}", file: "src/transition.mjs", function: "transitionRecord", branch }}),
  }});
}}

export function replayTrace(commands) {{ return commands.map(transitionRecord); }}

export function generate_property_cases() {{
  return Object.freeze(Array.from({{ length: 64 }}, (_, index) => `generated-case-${{index}}`));
}}

export function generate_malformed_input_cases() {{
  return Object.freeze(Array.from({{ length: 64 }}, (_, width) => " ".repeat(width)));
}}

export const {machine} = Object.freeze({{ transition, transitionRecord, replayTrace }});
"#,
            imports = imports,
            initial = initial,
            command = names.command,
            reply = names.reply,
            event = names.event,
            rejection = names.rejection,
            transition = names.transition,
            transition_record = names.transition_record,
            source_provenance = names.source_provenance,
            machine = names.machine,
        );
    }

    let accept_body = if model.declares_effects {
        format!(
            "nextState = {waiting};\n      events = [make{event}EffectRequested()];\n      effects = [make{effect}Execute(command.label)];\n      reply = null;",
            event = names.event,
            effect = names.effect,
        )
    } else {
        format!(
            "nextState = {completed};\n      events = [make{event}Accepted()];\n      effects = [];\n      reply = make{reply}Accepted();",
            event = names.event,
            reply = names.reply,
        )
    };
    let result_branches = if model.declares_effect_results {
        format!(
            r#" else if (state?.tag === "{state}.{waiting}" && input?.tag === "{input}.EffectResult" && input.effect_result?.tag === "{effect_result}.Succeeded") {{
    nextState = {waiting_success};
    events = [make{event}EffectCompleted()];
    effects = [];
    reply = make{reply}Accepted();
    rejectionValue = null;
    branch = "Succeeded";
  }} else if (state?.tag === "{state}.{waiting}" && input?.tag === "{input}.EffectResult" && input.effect_result?.tag === "{effect_result}.Failed") {{
    const rejection = make{rejection}InvalidCommand(input.effect_result.reason);
    nextState = {rejected};
    events = [make{event}Rejected(rejection)];
    effects = [];
    reply = null;
    rejectionValue = rejection;
    branch = "Failed";
  }}"#,
            state = names.state,
            waiting = waiting,
            input = names.input,
            effect_result = names.effect_result,
            waiting_success = completed,
            event = names.event,
            reply = names.reply,
            rejection = names.rejection,
            rejected = rejected,
        )
    } else {
        String::new()
    };
    let observed_branch = if !model.declared_observed_events().is_empty() {
        format!(
            r#" else if (state?.tag === "{state}.{initial}" && input?.tag === "{input}.ObservedEvent") {{
    nextState = {completed};
    events = [make{event}Accepted()];
    effects = [];
    reply = make{reply}Accepted();
    rejectionValue = null;
    branch = "Observed";
  }}"#,
            input = names.input,
            state = names.state,
            initial = initial,
            event = names.event,
            reply = names.reply,
        )
    } else {
        String::new()
    };
    format!(
        r#"import {{
{imports}
}} from "./representation.mjs";

export function transition(state, input) {{
  return transitionRecord(state, input).output;
}}

export function transitionRecord(state, input) {{
  let nextState;
  let events;
  let effects;
  let reply;
  let rejectionValue;
  let branch;
  if (state?.tag === "{state}.{initial}" && input?.tag === "{input}.Command" && input.command?.tag === "{command}.Accept") {{
    const command = input.command;
    {accept_body}
    rejectionValue = null;
    branch = "Accept";
  }} else if (state?.tag === "{state}.{initial}" && input?.tag === "{input}.Command" && input.command?.tag === "{command}.Reject") {{
    const rejection = make{rejection}InvalidCommand(input.command.reason);
    nextState = {rejected};
    events = [make{event}Rejected(rejection)];
    effects = [];
    reply = null;
    rejectionValue = rejection;
    branch = "Reject";
  }}{result_branches}{observed_branch} else {{
    const rejection = make{rejection}IllegalTransition();
    nextState = state;
    events = [make{event}Rejected(rejection)];
    effects = [];
    reply = null;
    rejectionValue = rejection;
    branch = "IllegalTransition";
  }}
  const output = Object.freeze({{
    tag: "{transition}", next_state: nextState, events: Object.freeze(events),
    commands: Object.freeze([]), effects: Object.freeze(effects), reply, rejection: rejectionValue,
  }});
  return Object.freeze({{
    tag: "{transition_record}", state_before: state, state_after: nextState, input, output,
    source: Object.freeze({{ tag: "{source_provenance}", file: "src/transition.mjs", function: "transitionRecord", branch }}),
  }});
}}

export function replayTrace(initialState, inputs) {{
  let state = initialState;
  return inputs.map((input) => {{
    const record = transitionRecord(state, input);
    state = record.state_after;
    return record;
  }});
}}

export function generate_property_cases() {{
  return Object.freeze(Array.from({{ length: 64 }}, (_, index) => `generated-case-${{index}}`));
}}

export function generate_malformed_input_cases() {{
  return Object.freeze(Array.from({{ length: 64 }}, (_, width) => " ".repeat(width)));
}}

export const {machine} = Object.freeze({{ transition, transitionRecord, replayTrace }});
"#,
        imports = imports,
        input = names.input,
        state = names.state,
        initial = initial,
        command = names.command,
        accept_body = accept_body,
        rejection = names.rejection,
        rejected = rejected,
        event = names.event,
        result_branches = result_branches,
        observed_branch = observed_branch,
        transition = names.transition,
        transition_record = names.transition_record,
        source_provenance = names.source_provenance,
        machine = names.machine,
    )
}

fn render_js_public_mjs(names: &InnerStructureNames) -> String {
    format!(
        r#"export * from "./representation.mjs";
export {{
  transition,
  transitionRecord,
  replayTrace,
  {machine},
}} from "./transition.mjs";

export const rmsPublicFacade = Object.freeze({{
  machine: "{machine}",
  entrypoint: "src/public.mjs",
}});
"#,
        machine = names.machine,
    )
}

fn render_js_parser_mjs(names: &InnerStructureNames) -> String {
    format!(
        r#"import {{
  make{command}Accept,
  make{command_envelope},
  make{command}Reject,
  make{label},
  make{rejection}MalformedInput,
}} from "./representation.mjs";

export function parseCommand(input) {{
  const label = make{label}(input?.label ?? input);
  if (!label) {{
    return Object.freeze({{
      tag: "{prefix}ParseRejected",
      rejection: make{rejection}MalformedInput("missing-label"),
    }});
  }}

  const command = input?.reject === true
    ? make{command}Reject(label)
    : make{command}Accept(label);
  return Object.freeze({{
    tag: "{prefix}ParsedCommand",
    command_envelope: make{command_envelope}(command),
  }});
}}
"#,
        command = names.command,
        command_envelope = names.command_envelope,
        label = names.label,
        prefix = names.prefix,
        rejection = names.rejection,
    )
}

fn render_js_adapter_mjs(names: &InnerStructureNames, shape: ScaffoldShape) -> String {
    let states = starter_states_for_shape(shape);
    let state_before = states.first().map(String::as_str).unwrap_or("Ready");
    let effectful = scaffold_declares_effects_by_default(shape)
        && is_stateful_machine_mode(machine_mode_for_shape(shape));
    let machine_execution_import = if effectful {
        "import { driveMachine } from \"./machine_driver.mjs\";"
    } else {
        "import { transitionRecord } from \"./transition.mjs\";"
    };
    let transition_call = if effectful {
        format!(
            "  const records = driveMachine(\n    {state_before},\n    make{input}Command(parsed.command_envelope.command),\n  );\n  return Object.freeze({{ output: records.at(-1)?.output, transitions: records }});",
            input = names.input,
        )
    } else {
        format!(
            "  return transitionRecord(\n    {state_before},\n    make{input}Command(parsed.command_envelope.command),\n  );",
            input = names.input,
        )
    };
    let rejection_call = if effectful {
        format!(
            "    const records = driveMachine({state_before}, make{input}Command(make{command}Reject(reason)));\n    return Object.freeze({{ output: records.at(-1)?.output, transitions: records }});",
            command = names.command,
            input = names.input,
        )
    } else {
        format!(
            "    return transitionRecord({state_before}, make{input}Command(make{command}Reject(reason)));",
            command = names.command,
            input = names.input,
        )
    };
    format!(
        r#"import {{
  {state_before},
  make{command}Reject,
  make{input}Command,
  make{label},
}} from "./representation.mjs";
import {{ parseCommand }} from "./parser.mjs";
{machine_execution_import}

export function handleBoundaryTransition(input, ports) {{
  const parsed = parseCommand(input);
  if (parsed.tag === "{prefix}ParseRejected") {{
    const reason = make{label}(parsed.rejection?.reason ?? "malformed-input");
{rejection_call}
  }}

  ports?.write?.(parsed.command_envelope);
{transition_call}
}}

export function handleBoundaryInput(input, ports) {{
  return handleBoundaryTransition(input, ports).output;
}}

export const {machine} = Object.freeze({{
  handleBoundaryTransition,
  handleBoundaryInput,
}});
"#,
        command = names.command,
        input = names.input,
        label = names.label,
        machine = names.machine,
        machine_execution_import = machine_execution_import,
        prefix = names.prefix,
        rejection_call = rejection_call,
        state_before = state_before,
        transition_call = transition_call,
    )
}

fn render_js_trace_test_mjs(model: &BindingScaffoldModel) -> String {
    let names = &model.names;
    let states = starter_states_for_shape(model.shape);
    let initial = states.first().map(String::as_str).unwrap_or("Ready");
    let input_import = if model.stateful() {
        format!("  make{}Command,\n", names.input)
    } else {
        String::new()
    };
    let transition_call = if model.stateful() {
        format!(
            "{machine}.transition({initial}, make{input}Command(make{command}Accept(label)))",
            machine = names.machine,
            input = names.input,
            command = names.command,
        )
    } else {
        format!(
            "{machine}.transition(make{command}Accept(label))",
            machine = names.machine,
            command = names.command,
        )
    };
    let replay_call = if model.stateful() {
        format!(
            "replayTrace({initial}, [make{input}Command(make{command}Accept(label))])",
            input = names.input,
            command = names.command,
        )
    } else {
        format!("replayTrace([make{}Accept(label)])", names.command)
    };
    format!(
        r#"import assert from "node:assert/strict";
import test from "node:test";
import {{
{input_import}  {initial},
  make{command}Accept,
  make{label},
}} from "../src/representation.mjs";
import {{ generate_property_cases, replayTrace, {machine} }} from "../src/transition.mjs";

test("{machine} rejects invalid representation", () => {{
  assert.equal(make{label}(""), null);
}});

test("{machine} replays accepted commands", () => {{
  const label = make{label}("example");
  assert.equal({replay_call}[0].source.branch, "Accept");
  assert.equal({transition_call}.events.length, 1);
}});

export function runTransitionProperty() {{
  for (const raw of generate_property_cases()) {{
    const label = make{label}(raw);
    const output = {transition_call};
    assert.equal(output.events.length, 1);
  }}
}}

test("{machine} property generated labels use declared variants", runTransitionProperty);
"#,
        command = names.command,
        initial = initial,
        input_import = input_import,
        label = names.label,
        machine = names.machine,
        replay_call = replay_call,
        transition_call = transition_call,
    )
}

fn render_js_trace_producer_mjs(model: &BindingScaffoldModel) -> String {
    let names = &model.names;
    let initial = starter_states_for_shape(model.shape)
        .first()
        .cloned()
        .unwrap_or_else(|| "Ready".to_string());
    let mut imports = vec![
        initial.clone(),
        format!("make{}Accept", names.command),
        format!("make{}Reject", names.command),
        format!("make{}", names.label),
    ];
    if model.stateful() {
        imports.push(format!("make{}Command", names.input));
    }
    if model.declares_effect_results {
        imports.push(format!("make{}EffectResult", names.input));
        imports.push(format!("make{}Succeeded", names.effect_result));
    }
    let records = if !model.stateful() {
        format!(
            r#"[
    {{ scenario_start: true, ...transitionRecord(make{command}Accept(make{label}("accepted"))) }},
    {{ scenario_start: true, ...transitionRecord(make{command}Reject("rejected")) }},
  ]"#,
            command = names.command,
            label = names.label,
        )
    } else if model.declares_effect_results {
        format!(
            r#"(() => {{
    const accepted = transitionRecord({initial}, make{input}Command(make{command}Accept(make{label}("accepted"))));
    const succeeded = transitionRecord(accepted.state_after, make{input}EffectResult(make{effect_result}Succeeded()));
    const rejected = transitionRecord({initial}, make{input}Command(make{command}Reject("rejected")));
    return [
      {{ scenario_start: true, ...accepted }},
      {{ scenario_start: false, ...succeeded }},
      {{ scenario_start: true, ...rejected }},
    ];
  }})()"#,
            initial = initial,
            input = names.input,
            command = names.command,
            label = names.label,
            effect_result = names.effect_result,
        )
    } else {
        format!(
            r#"[
    {{ scenario_start: true, ...transitionRecord({initial}, make{input}Command(make{command}Accept(make{label}("accepted")))) }},
    {{ scenario_start: true, ...transitionRecord({initial}, make{input}Command(make{command}Reject("rejected"))) }},
  ]"#,
            initial = initial,
            input = names.input,
            command = names.command,
            label = names.label,
        )
    };
    format!(
        r#"import {{ writeFile }} from "node:fs/promises";
import {{
  {imports}
}} from "../src/representation.mjs";
import {{ transitionRecord }} from "../src/transition.mjs";

export async function produceTransitionTrace() {{
  const output = process.env.RMS_TRACE_OUTPUT;
  if (!output) throw new Error("RMS_TRACE_OUTPUT is required");
  const records = {records};
  await writeFile(output, JSON.stringify({{
    spec: "rms/trace-bundle/v0.1",
    machine: "{machine}",
    records,
  }}, null, 2));
  if (records.length === 0) throw new Error("trace producer emitted no records");
}}

if (process.env.RMS_TRACE_RUNNER === "produceTransitionTrace") {{
  await produceTransitionTrace();
}}
"#,
        imports = imports.join(",\n  "),
        records = records,
        machine = names.machine,
    )
}

fn render_js_machine_probe_mjs(model: &BindingScaffoldModel) -> String {
    let names = &model.names;
    let states = starter_states_for_shape(model.shape);
    let initial = states
        .first()
        .cloned()
        .unwrap_or_else(|| "Ready".to_string());
    let mut imports = states.clone();
    imports.extend([
        "initialState".to_string(),
        format!("make{}Accept", names.command),
        format!("make{}Reject", names.command),
        format!("make{}", names.label),
    ]);
    if model.stateful() {
        imports.push(format!("make{}Command", names.input));
    }
    for event in model.declared_observed_events() {
        imports.push(format!("make{}{}", names.event, event));
    }
    if !model.declared_observed_events().is_empty() {
        imports.push(format!("make{}ObservedEvent", names.input));
    }
    if model.declares_effect_results {
        imports.extend([
            format!("make{}EffectResult", names.input),
            format!("make{}Succeeded", names.effect_result),
            format!("make{}Failed", names.effect_result),
        ]);
    }
    imports.sort();
    imports.dedup();
    let state_map = states
        .iter()
        .map(|state| format!("  {state},"))
        .collect::<Vec<_>>()
        .join("\n");
    let state_descriptions = states
        .iter()
        .map(|state| {
            format!(
                r#"{{ name: "{state}", data_schema: {{ type: "object" }}, examples: [variantJSON({state})] }}"#
            )
        })
        .collect::<Vec<_>>()
        .join(",\n    ");
    let observed_arms = model
        .declared_observed_events()
        .iter()
        .map(|event| {
            format!(
                r#"  if (kind === "observed-event" && name === "{event}") return make{input}ObservedEvent(make{event_type}{event}());"#,
                input = names.input,
                event_type = names.event,
            )
        })
        .collect::<Vec<_>>()
        .join("\n");
    let observed_descriptions = model
        .declared_observed_events()
        .iter()
        .map(|event| {
            format!(
                r#"{{ kind: "observed-event", name: "{event}", data_schema: {{ type: "object" }}, example: {{ kind: "observed-event", name: "{event}", data: {{}} }} }}"#
            )
        })
        .collect::<Vec<_>>();
    let effect_arms = if model.declares_effect_results {
        format!(
            r#"  if (kind === "effect-result" && name === "Succeeded") return make{input}EffectResult(make{effect_result}Succeeded());
  if (kind === "effect-result" && name === "Failed") return make{input}EffectResult(make{effect_result}Failed(probeText(value, "reason")));"#,
            input = names.input,
            effect_result = names.effect_result,
        )
    } else {
        String::new()
    };
    let mut input_descriptions = vec![
        r#"{ kind: "command", name: "Accept", data_schema: { type: "object", properties: { label: { type: "string" } }, required: ["label"] }, example: { kind: "command", name: "Accept", data: { label: "example" } } }"#.to_string(),
        r#"{ kind: "command", name: "Reject", data_schema: { type: "object", properties: { reason: { type: "string" } }, required: ["reason"] }, example: { kind: "command", name: "Reject", data: { reason: "rejected" } } }"#.to_string(),
    ];
    input_descriptions.extend(observed_descriptions);
    if model.declares_effect_results {
        input_descriptions.extend([
            r#"{ kind: "effect-result", name: "Succeeded", data_schema: { type: "object" }, example: { kind: "effect-result", name: "Succeeded", data: {} } }"#.to_string(),
            r#"{ kind: "effect-result", name: "Failed", data_schema: { type: "object", properties: { reason: { type: "string" } }, required: ["reason"] }, example: { kind: "effect-result", name: "Failed", data: { reason: "failed" } } }"#.to_string(),
        ]);
    }
    let parse_input = if model.stateful() {
        format!(
            r#"function parseInput(value) {{
  const kind = value?.kind;
  const name = value?.name;
  if (kind === "command" && name === "Accept") return make{input}Command(make{command}Accept(make{label}(probeText(value, "label"))));
  if (kind === "command" && name === "Reject") return make{input}Command(make{command}Reject(probeText(value, "reason")));
{observed_arms}
{effect_arms}
  throw new Error(`unsupported probe input ${{kind}}:${{name}}`);
}}"#,
            input = names.input,
            command = names.command,
            label = names.label,
            observed_arms = observed_arms,
            effect_arms = effect_arms,
        )
    } else {
        format!(
            r#"function parseInput(value) {{
  if (value?.name === "Accept") return make{command}Accept(make{label}(probeText(value, "label")));
  if (value?.name === "Reject") return make{command}Reject(probeText(value, "reason"));
  throw new Error(`unsupported probe command ${{value?.name}}`);
}}"#,
            command = names.command,
            label = names.label,
        )
    };
    let run_steps = if model.stateful() {
        r#"function runSteps(request) {
  let state = request.start === "initial"
    ? initialState()
    : statesByName[request.start?.name];
  if (!state) throw new Error(`unknown probe state ${request.start?.name}`);
  return request.steps.map((step, index) => {
    const record = transitionRecord(state, parseInput(step.input));
    state = record.state_after;
    return recordJSON(record, step.input, index === 0);
  });
}

function evaluateCases(request) {
  return request.cases.map((item) => {
    const state = statesByName[item.state?.name];
    if (!state) throw new Error(`unknown probe state ${item.state?.name}`);
    return {
      id: item.id,
      record: recordJSON(transitionRecord(state, parseInput(item.input)), item.input, true),
    };
  });
}"#
        .to_string()
    } else {
        r#"function runSteps(request) {
  return request.steps.map((step, index) =>
    recordJSON(transitionRecord(parseInput(step.input)), step.input, index === 0));
}

function evaluateCases(request) {
  return request.cases.map((item) => ({
    id: item.id,
    record: recordJSON(transitionRecord(parseInput(item.input)), item.input, true),
  }));
}"#
        .to_string()
    };
    format!(
        r#"import {{ readFile, writeFile }} from "node:fs/promises";
import {{
  {imports}
}} from "../src/representation.mjs";
import {{ transitionRecord }} from "../src/transition.mjs";

const statesByName = Object.freeze({{
{state_map}
}});

function caseName(value) {{
  const tag = value?.tag;
  if (typeof tag === "string") return tag.split(".").at(-1);
  return String(value?.constructor?.name ?? value);
}}

function variantJSON(value) {{
  if (value == null) return null;
  return {{ name: caseName(value), data: {{ value }} }};
}}

function probeText(value, field) {{
  return value?.data?.[field] ?? value?.data?.value ?? field;
}}

{parse_input}

function recordJSON(record, normalizedInput, scenarioStart) {{
  return {{
    scenario_start: scenarioStart,
    state_before: variantJSON(record.state_before),
    state_after: variantJSON(record.state_after),
    input: normalizedInput,
    output: {{
      next_state: variantJSON(record.output.next_state),
      events: record.output.events.map(variantJSON),
      commands: record.output.commands.map(variantJSON),
      effects: record.output.effects.map(variantJSON),
      reply: variantJSON(record.output.reply),
      rejection: variantJSON(record.output.rejection),
    }},
    source: record.source,
  }};
}}

{run_steps}

export async function probeMachine() {{
  const requestPath = process.env.RMS_PROBE_REQUEST;
  const outputPath = process.env.RMS_PROBE_OUTPUT;
  if (!requestPath || !outputPath) throw new Error("RMS_PROBE_REQUEST and RMS_PROBE_OUTPUT are required");
  const request = JSON.parse(await readFile(requestPath, "utf8"));
  let output;
  if (request.operation === "describe") {{
    output = {{
      spec: "rms/machine-probe-description/v0.1",
      machine: "{machine}",
      initial_state: variantJSON({initial}),
      states: [
      {state_descriptions}
      ],
      inputs: [
      {input_descriptions}
      ],
    }};
  }} else if (request.operation === "evaluate") {{
    output = {{
      spec: "rms/machine-probe-evaluation/v0.2",
      machine: "{machine}",
      results: evaluateCases(request),
    }};
  }} else {{
    output = {{
      spec: "rms/trace-bundle/v0.1",
      machine: "{machine}",
      records: runSteps(request),
    }};
  }}
  await writeFile(outputPath, JSON.stringify(output, null, 2));
}}

if (process.env.RMS_PROBE_RUNNER?.split('#').at(-1) === "probeMachine") {{
  await probeMachine();
}}
"#,
        imports = imports.join(",\n  "),
        state_map = state_map,
        parse_input = parse_input,
        run_steps = run_steps,
        machine = names.machine,
        initial = initial,
        state_descriptions = state_descriptions,
        input_descriptions = input_descriptions.join(",\n    "),
    )
}

fn render_js_boundary_test_mjs(names: &InnerStructureNames) -> String {
    format!(
        r#"import assert from "node:assert/strict";
import test from "node:test";
import {{ handleBoundaryInput }} from "../src/adapter.mjs";
import {{ createPorts }} from "../src/ports.mjs";
import {{ generate_malformed_input_cases }} from "../src/transition.mjs";

test("{machine} boundary adapter rejects malformed input", () => {{
  const ports = createPorts();
  assert.equal(handleBoundaryInput("", ports).rejection.tag, "{rejection}.InvalidCommand");
}});

test("{machine} boundary adapter writes parsed commands", () => {{
  const written = [];
  const ports = createPorts({{ write: (command) => written.push(command) }});
  assert.equal(handleBoundaryInput("example", ports).reply.tag, "{reply}.Accepted");
  assert.equal(written.length, 1);
  assert.equal(written[0].tag, "{command_envelope}");
  assert.equal(written[0].command.tag, "{command}.Accept");
}});

export function runMalformedInputProperty() {{
  for (const raw of [...generate_malformed_input_cases(), null, undefined, {{}}, {{ label: "" }}, {{ unexpected: true }}]) {{
    const written = [];
    const ports = createPorts({{ write: (command) => written.push(command) }});
    assert.equal(handleBoundaryInput(raw, ports).rejection.tag, "{rejection}.InvalidCommand");
    assert.equal(written.length, 0);
  }}
}}

test("{machine} fuzz generated malformed inputs stop before delegation", runMalformedInputProperty);
"#,
        command = names.command,
        command_envelope = names.command_envelope,
        machine = names.machine,
        reply = names.reply,
        rejection = names.rejection,
    )
}

fn render_js_browser_controller_mjs(public_command: &str) -> String {
    format!(
        r#"import {{ handleBoundaryInput }} from "../src/adapter.mjs";

export async function runRmsSurface(input, ports) {{
  return await handleBoundaryInput(input, ports);
}}

export function declaredRmsSurface() {{
  return Object.freeze({{
    kind: "runnable-boundary",
    surface: "browser",
    command: "{public_command}",
    delegatesTo: "src/adapter.mjs#handleBoundaryInput",
  }});
}}

export function mountRmsSurface(root = document, ports) {{
  const form = root.querySelector("[data-rms-surface-form]");
  const output = root.querySelector("[data-rms-surface-output]");
  const run = async () => {{
    const formData = new FormData(form);
    const input = Object.fromEntries(formData.entries());
    const reply = await runRmsSurface(input, ports);
    if (output) {{
      output.textContent = JSON.stringify(reply, null, 2);
    }}
    return reply;
  }};
  form?.addEventListener("submit", async (event) => {{
    event.preventDefault();
    await run();
  }});
  return Object.freeze({{ run }});
}}
"#
    )
}

fn render_js_browser_app_mjs(controller_import: &str) -> String {
    format!(
        r#"import {{ mountRmsSurface }} from "{controller_import}";

mountRmsSurface(document);
"#
    )
}

