fn yaml_string_list(values: &[String], indent: usize) -> String {
    let prefix = " ".repeat(indent);
    values
        .iter()
        .map(|value| format!("{prefix}- {}", yaml_quote(value)))
        .collect::<Vec<_>>()
        .join("\n")
}

fn yaml_quote(value: &str) -> String {
    format!("\"{}\"", value.replace('\\', "\\\\").replace('"', "\\\""))
}

fn yaml_summary(value: &YamlValue) -> String {
    serde_yaml::to_string(value)
        .unwrap_or_else(|_| format!("{value:?}"))
        .trim()
        .to_string()
}

fn markdown_inline(value: &str) -> String {
    value.split_whitespace().collect::<Vec<_>>().join(" ")
}

fn shell_arg(value: &str) -> String {
    if value
        .chars()
        .all(|character| character.is_ascii_alphanumeric() || "-_./:".contains(character))
    {
        value.to_string()
    } else {
        format!("'{}'", value.replace('\'', "'\\''"))
    }
}

fn inner_structure_names(semantic_name: &str, shape: ScaffoldShape) -> InnerStructureNames {
    let prefix = semantic_role_prefix(semantic_name, shape);
    InnerStructureNames {
        prefix: prefix.clone(),
        machine: format!("{prefix}Machine"),
        state: format!("{prefix}State"),
        input: format!("{prefix}Input"),
        command: format!("{prefix}Command"),
        command_envelope: format!("{prefix}CommandEnvelope"),
        event: format!("{prefix}Event"),
        event_envelope: format!("{prefix}EventEnvelope"),
        effect: format!("{prefix}Effect"),
        effect_envelope: format!("{prefix}EffectEnvelope"),
        effect_result: format!("{prefix}EffectResult"),
        effect_result_envelope: format!("{prefix}EffectResultEnvelope"),
        effect_lifecycle: format!("{prefix}EffectLifecycle"),
        reply: format!("{prefix}Reply"),
        rejection: format!("{prefix}Rejection"),
        transition: format!("{prefix}Transition"),
        transition_record: format!("{prefix}TransitionRecord"),
        source_provenance: format!("{prefix}SourceProvenance"),
        label: format!("{prefix}Label"),
    }
}

fn semantic_role_prefix(semantic_name: &str, shape: ScaffoldShape) -> String {
    let mut tokens = semantic_identifier_tokens(semantic_name);
    while tokens.len() > 1
        && tokens
            .last()
            .is_some_and(|token| is_role_suffix_token(token.as_str()))
    {
        tokens.pop();
    }

    let mut prefix = pascal_case_tokens(&tokens);
    let role_suffix = match shape {
        ScaffoldShape::DomainEngine => "",
        ScaffoldShape::BoundaryAdapter => "Boundary",
        ScaffoldShape::RuntimeMonitor => "Monitor",
        ScaffoldShape::Workflow => "Workflow",
        ScaffoldShape::StorageAdapter => "Storage",
        ScaffoldShape::IntegrationAdapter => "Integration",
        ScaffoldShape::Composite => "Composite",
    };
    if !role_suffix.is_empty() && !prefix.ends_with(role_suffix) {
        prefix.push_str(role_suffix);
    }
    prefix
}

fn semantic_identifier_tokens(value: &str) -> Vec<String> {
    let mut tokens = Vec::new();
    let mut current = String::new();
    for character in value.chars() {
        if character.is_ascii_alphanumeric() {
            current.push(character.to_ascii_lowercase());
        } else if !current.is_empty() {
            tokens.push(std::mem::take(&mut current));
        }
    }
    if !current.is_empty() {
        tokens.push(current);
    }
    if tokens.is_empty() {
        tokens.push("module".to_string());
    }
    tokens
}

fn is_role_suffix_token(token: &str) -> bool {
    matches!(
        token,
        "adapter"
            | "adaptor"
            | "api"
            | "boundary"
            | "boundaries"
            | "cli"
            | "domain"
            | "engine"
            | "integration"
            | "javascript"
            | "js"
            | "mjs"
            | "monitor"
            | "persistence"
            | "python"
            | "rules"
            | "rule"
            | "rust"
            | "runtime"
            | "storage"
            | "store"
            | "swift"
            | "ts"
            | "typescript"
            | "ui"
            | "web"
            | "workflow"
    )
}

fn pascal_case_tokens(tokens: &[String]) -> String {
    let prefix = tokens
        .iter()
        .map(|token| pascal_case_identifier(token))
        .collect::<Vec<_>>()
        .join("");
    if prefix.is_empty() {
        "Module".to_string()
    } else {
        prefix
    }
}

fn pascal_case_identifier(value: &str) -> String {
    let mut output = String::new();
    let mut capitalize_next = true;
    for character in value.chars() {
        if character.is_ascii_alphanumeric() {
            if output.is_empty() && character.is_ascii_digit() {
                output.push_str("Module");
            }
            if capitalize_next {
                output.extend(character.to_uppercase());
                capitalize_next = false;
            } else {
                output.push(character);
            }
        } else {
            capitalize_next = true;
        }
    }
    if output.is_empty() {
        "Module".to_string()
    } else {
        output
    }
}

fn sanitize_rust_package_name(name: &str) -> String {
    let mut output = String::new();
    let mut previous_dash = false;
    for character in name.chars().flat_map(char::to_lowercase) {
        if character.is_ascii_alphanumeric() || character == '_' {
            output.push(character);
            previous_dash = false;
        } else if !previous_dash {
            output.push('-');
            previous_dash = true;
        }
    }
    let trimmed = output.trim_matches('-').to_string();
    if trimmed.is_empty() {
        "rms-module".to_string()
    } else {
        trimmed
    }
}

fn sanitize_swift_package_name(name: &str) -> String {
    sanitize_rust_package_name(name)
}

fn sanitize_swift_target_name(name: &str) -> String {
    let mut output = String::new();
    let mut capitalize_next = true;
    for character in name.chars() {
        if character.is_ascii_alphanumeric() {
            if output.is_empty() && character.is_ascii_digit() {
                output.push_str("Rms");
            }
            if capitalize_next {
                output.extend(character.to_uppercase());
                capitalize_next = false;
            } else {
                output.push(character);
            }
        } else {
            capitalize_next = true;
        }
    }
    if output.is_empty() {
        "RmsModule".to_string()
    } else {
        output
    }
}

fn write_new_file(path: &Path, contents: &str) -> Result<()> {
    if path.exists() {
        bail!("refusing to overwrite existing file `{}`", path.display());
    }
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)?;
    }
    fs::write(path, contents).with_context(|| format!("failed to write `{}`", path.display()))
}

fn write_file_if_missing(path: &Path, contents: &str) -> Result<()> {
    if path.exists() {
        return Ok(());
    }
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)?;
    }
    fs::write(path, contents).with_context(|| format!("failed to write `{}`", path.display()))
}

