fn referenced_paths(value: &YamlValue) -> BTreeSet<String> {
    let mut paths = BTreeSet::new();
    collect_contract_paths(value, &mut |path| {
        paths.insert(path.to_string());
    });

    if let Some(invariants) = get_path(value, &["invariants"]).and_then(YamlValue::as_sequence) {
        for invariant in invariants {
            if let Some(path) = get_str(invariant, &["verified_by"]) {
                paths.insert(path.to_string());
            }
        }
    }

    if let Some(verification) = get_path(value, &["verification"]) {
        for category in verification_reference_categories() {
            if let Some(items) =
                get_path(verification, &[category]).and_then(YamlValue::as_sequence)
            {
                for item in items.iter().filter_map(YamlValue::as_str) {
                    paths.insert(item.to_string());
                }
            }
        }
    }

    if let Some(protocols) = change_protocol_items(value) {
        for protocol in protocols {
            collect_change_protocol_reference_paths(protocol, &mut |path| {
                paths.insert(path.to_string());
            });
        }
    }

    paths
}

fn has_empty_verification_category(value: &YamlValue) -> bool {
    REQUIRED_VERIFICATION_CATEGORIES
        .into_iter()
        .any(|category| {
            get_path(value, &["verification", category])
                .and_then(YamlValue::as_sequence)
                .is_none_or(Vec::is_empty)
        })
}

fn load_manifest(path: &Path) -> Result<LoadedManifest> {
    let contents = fs::read_to_string(path)
        .with_context(|| format!("failed to read manifest `{}`", path.display()))?;
    let value = serde_yaml::from_str(&contents)
        .with_context(|| format!("failed to parse YAML `{}`", path.display()))?;
    Ok(LoadedManifest {
        path: path.to_path_buf(),
        value,
    })
}

fn get_path<'a>(value: &'a YamlValue, path: &[&str]) -> Option<&'a YamlValue> {
    let mut current = value;
    for segment in path {
        current = current
            .as_mapping()?
            .get(YamlValue::String((*segment).to_string()))?;
    }
    Some(current)
}

fn get_path_mut<'a>(value: &'a mut YamlValue, path: &[&str]) -> Option<&'a mut YamlValue> {
    let mut current = value;
    for segment in path {
        current = current
            .as_mapping_mut()?
            .get_mut(YamlValue::String((*segment).to_string()))?;
    }
    Some(current)
}

fn get_str<'a>(value: &'a YamlValue, path: &[&str]) -> Option<&'a str> {
    get_path(value, path)?.as_str()
}

fn yaml_key(key: &str) -> YamlValue {
    YamlValue::String(key.to_string())
}

fn yaml_string_sequence(values: &[String]) -> YamlValue {
    YamlValue::Sequence(
        values
            .iter()
            .map(|value| YamlValue::String(value.clone()))
            .collect(),
    )
}

fn yaml_mapping_value<const N: usize>(entries: [(&str, YamlValue); N]) -> YamlValue {
    YamlValue::Mapping(
        entries
            .into_iter()
            .map(|(key, value)| (yaml_key(key), value))
            .collect(),
    )
}

fn ensure_yaml_mapping(value: &mut YamlValue) -> &mut serde_yaml::Mapping {
    if !value.is_mapping() {
        *value = YamlValue::Mapping(serde_yaml::Mapping::new());
    }
    match value {
        YamlValue::Mapping(mapping) => mapping,
        _ => unreachable!("YAML value was just normalized to a mapping"),
    }
}

fn ensure_yaml_mapping_path<'a>(
    value: &'a mut YamlValue,
    path: &[&str],
) -> &'a mut serde_yaml::Mapping {
    if path.is_empty() {
        return ensure_yaml_mapping(value);
    }
    let mapping = ensure_yaml_mapping(value);
    let entry = mapping
        .entry(yaml_key(path[0]))
        .or_insert_with(|| YamlValue::Mapping(serde_yaml::Mapping::new()));
    ensure_yaml_mapping_path(entry, &path[1..])
}

fn ensure_yaml_sequence_path<'a>(
    value: &'a mut YamlValue,
    path: &[&str],
) -> &'a mut Vec<YamlValue> {
    let (parent_path, key) = path.split_at(path.len().saturating_sub(1));
    let key = key.first().copied().unwrap_or("");
    let mapping = ensure_yaml_mapping_path(value, parent_path);
    let entry = mapping
        .entry(yaml_key(key))
        .or_insert_with(|| YamlValue::Sequence(Vec::new()));
    if !entry.is_sequence() {
        let prior = std::mem::replace(entry, YamlValue::Sequence(Vec::new()));
        if let YamlValue::String(value) = prior {
            *entry = YamlValue::Sequence(vec![YamlValue::String(value)]);
        }
    }
    match entry {
        YamlValue::Sequence(sequence) => sequence,
        _ => unreachable!("YAML value was just normalized to a sequence"),
    }
}

fn set_yaml_string_path(value: &mut YamlValue, path: &[&str], item: &str) {
    set_yaml_value_path(value, path, YamlValue::String(item.to_string()));
}

fn set_yaml_value_path(value: &mut YamlValue, path: &[&str], item: YamlValue) {
    let (parent_path, key) = path.split_at(path.len().saturating_sub(1));
    let Some(key) = key.first() else {
        return;
    };
    let mapping = ensure_yaml_mapping_path(value, parent_path);
    mapping.insert(yaml_key(key), item);
}

fn set_yaml_sequence_path(value: &mut YamlValue, path: &[&str], items: Vec<YamlValue>) {
    let (parent_path, key) = path.split_at(path.len().saturating_sub(1));
    let Some(key) = key.first() else {
        return;
    };
    let mapping = ensure_yaml_mapping_path(value, parent_path);
    mapping.insert(yaml_key(key), YamlValue::Sequence(items));
}

fn set_yaml_string_sequence_path(value: &mut YamlValue, path: &[&str], items: &[String]) {
    set_yaml_sequence_path(
        value,
        path,
        items
            .iter()
            .map(|item| YamlValue::String(item.clone()))
            .collect(),
    );
}

fn set_yaml_string_if_missing_path(value: &mut YamlValue, path: &[&str], item: &str) {
    if get_path(value, path).is_some() {
        return;
    }
    set_yaml_string_path(value, path, item);
}

fn remove_yaml_path(value: &mut YamlValue, path: &[&str]) {
    let (parent_path, key) = path.split_at(path.len().saturating_sub(1));
    let Some(key) = key.first() else {
        return;
    };
    if let Some(mapping) = get_path_mut(value, parent_path).and_then(YamlValue::as_mapping_mut) {
        mapping.remove(yaml_key(key));
    }
}

fn append_unique_yaml_string_path(value: &mut YamlValue, path: &[&str], item: &str) {
    let sequence = ensure_yaml_sequence_path(value, path);
    if !sequence
        .iter()
        .any(|existing| existing.as_str() == Some(item))
    {
        sequence.push(YamlValue::String(item.to_string()));
    }
}

fn dedup_preserve_order(values: Vec<String>) -> Vec<String> {
    let mut seen = BTreeSet::new();
    values
        .into_iter()
        .filter(|value| seen.insert(value.clone()))
        .collect()
}

fn append_yaml_mapping_path(value: &mut YamlValue, path: &[&str], item: YamlValue) {
    ensure_yaml_sequence_path(value, path).push(item);
}

fn get_bool(value: &YamlValue, path: &[&str]) -> Option<bool> {
    get_path(value, path)?.as_bool()
}

fn get_string_array(value: &YamlValue, path: &[&str]) -> Vec<String> {
    get_path(value, path)
        .and_then(YamlValue::as_sequence)
        .map(|items| {
            items
                .iter()
                .filter_map(YamlValue::as_str)
                .map(ToString::to_string)
                .collect()
        })
        .unwrap_or_default()
}

fn yaml_string_values(value: &YamlValue) -> Vec<String> {
    if let Some(value) = value.as_str() {
        return vec![value.to_string()];
    }
    value
        .as_sequence()
        .map(|items| {
            items
                .iter()
                .filter_map(YamlValue::as_str)
                .map(ToString::to_string)
                .collect()
        })
        .unwrap_or_default()
}

fn require_str(
    manifest: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
    check: impl Into<String>,
    path: &[&str],
) {
    if get_str(&manifest.value, path).is_none() {
        diagnostics.push(error(
            check,
            &manifest.path,
            format!("missing required string `{}`", path.join(".")),
        ));
    }
}

fn require_array(
    manifest: &LoadedManifest,
    diagnostics: &mut Vec<Diagnostic>,
    check: impl Into<String>,
    path: &[&str],
) {
    if get_path(&manifest.value, path)
        .and_then(YamlValue::as_sequence)
        .is_none()
    {
        diagnostics.push(error(
            check,
            &manifest.path,
            format!("missing required array `{}`", path.join(".")),
        ));
    }
}

fn error(check: impl Into<String>, path: &Path, message: impl Into<String>) -> Diagnostic {
    Diagnostic {
        severity: Severity::Error,
        check: check.into(),
        path: path.display().to_string(),
        message: message.into(),
    }
}

fn warning(check: impl Into<String>, path: &Path, message: impl Into<String>) -> Diagnostic {
    Diagnostic {
        severity: Severity::Warning,
        check: check.into(),
        path: path.display().to_string(),
        message: message.into(),
    }
}

fn push_unique_warning(
    diagnostics: &mut Vec<Diagnostic>,
    check: impl Into<String>,
    path: &Path,
    message: impl Into<String>,
) {
    let check = check.into();
    let path_string = path.display().to_string();
    let message = message.into();
    if diagnostics.iter().any(|diagnostic| {
        diagnostic.severity == Severity::Warning
            && diagnostic.check == check
            && diagnostic.path == path_string
            && diagnostic.message == message
    }) {
        return;
    }
    diagnostics.push(Diagnostic {
        severity: Severity::Warning,
        check,
        path: path_string,
        message,
    });
}

fn error_diagnostic(
    check: impl Into<String>,
    path: &Path,
    message: impl Into<String>,
) -> Diagnostic {
    error(check, path, message)
}

fn severity_label(severity: Severity) -> &'static str {
    match severity {
        Severity::Error => "error",
        Severity::Warning => "warning",
        Severity::Info => "info",
    }
}

fn command_readiness(command: &str, args: &[&str]) -> CommandReadiness {
    match Command::new(command).args(args).output() {
        Ok(output) if output.status.success() => {
            let stdout = String::from_utf8_lossy(&output.stdout);
            let stderr = String::from_utf8_lossy(&output.stderr);
            let version = stdout
                .lines()
                .next()
                .filter(|line| !line.trim().is_empty())
                .or_else(|| stderr.lines().next())
                .unwrap_or("available");
            CommandReadiness {
                command: command.to_string(),
                status: "available".to_string(),
                detail: Some(version.to_string()),
            }
        }
        Ok(output) => CommandReadiness {
            command: command.to_string(),
            status: "found-not-ready".to_string(),
            detail: Some(format!(
                "exit {}",
                output
                    .status
                    .code()
                    .map(|code| code.to_string())
                    .unwrap_or_else(|| "signal".to_string())
            )),
        },
        Err(_) => CommandReadiness {
            command: command.to_string(),
            status: "not-configured".to_string(),
            detail: None,
        },
    }
}

fn codex_provider_readiness(config: &ConfigReadiness) -> CommandReadiness {
    let user_model = codex_user_config_model();
    codex_provider_readiness_with_program(config, Path::new("codex"), user_model.as_deref())
}

fn codex_user_config_model() -> Option<String> {
    let codex_root = std::env::var_os("CODEX_HOME")
        .map(PathBuf::from)
        .or_else(|| home_dir().ok().map(|home| home.join(".codex")))?;
    let source = fs::read_to_string(codex_root.join("config.toml")).ok()?;
    let config: toml::Value = toml::from_str(&source).ok()?;
    config.get("model")?.as_str().map(str::to_string)
}

fn codex_provider_readiness_with_program(
    config: &ConfigReadiness,
    program: &Path,
    user_model: Option<&str>,
) -> CommandReadiness {
    let (effective_model, model_source) = match config.codex_model.as_deref() {
        Some(model) => (Some(model), "RMS project config"),
        None => match user_model {
            Some(model) => (Some(model), "Codex user config"),
            None => (None, "Codex provider default"),
        },
    };
    let version = Command::new(program)
        .arg("--version")
        .output()
        .ok()
        .and_then(|output| {
            let text = format!(
                "{}{}",
                String::from_utf8_lossy(&output.stdout),
                String::from_utf8_lossy(&output.stderr)
            );
            text.lines()
                .find(|line| !line.trim().is_empty())
                .map(|line| line.trim().to_string())
        })
        .unwrap_or_else(|| "unknown Codex version".to_string());

    match Command::new(program).args(["exec", "--help"]).output() {
        Ok(output) if output.status.success() => {
            let help = format!(
                "{}{}",
                String::from_utf8_lossy(&output.stdout),
                String::from_utf8_lossy(&output.stderr)
            );
            if help.contains("--output-schema") {
                // Continue below and verify the effective model against the catalog bundled with
                // this exact CLI. This is offline, non-mutating, and catches a newer configured
                // model paired with an older Codex binary before provider execution.
            } else {
                return CommandReadiness {
                    command: "codex".to_string(),
                    status: "upgrade-required".to_string(),
                    detail: Some(
                        "rms next/design --ai requires a Codex version with --output-schema"
                            .to_string(),
                    ),
                };
            }
        }
        Ok(output) => {
            return CommandReadiness {
                command: "codex".to_string(),
                status: "found-not-ready".to_string(),
                detail: Some(format!(
                    "`codex exec --help` exited {}",
                    exit_status_label(output.status)
                )),
            };
        }
        Err(_) => {
            return CommandReadiness {
                command: "codex".to_string(),
                status: "not-configured".to_string(),
                detail: None,
            };
        }
    }

    let Some(model) = effective_model else {
        return CommandReadiness {
            command: "codex".to_string(),
            status: "available".to_string(),
            detail: Some(format!(
                "{version}; structured output supported; effective model uses {model_source}"
            )),
        };
    };

    let catalog = match Command::new(program)
        .args(["debug", "models", "--bundled"])
        .output()
    {
        Ok(output) if output.status.success() => output,
        Ok(_) => {
            return CommandReadiness {
                command: "codex".to_string(),
                status: "upgrade-required".to_string(),
                detail: Some(format!(
                    "{version} cannot verify effective model `{model}` from {model_source}; run `codex update`, then `rms check --environment`, or explicitly pin `ai.codex.model` to a model supported by this Codex installation"
                )),
            };
        }
        Err(_) => {
            return CommandReadiness {
                command: "codex".to_string(),
                status: "not-configured".to_string(),
                detail: None,
            };
        }
    };
    let catalog: JsonValue = match serde_json::from_slice(&catalog.stdout) {
        Ok(catalog) => catalog,
        Err(error) => {
            return CommandReadiness {
                command: "codex".to_string(),
                status: "found-not-ready".to_string(),
                detail: Some(format!("Codex bundled model catalog is invalid: {error}")),
            };
        }
    };
    let model_entry = catalog
        .get("models")
        .and_then(JsonValue::as_array)
        .and_then(|models| {
            models
                .iter()
                .find(|entry| entry.get("slug").and_then(JsonValue::as_str) == Some(model))
        });
    let Some(model_entry) = model_entry else {
        return CommandReadiness {
            command: "codex".to_string(),
            status: "provider-incompatible".to_string(),
            detail: Some(format!(
                "{version} does not include effective model `{model}` from {model_source}; run `codex update`, then `rms check --environment`, or explicitly pin `ai.codex.model` to a model supported by this Codex installation"
            )),
        };
    };
    if model_entry
        .get("upgrade")
        .is_some_and(|value| !value.is_null())
    {
        return CommandReadiness {
            command: "codex".to_string(),
            status: "upgrade-required".to_string(),
            detail: Some(format!(
                "{version} marks effective model `{model}` from {model_source} as requiring an upgrade; run `codex update`, then `rms check --environment`"
            )),
        };
    }

    CommandReadiness {
        command: "codex".to_string(),
        status: "available".to_string(),
        detail: Some(format!(
            "{version}; effective model `{model}` from {model_source} is present in the bundled catalog; structured output supported"
        )),
    }
}

fn print_command_readiness(readiness: &CommandReadiness) {
    match readiness.detail.as_deref() {
        Some(detail) => println!("{}: {} ({detail})", readiness.command, readiness.status),
        None => println!("{}: {}", readiness.command, readiness.status),
    }
}

fn print_string_list(label: &str, items: &[String]) {
    println!(
        "{label}: {}",
        if items.is_empty() {
            "<none>".to_string()
        } else {
            items.join(", ")
        }
    );
}

fn print_owned_terms(value: &YamlValue) {
    println!();
    println!("## Ownership");
    if let Some(owns) = get_path(value, &["owns"]).and_then(YamlValue::as_mapping) {
        for (key, values) in owns {
            let label = key.as_str().unwrap_or("<unknown>");
            let items = values
                .as_sequence()
                .map(|items| {
                    items
                        .iter()
                        .filter_map(YamlValue::as_str)
                        .collect::<Vec<_>>()
                        .join(", ")
                })
                .unwrap_or_default();
            println!(
                "- {label}: {}",
                if items.is_empty() { "<none>" } else { &items }
            );
        }
    } else {
        println!("- <missing>");
    }
}

fn print_contract_groups(label: &str, value: Option<&YamlValue>) {
    println!();
    println!("## {label}");
    let Some(groups) = value.and_then(YamlValue::as_mapping) else {
        println!("- <missing>");
        return;
    };
    for (group, items) in groups {
        let group = group.as_str().unwrap_or("<unknown>");
        println!("- {group}:");
        if let Some(items) = items.as_sequence() {
            for item in items {
                match item {
                    YamlValue::String(name) => println!("  - {name}"),
                    YamlValue::Mapping(mapping) => {
                        let name = mapping
                            .get(YamlValue::String("name".to_string()))
                            .and_then(YamlValue::as_str)
                            .unwrap_or("<unnamed>");
                        let contract = mapping
                            .get(YamlValue::String("contract".to_string()))
                            .and_then(YamlValue::as_str)
                            .unwrap_or("<no contract>");
                        println!("  - {name} ({contract})");
                    }
                    _ => println!("  - <unsupported reference>"),
                }
            }
        }
    }
}

fn print_invariants(value: &YamlValue) {
    println!();
    println!("## Invariants");
    let Some(invariants) = get_path(value, &["invariants"]).and_then(YamlValue::as_sequence) else {
        println!("- <missing>");
        return;
    };
    if invariants.is_empty() {
        println!("- <none declared>");
        return;
    }
    for invariant in invariants {
        println!(
            "- {}: {}",
            get_str(invariant, &["id"]).unwrap_or("<missing-id>"),
            get_str(invariant, &["statement"]).unwrap_or("<missing statement>")
        );
    }
}

fn print_effects(value: &YamlValue) {
    println!();
    println!("## Effects");
    let Some(effects) = get_path(value, &["effects"]).and_then(YamlValue::as_sequence) else {
        println!("- <missing>");
        return;
    };
    if effects.is_empty() {
        println!("- <none declared>");
        return;
    }
    for effect in effects {
        println!(
            "- {} ({})",
            get_str(effect, &["name"]).unwrap_or("<unnamed>"),
            get_str(effect, &["kind"]).unwrap_or("<unknown-kind>")
        );
    }
}

fn print_verification(value: &YamlValue) {
    println!();
    println!("## Verification");
    for category in verification_reference_categories() {
        let items = get_string_array(value, &["verification", category]);
        println!(
            "- {category}: {}",
            if items.is_empty() {
                "<none>".to_string()
            } else {
                items.join(", ")
            }
        );
    }
}

fn print_change_protocols(value: &YamlValue) {
    let Some(protocols) = change_protocol_items(value) else {
        return;
    };
    if protocols.is_empty() {
        return;
    }

    println!();
    println!("## Change Protocols");
    for protocol in protocols {
        let id = get_str(protocol, &["id"]).unwrap_or("<missing-id>");
        let applies_when = get_str(protocol, &["applies_when"]).unwrap_or("<missing applies_when>");
        println!("- {id}: {applies_when}");
        if let Some(classification) = get_str(protocol, &["classification"]) {
            println!("  classification: {classification}");
        }

        let required_updates = get_string_array(protocol, &["required_updates"]);
        if !required_updates.is_empty() {
            println!("  required updates:");
            for update in required_updates {
                println!("    - {update}");
            }
        }

        let verify = get_string_array(protocol, &["verify"]);
        if !verify.is_empty() {
            println!("  verify:");
            for command in verify {
                println!("    - {command}");
            }
        }
    }
}

fn source_revision(root: &Path) -> Option<String> {
    let output = Command::new("git")
        .current_dir(root)
        .args(["rev-parse", "--short=12", "HEAD"])
        .output()
        .ok()?;
    if output.status.success() {
        Some(format!(
            "git:{}",
            String::from_utf8_lossy(&output.stdout).trim()
        ))
    } else {
        None
    }
}

fn git_repository_identity(root: &Path) -> Result<String> {
    let output = Command::new("git")
        .current_dir(root)
        .args(["rev-parse", "--show-toplevel"])
        .output()
        .with_context(|| format!("failed to inspect Git repository `{}`", root.display()))?;
    if !output.status.success() {
        bail!(
            "route receipts require a Git repository at `{}`{}",
            root.display(),
            command_output_excerpt(&output)
        );
    }
    let path = PathBuf::from(String::from_utf8_lossy(&output.stdout).trim());
    Ok(fs::canonicalize(&path)
        .with_context(|| format!("failed to canonicalize Git root `{}`", path.display()))?
        .display()
        .to_string())
}

fn git_head(root: &Path) -> Result<String> {
    let output = Command::new("git")
        .current_dir(root)
        .args(["rev-parse", "HEAD"])
        .output()
        .with_context(|| format!("failed to inspect Git HEAD at `{}`", root.display()))?;
    if !output.status.success() {
        bail!(
            "route receipts require a committed Git HEAD at `{}`{}",
            root.display(),
            command_output_excerpt(&output)
        );
    }
    Ok(String::from_utf8_lossy(&output.stdout).trim().to_string())
}

fn route_repository_identity(root: &Path) -> Result<String> {
    git_repository_identity(root).or_else(|_| {
        Ok(fs::canonicalize(root)
            .with_context(|| format!("failed to canonicalize route root `{}`", root.display()))?
            .display()
            .to_string())
    })
}

fn route_git_head(root: &Path) -> String {
    git_head(root).unwrap_or_else(|_| "<uncommitted>".to_string())
}

fn normalize_receipt_target(root: &Path, target: &Path) -> Result<String> {
    let target = if target.is_absolute() {
        target.to_path_buf()
    } else {
        root.join(target)
    };
    let normalized = if target.exists() {
        fs::canonicalize(&target)
            .with_context(|| format!("failed to canonicalize target `{}`", target.display()))?
    } else {
        let mut existing = target.as_path();
        let mut suffix = Vec::new();
        while !existing.exists() {
            suffix.push(
                existing
                    .file_name()
                    .ok_or_else(|| {
                        anyhow!("target `{}` has no existing ancestor", target.display())
                    })?
                    .to_os_string(),
            );
            existing = existing.parent().unwrap_or(root);
        }
        let mut normalized = fs::canonicalize(existing).with_context(|| {
            format!(
                "failed to canonicalize target ancestor `{}`",
                existing.display()
            )
        })?;
        for component in suffix.into_iter().rev() {
            normalized.push(component);
        }
        normalized
    };
    Ok(normalized.display().to_string())
}

fn intent_model_json_schema() -> JsonValue {
    let fact = json!({
        "type": "object",
        "additionalProperties": false,
        "required": ["disposition", "basis", "source_quote", "rationale"],
        "properties": {
            "disposition": {"type": "string", "enum": ["required", "absent", "unknown"]},
            "basis": {"type": "string", "enum": ["explicit", "inferred"]},
            "source_quote": {"type": ["string", "null"]},
            "rationale": {"type": ["string", "null"]}
        }
    });
    json!({
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "$id": INTENT_SCHEMA_SPEC,
        "type": "object",
        "additionalProperties": false,
        "required": ["spec", "operation", "change_scope", "subjects", "facts", "responsibilities", "surface_kinds", "binding_preferences", "open_questions"],
        "properties": {
            "spec": {"type": "string", "const": INTENT_SCHEMA_SPEC},
            "operation": {"type": "string", "enum": ["read", "repository-operation", "design", "semantic-change", "surface-change", "implementation-change"]},
            "change_scope": {"type": "string", "enum": ["new-system", "new-module", "existing-module", "unknown"]},
            "subjects": {"type": "array", "items": {"type": "string"}, "minItems": 1},
            "facts": {
                "type": "object",
                "additionalProperties": false,
                "required": ["domain_decisions", "lifecycle", "effects", "runnable_surface", "reuse"],
                "properties": {
                    "domain_decisions": fact.clone(),
                    "lifecycle": fact.clone(),
                    "effects": fact.clone(),
                    "runnable_surface": fact.clone(),
                    "reuse": fact
                }
            },
            "responsibilities": {
                "type": "array",
                "items": {
                    "type": "object",
                    "additionalProperties": false,
                    "required": ["id", "kind", "summary"],
                    "properties": {
                        "id": {"type": "string"},
                        "kind": {"type": "string", "enum": ["decision", "workflow", "boundary", "storage", "integration", "monitor"]},
                        "summary": {"type": "string"}
                    }
                }
            },
            "surface_kinds": {"type": "array", "items": {"type": "string", "enum": ["browser", "cli", "mobile-ui", "desktop-ui", "http", "batch", "executable"]}},
            "binding_preferences": {"type": "array", "items": {"type": "string"}},
            "open_questions": {"type": "array", "items": {"type": "string"}}
        }
    })
}

fn create_route_run_record(
    root: &Path,
    command: &str,
    task: &str,
    prompt: &str,
    options: Option<&PromptRunOptions>,
) -> Result<PathBuf> {
    let run_root = match options {
        Some(options) => options.run_root.clone(),
        None => resolve_run_root(root, None)?,
    };
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_nanos())
        .unwrap_or(0);
    let run_id = format!("{nanos}-{command}-route");
    let run_dir = root.join(run_root).join(&run_id);
    fs::create_dir_all(&run_dir)
        .with_context(|| format!("failed to create route run `{}`", run_dir.display()))?;
    fs::write(run_dir.join("prompt.md"), prompt)?;
    fs::write(
        run_dir.join("request.yaml"),
        serde_yaml::to_string(&json!({
            "schema": "rms/route-request/v0.1",
            "run_id": run_id,
            "command": command,
            "task": task,
            "created_unix_ms": SystemTime::now().duration_since(UNIX_EPOCH).map(|value| value.as_millis()).unwrap_or(0),
        }))?,
    )?;
    fs::write(
        run_dir.join("intent-schema.json"),
        serde_json::to_string_pretty(&intent_model_json_schema())?,
    )?;
    if !run_dir.join("response.md").exists() {
        fs::write(run_dir.join("response.md"), "")?;
    }
    Ok(run_dir)
}

fn prepare_route_run_record(
    root: &Path,
    command: &str,
    task: &str,
    prompt: &str,
    options: Option<&PromptRunOptions>,
    existing: Option<PathBuf>,
) -> Result<PathBuf> {
    let run_dir = match existing {
        Some(run_dir) => run_dir,
        None => create_route_run_record(root, command, task, prompt, options)?,
    };
    fs::write(
        run_dir.join("intent-schema.json"),
        serde_json::to_string_pretty(&intent_model_json_schema())?,
    )?;
    if !run_dir.join("response.md").exists() {
        fs::write(run_dir.join("response.md"), "")?;
    }
    if !run_dir.join("provider.json").exists() {
        fs::write(
            run_dir.join("provider.json"),
            serde_json::to_string_pretty(&json!({
                "provider": "none",
                "model": null,
                "cache": "not-applicable",
                "attempts": 0,
                "elapsed_ms": 0,
                "tokens": null,
            }))?,
        )?;
    }
    Ok(run_dir)
}

fn issue_route_receipt(
    root: &Path,
    run_dir: &Path,
    task: &str,
    intent: Option<&IntentModel>,
    route_result: &str,
    lane: &str,
    owner_module: Option<&Path>,
    implementation_target: Option<&Path>,
    mut allowed_action_families: Vec<String>,
    target_paths: Vec<PathBuf>,
    scaffold: Option<ArchitectureAction>,
    repair_authority: Option<SpecRepairAuthority>,
) -> Result<RouteRunArtifacts> {
    let run_id = run_dir
        .file_name()
        .and_then(|value| value.to_str())
        .ok_or_else(|| anyhow!("run directory `{}` has no stable run ID", run_dir.display()))?
        .to_string();
    allowed_action_families.sort();
    allowed_action_families.dedup();
    let mut normalized_target_paths = target_paths
        .iter()
        .map(|path| normalize_receipt_target(root, path))
        .collect::<Result<Vec<_>>>()?;
    normalized_target_paths.sort();
    normalized_target_paths.dedup();
    let normalized_intent_value = serde_json::to_value(intent)?;
    let normalized_intent = serde_json::to_vec(&normalized_intent_value)?;
    let schema_bytes = serde_json::to_vec(&intent_model_json_schema())?;
    let payload = RouteReceiptPayload {
        schema: ROUTE_RECEIPT_SPEC.to_string(),
        run_id: run_id.clone(),
        issuing_rms_version: VALIDATOR_VERSION.to_string(),
        route_result: route_result.to_string(),
        task_sha256: sha256_bytes(task.as_bytes()),
        normalized_intent_sha256: sha256_bytes(&normalized_intent),
        intent_schema_sha256: sha256_bytes(&schema_bytes),
        extraction_prompt_version: INTENT_EXTRACTION_PROMPT_VERSION.to_string(),
        repository: route_repository_identity(root)?,
        git_head: route_git_head(root),
        lane: lane.to_string(),
        owner_module: owner_module
            .map(|path| normalize_receipt_target(root, path))
            .transpose()?,
        implementation_target: implementation_target
            .map(|path| normalize_receipt_target(root, path))
            .transpose()?,
        allowed_action_families,
        normalized_target_paths,
        scaffold,
        repair_authority,
    };
    let receipt_id = sha256_bytes(&serde_json::to_vec(&payload)?);
    let receipt = RouteReceipt {
        payload,
        receipt_id: receipt_id.clone(),
    };
    let receipt_path = run_dir.join("route-receipt.json");
    fs::write(&receipt_path, serde_json::to_string_pretty(&receipt)?)?;
    fs::write(
        run_dir.join("normalized-intent.json"),
        serde_json::to_string_pretty(&normalized_intent_value)?,
    )?;
    Ok(RouteRunArtifacts {
        run_id,
        run_dir: run_dir.to_path_buf(),
        receipt_id,
        receipt_path,
    })
}

fn resolve_route_receipt_path(root: &Path, reference: &Path) -> Result<PathBuf> {
    if reference.is_file() {
        return Ok(reference.to_path_buf());
    }
    if reference.is_dir() {
        return Ok(reference.join("route-receipt.json"));
    }
    if reference.components().count() == 1 {
        return Ok(root
            .join(resolve_run_root(root, None)?)
            .join(reference)
            .join("route-receipt.json"));
    }
    Ok(reference.to_path_buf())
}

fn validate_route_receipt(
    root: &Path,
    reference: &Path,
    action_family: &str,
    target: &Path,
    scaffold: Option<&ArchitectureAction>,
) -> Result<RouteReceipt> {
    let root = fs::canonicalize(root)
        .with_context(|| format!("failed to resolve repository root `{}`", root.display()))?;
    let path = resolve_route_receipt_path(&root, reference)?;
    let source = fs::read_to_string(&path)
        .with_context(|| format!("failed to read route receipt `{}`", path.display()))?;
    let receipt: RouteReceipt = serde_json::from_str(&source)
        .with_context(|| format!("invalid route receipt `{}`", path.display()))?;
    let expected_id = sha256_bytes(&serde_json::to_vec(&receipt.payload)?);
    if receipt.receipt_id != expected_id {
        bail!("route receipt digest does not match its canonical payload");
    }
    if receipt.payload.schema != ROUTE_RECEIPT_SPEC {
        bail!(
            "unsupported route receipt schema `{}`",
            receipt.payload.schema
        );
    }
    if receipt.payload.issuing_rms_version != VALIDATOR_VERSION {
        bail!(
            "route receipt was issued by RMS {}, current RMS is {}",
            receipt.payload.issuing_rms_version,
            VALIDATOR_VERSION
        );
    }
    if receipt.payload.route_result != "ready" {
        bail!(
            "route result `{}` cannot authorize a canonical mutation",
            receipt.payload.route_result
        );
    }
    if receipt.payload.repository != git_repository_identity(&root)? {
        bail!("route receipt repository identity does not match the current repository");
    }
    if receipt.payload.git_head != git_head(&root)? {
        bail!("route receipt Git HEAD is stale; route the exact task again");
    }
    if !receipt
        .payload
        .allowed_action_families
        .iter()
        .any(|allowed| allowed == action_family)
    {
        bail!("route receipt does not authorize action family `{action_family}`");
    }
    let normalized_target = normalize_receipt_target(&root, target)?;
    if !receipt
        .payload
        .normalized_target_paths
        .iter()
        .any(|allowed| allowed == &normalized_target)
    {
        bail!(
            "route receipt does not authorize target `{}`",
            target.display()
        );
    }
    if receipt.payload.scaffold.as_ref() != scaffold {
        bail!("route receipt scaffold arguments do not match the requested topology mutation");
    }
    let run_dir = path
        .parent()
        .ok_or_else(|| anyhow!("route receipt has no run directory"))?;
    let request: YamlValue =
        serde_yaml::from_str(&fs::read_to_string(run_dir.join("request.yaml"))?)?;
    let task = get_str(&request, &["task"])
        .ok_or_else(|| anyhow!("route run request does not preserve the exact task"))?;
    if sha256_bytes(task.as_bytes()) != receipt.payload.task_sha256 {
        bail!("route receipt task digest does not match its run record");
    }
    let normalized_intent = fs::read(run_dir.join("normalized-intent.json"))?;
    let normalized_intent: JsonValue = serde_json::from_slice(&normalized_intent)?;
    if sha256_bytes(&serde_json::to_vec(&normalized_intent)?)
        != receipt.payload.normalized_intent_sha256
    {
        bail!("route receipt normalized intent digest does not match its run record");
    }
    let schema: JsonValue = serde_json::from_slice(&fs::read(run_dir.join("intent-schema.json"))?)?;
    if sha256_bytes(&serde_json::to_vec(&schema)?) != receipt.payload.intent_schema_sha256 {
        bail!("route receipt intent schema digest does not match its run record");
    }
    if receipt.payload.extraction_prompt_version != INTENT_EXTRACTION_PROMPT_VERSION {
        bail!("route receipt extraction prompt version is stale");
    }
    Ok(receipt)
}

fn require_route_receipt(
    root: &Path,
    reference: &Path,
    action_family: &str,
    target: &Path,
    scaffold: Option<&ArchitectureAction>,
) -> RouteReceipt {
    match validate_route_receipt(root, reference, action_family, target, scaffold) {
        Ok(receipt) => receipt,
        Err(error) => {
            eprintln!("RMS route receipt rejected: {error:#}");
            std::process::exit(2);
        }
    }
}

fn validate_spec_change_route_receipt(
    root: &Path,
    reference: &Path,
    target: &Path,
    change_json: Option<&str>,
    change_yaml: Option<&str>,
    change_file: Option<&Path>,
) -> Result<RouteReceipt> {
    if let Ok(receipt) = validate_route_receipt(root, reference, "spec-apply", target, None) {
        return Ok(receipt);
    }
    let receipt = validate_route_receipt(root, reference, "spec-repair-apply", target, None)?;
    let expected = receipt
        .payload
        .repair_authority
        .as_ref()
        .ok_or_else(|| anyhow!("spec repair receipt has no signed repair authority"))?;
    if expected.kind != "contract-behavior-cases" {
        bail!("unsupported spec repair authority `{}`", expected.kind);
    }
    let diagnostics = collect_validation_diagnostics(
        root,
        Vec::new(),
        Vec::new(),
        Vec::new(),
        Vec::new(),
        Vec::new(),
        Vec::new(),
    )?;
    let current = build_contract_behavior_case_repair_authority(root, target, &diagnostics)?;
    if &current != expected {
        bail!(
            "spec repair authority is stale: the blocker fingerprint, owned contract sources, paths, or case ids changed; route the exact repair task again"
        );
    }
    let context = load_spec_target(target)?;
    let change = prepare_semantic_change_for_apply(
        &context,
        parse_semantic_change(change_json, change_yaml, change_file)?,
    );
    validate_contract_behavior_case_repair_change(root, &context, &change, expected)?;
    Ok(receipt)
}

fn require_spec_change_route_receipt(
    root: &Path,
    reference: &Path,
    target: &Path,
    change_json: Option<&str>,
    change_yaml: Option<&str>,
    change_file: Option<&Path>,
) -> RouteReceipt {
    match validate_spec_change_route_receipt(
        root,
        reference,
        target,
        change_json,
        change_yaml,
        change_file,
    ) {
        Ok(receipt) => receipt,
        Err(error) => {
            eprintln!("RMS route receipt rejected: {error:#}");
            std::process::exit(2);
        }
    }
}

fn validate_contract_behavior_case_repair_change(
    root: &Path,
    context: &SpecTargetContext,
    change: &SemanticChange,
    authority: &SpecRepairAuthority,
) -> Result<()> {
    let value = serde_json::to_value(change)?;
    let object = value
        .as_object()
        .ok_or_else(|| anyhow!("semantic change is not an object"))?;
    for (field, value) in object {
        if matches!(
            field.as_str(),
            "spec" | "module" | "supersedes" | "intent" | "contracts" | "evidence"
        ) {
            continue;
        }
        if json_value_has_material_operation(value) {
            bail!(
                "spec repair receipt permits only contracts.set and already-declared contract evidence; `{field}` contains an operation"
            );
        }
    }

    let contracts = change
        .contracts
        .as_ref()
        .ok_or_else(|| anyhow!("spec repair requires contracts.set"))?;
    if !contracts.add.is_empty() || !contracts.remove.is_empty() || contracts.replace.is_empty() {
        bail!("spec repair requires only a nonempty contracts.set operation");
    }
    let module = context
        .module
        .as_ref()
        .ok_or_else(|| anyhow!("spec repair target is not a module manifest"))?;
    let base = module.path.parent().unwrap_or(root);
    let expected_paths = authority
        .contracts
        .iter()
        .map(|contract| contract.path.as_str())
        .collect::<BTreeSet<_>>();
    let proposed_paths = contracts
        .replace
        .iter()
        .map(|contract| {
            normalize_receipt_target(
                root,
                &base.join(semantic_contract_change_path(&module.value, contract)),
            )
        })
        .collect::<Result<BTreeSet<_>>>()?;
    if proposed_paths
        .iter()
        .map(String::as_str)
        .collect::<BTreeSet<_>>()
        != expected_paths
    {
        bail!("spec repair must set every and only the signed invalid contract paths");
    }

    for proposed in &contracts.replace {
        let relative = normalize_receipt_target(
            root,
            &base.join(semantic_contract_change_path(&module.value, proposed)),
        )?;
        let signed = authority
            .contracts
            .iter()
            .find(|contract| contract.path == relative)
            .ok_or_else(|| anyhow!("contract `{relative}` is outside signed repair authority"))?;
        let current = load_manifest(&root.join(&relative))?;
        let contract_spec = get_str(&current.value, &["spec"])
            .filter(|spec| behavioral_contract::is_contract_spec(Some(spec)))
            .unwrap_or(behavioral_contract::CONTRACT_SPEC);
        let rendered: YamlValue =
            serde_yaml::from_str(&render_semantic_contract_for_spec(proposed, contract_spec))?;
        validate_contract_behavior_case_repair_pair(&current.value, &rendered, signed)?;
        if proposed
            .command
            .as_deref()
            .is_some_and(|command| command != proposed.name)
            || !proposed.accepts.is_empty()
            || !proposed.ensures.is_empty()
            || !proposed.rejects.is_empty()
        {
            bail!(
                "spec repair contract `{}` may not use legacy clauses or rename its command",
                proposed.name
            );
        }
    }

    let evidence = change
        .evidence
        .as_ref()
        .ok_or_else(|| anyhow!("each repaired contract requires its already-declared evidence"))?;
    if !evidence.remove.is_empty() || evidence.add.len() != contracts.replace.len() {
        bail!("spec repair must preserve evidence and cite exactly one existing item per contract");
    }
    let declared_evidence = module_verification_references(&module.value);
    let repaired_names = contracts
        .replace
        .iter()
        .map(|contract| contract.name.as_str())
        .collect::<BTreeSet<_>>();
    let proved = evidence
        .add
        .iter()
        .map(|item| item.proves.as_str())
        .collect::<BTreeSet<_>>();
    if proved != repaired_names
        || evidence
            .add
            .iter()
            .any(|item| !declared_evidence.contains(&item.path) || !base.join(&item.path).exists())
    {
        bail!(
            "spec repair evidence must prove each repaired contract through an existing declared path"
        );
    }
    Ok(())
}

fn json_value_has_material_operation(value: &JsonValue) -> bool {
    match value {
        JsonValue::Null => false,
        JsonValue::Bool(value) => *value,
        JsonValue::String(value) => !value.is_empty(),
        JsonValue::Array(values) => values.iter().any(json_value_has_material_operation),
        JsonValue::Object(values) => values.values().any(json_value_has_material_operation),
        JsonValue::Number(_) => true,
    }
}

fn validate_contract_behavior_case_repair_pair(
    current: &YamlValue,
    proposed: &YamlValue,
    authority: &SpecRepairContractAuthority,
) -> Result<()> {
    let mut current_top = current
        .as_mapping()
        .cloned()
        .ok_or_else(|| anyhow!("current contract is not an object"))?;
    let mut proposed_top = proposed
        .as_mapping()
        .cloned()
        .ok_or_else(|| anyhow!("proposed contract is not an object"))?;
    current_top.remove(&yaml_key("semantics"));
    proposed_top.remove(&yaml_key("semantics"));
    if current_top != proposed_top {
        bail!("spec repair may not change contract identity, meaning, compatibility, or metadata");
    }

    let mut current_semantics = get_path(current, &["semantics"])
        .and_then(YamlValue::as_mapping)
        .cloned()
        .ok_or_else(|| anyhow!("current contract semantics are not an object"))?;
    let mut proposed_semantics = get_path(proposed, &["semantics"])
        .and_then(YamlValue::as_mapping)
        .cloned()
        .ok_or_else(|| anyhow!("proposed contract semantics are not an object"))?;
    let current_behavior = current_semantics
        .remove(&yaml_key("behavior"))
        .and_then(|value| value.as_mapping().cloned())
        .ok_or_else(|| anyhow!("current contract behavior is not an object"))?;
    let proposed_behavior = proposed_semantics
        .remove(&yaml_key("behavior"))
        .and_then(|value| value.as_mapping().cloned())
        .ok_or_else(|| anyhow!("proposed contract behavior is not an object"))?;
    if current_semantics != proposed_semantics {
        bail!("spec repair may not change non-behavior contract semantics");
    }
    let mut current_protected = current_behavior.clone();
    current_protected.remove(&yaml_key("observations"));
    current_protected.remove(&yaml_key("cases"));
    let mut proposed_protected = proposed_behavior.clone();
    proposed_protected.remove(&yaml_key("observations"));
    proposed_protected.remove(&yaml_key("cases"));
    if current_protected != proposed_protected {
        bail!("spec repair may not change requirements, guarantees, failures, invariants, or case policy");
    }
    let observations = proposed_behavior
        .get(&yaml_key("observations"))
        .and_then(YamlValue::as_sequence)
        .ok_or_else(|| anyhow!("spec repair must provide behavior observations"))?;
    if observations.is_empty() {
        bail!("spec repair must provide at least one behavior observation");
    }
    let current_cases = contract_case_id_statements(&current_behavior)?;
    let proposed_cases = contract_case_id_statements(&proposed_behavior)?;
    if current_cases != proposed_cases {
        bail!("spec repair must preserve every case id, statement, and order");
    }
    if proposed_cases.iter().map(|(id, _)| id).collect::<Vec<_>>()
        != authority.case_ids.iter().collect::<Vec<_>>()
    {
        bail!("spec repair case ids do not match the signed repair authority");
    }
    Ok(())
}

fn contract_case_id_statements(behavior: &serde_yaml::Mapping) -> Result<Vec<(String, String)>> {
    behavior
        .get(&yaml_key("cases"))
        .and_then(YamlValue::as_sequence)
        .ok_or_else(|| anyhow!("contract behavior cases are not a sequence"))?
        .iter()
        .map(|case| {
            Ok((
                get_str(case, &["id"])
                    .ok_or_else(|| anyhow!("contract case has no id"))?
                    .to_string(),
                get_str(case, &["statement"])
                    .ok_or_else(|| anyhow!("contract case has no statement"))?
                    .to_string(),
            ))
        })
        .collect()
}

fn validate_machine_change_route_receipt(
    root: &Path,
    reference: &Path,
    target: &Path,
    change: &MachineChange,
) -> Result<RouteReceipt> {
    let receipt = validate_route_receipt(root, reference, "machine-apply", target, None)?;
    let root = fs::canonicalize(root)
        .with_context(|| format!("failed to resolve repository root `{}`", root.display()))?;
    let receipt_path = resolve_route_receipt_path(&root, reference)?;
    let run_dir = receipt_path
        .parent()
        .ok_or_else(|| anyhow!("route receipt has no run directory"))?;
    let request: YamlValue =
        serde_yaml::from_str(&fs::read_to_string(run_dir.join("request.yaml"))?)?;
    let task = get_str(&request, &["task"])
        .ok_or_else(|| anyhow!("route run request does not preserve the exact task"))?;
    let intent: IntentModel =
        serde_json::from_slice(&fs::read(run_dir.join("normalized-intent.json"))?)
            .context("route run normalized intent is not an rms/intent-model/v0.1 object")?;
    let manifest = load_manifest(target)?;
    validate_machine_change_intent_anchors(&manifest, change, task, &intent)?;
    Ok(receipt)
}

fn require_machine_change_route_receipt(
    root: &Path,
    reference: &Path,
    target: &Path,
    change: &MachineChange,
) -> RouteReceipt {
    match validate_machine_change_route_receipt(root, reference, target, change) {
        Ok(receipt) => receipt,
        Err(error) => {
            eprintln!("RMS route receipt rejected: {error:#}");
            std::process::exit(2);
        }
    }
}

#[derive(Default)]
struct MachineIntentAnchors {
    states: BTreeSet<String>,
    inputs: BTreeSet<String>,
    events: BTreeSet<String>,
    commands: BTreeSet<String>,
    effects: BTreeSet<String>,
    replies: BTreeSet<String>,
    rejections: BTreeSet<String>,
    cases: BTreeSet<String>,
}

fn validate_machine_change_intent_anchors(
    manifest: &LoadedManifest,
    change: &MachineChange,
    task: &str,
    intent: &IntentModel,
) -> Result<()> {
    let anchors = machine_intent_anchors(manifest, change, task, intent);
    // Exact transition-case identifiers are the review boundary that lets RMS
    // bind a route receipt to a concrete machine delta without guessing at the
    // semantics of prose-only tasks. Broader tasks retain the existing
    // owner/action/target receipt scope and require an explicit plan review.
    if anchors.cases.is_empty() {
        return Ok(());
    }
    let delta = machine_transition_delta(manifest, change)?;
    let mut realized = MachineIntentAnchors::default();
    for transition in &delta {
        realized
            .states
            .insert(semantic_id_segment(&transition.from));
        realized.states.insert(semantic_id_segment(&transition.to));
        realized
            .inputs
            .insert(semantic_id_segment(&transition_input_variant(
                &transition.on,
            )));
        realized.events.extend(
            transition
                .events
                .iter()
                .map(|item| semantic_id_segment(item)),
        );
        realized.commands.extend(
            transition
                .commands
                .iter()
                .map(|item| semantic_id_segment(item)),
        );
        realized.effects.extend(
            transition
                .effects
                .iter()
                .map(|item| semantic_id_segment(item)),
        );
        if let Some(reply) = &transition.reply {
            realized.replies.insert(semantic_id_segment(reply));
        }
        if let Some(rejection) = &transition.rejection {
            realized.rejections.insert(semantic_id_segment(rejection));
        }
        if let Some(case) = &transition.case {
            realized.cases.insert(semantic_id_segment(case));
        }
    }

    for (kind, expected, observed) in [
        ("state", &anchors.states, &realized.states),
        ("input", &anchors.inputs, &realized.inputs),
        ("event", &anchors.events, &realized.events),
        ("command", &anchors.commands, &realized.commands),
        ("effect", &anchors.effects, &realized.effects),
        ("reply", &anchors.replies, &realized.replies),
        ("rejection", &anchors.rejections, &realized.rejections),
        ("transition case", &anchors.cases, &realized.cases),
    ] {
        for missing in expected.difference(observed) {
            bail!(
                "machine change does not realize reviewed {kind} intent anchor `{missing}` from the route receipt"
            );
        }
    }

    if !anchors.cases.is_empty() {
        for transition in &delta {
            let case = transition
                .case
                .as_deref()
                .map(semantic_id_segment)
                .unwrap_or_else(|| "<missing>".to_string());
            if !anchors.cases.contains(&case) {
                bail!(
                    "machine transition case `{case}` is outside reviewed route-receipt case anchor(s): {}",
                    anchors.cases.iter().cloned().collect::<Vec<_>>().join(", ")
                );
            }
        }
    }
    Ok(())
}

fn machine_intent_anchors(
    manifest: &LoadedManifest,
    change: &MachineChange,
    task: &str,
    intent: &IntentModel,
) -> MachineIntentAnchors {
    let intent_ids = intent
        .subjects
        .iter()
        .chain(intent.responsibilities.iter().map(|item| &item.id))
        .map(|item| semantic_id_segment(item))
        .collect::<BTreeSet<_>>();
    let mut anchors = MachineIntentAnchors::default();
    let collect_variants = |field: &str, destination: &mut BTreeSet<String>, ready_fallback| {
        for variant in final_machine_variant_values(
            manifest,
            field,
            machine_variant_change(change, field),
            ready_fallback,
        ) {
            let normalized = semantic_id_segment(&variant);
            if intent_ids.contains(&normalized) {
                destination.insert(normalized);
            }
        }
    };
    collect_variants("states", &mut anchors.states, true);
    collect_variants("commands", &mut anchors.inputs, false);
    collect_variants("observed_events", &mut anchors.inputs, false);
    collect_variants("effect_results", &mut anchors.inputs, false);
    collect_variants("events", &mut anchors.events, false);
    collect_variants("effects", &mut anchors.effects, false);
    collect_variants("replies", &mut anchors.replies, false);
    collect_variants("rejections", &mut anchors.rejections, false);

    for token in
        task.split(|character: char| !(character.is_ascii_alphanumeric() || character == '_'))
    {
        if token.contains('_') && is_stable_identifier(token) {
            let normalized = semantic_id_segment(token);
            if intent_ids.contains(&normalized) {
                anchors.cases.insert(normalized);
            }
        }
    }
    anchors
}

fn machine_variant_change<'a>(
    change: &'a MachineChange,
    field: &str,
) -> &'a MachineVariantListChange {
    match field {
        "states" => &change.machine.states,
        "commands" => &change.machine.commands,
        "observed_events" => &change.machine.observed_events,
        "events" => &change.machine.events,
        "effects" => &change.machine.effects,
        "effect_results" => &change.machine.effect_results,
        "replies" => &change.machine.replies,
        "rejections" => &change.machine.rejections,
        _ => unreachable!("closed machine variant field"),
    }
}

fn machine_transition_delta(
    manifest: &LoadedManifest,
    change: &MachineChange,
) -> Result<Vec<MachineTransitionChange>> {
    let existing = existing_machine_transitions(manifest);
    let final_values = final_machine_transitions_without_diagnostics(manifest, change);
    let existing_by_value = existing
        .iter()
        .map(|transition| Ok((serde_json::to_string(transition)?, transition)))
        .collect::<Result<BTreeMap<_, _>>>()?;
    let final_by_value = final_values
        .iter()
        .map(|transition| Ok((serde_json::to_string(transition)?, transition)))
        .collect::<Result<BTreeMap<_, _>>>()?;
    Ok(existing_by_value
        .iter()
        .filter(|(key, _)| !final_by_value.contains_key(*key))
        .map(|(_, transition)| (*transition).clone())
        .chain(
            final_by_value
                .iter()
                .filter(|(key, _)| !existing_by_value.contains_key(*key))
                .map(|(_, transition)| (*transition).clone()),
        )
        .collect())
}

fn repository_root_for_target(target: &Path) -> Result<PathBuf> {
    let start = if target.is_dir() {
        target
    } else {
        target.parent().unwrap_or_else(|| Path::new("."))
    };
    Ok(PathBuf::from(git_repository_identity(start)?))
}

#[cfg(test)]
fn generate_route_receipt_validation_cases() -> Vec<String> {
    let dimensions = [
        ("status", ["matching", "mismatching"]),
        ("root", ["matching", "mismatching"]),
        ("head", ["matching", "mismatching"]),
        ("owner", ["matching", "mismatching"]),
        ("action", ["matching", "mismatching"]),
        ("target", ["matching", "mismatching"]),
        ("digest", ["matching", "mismatching"]),
        ("scaffold", ["matching", "mismatching"]),
    ];
    let mut cases = Vec::new();
    for (dimension, values) in dimensions {
        for value in values {
            cases.push(format!("{dimension}:{value}"));
        }
    }
    cases
}

#[cfg(test)]
fn generate_intent_cache_cases() -> Vec<String> {
    let outcomes = ["valid", "repairable", "invalid", "material-unknown"];
    let cache_states = ["miss", "hit", "refresh", "concurrent"];
    let mut cases = Vec::new();
    for outcome in outcomes {
        for cache_state in cache_states {
            cases.push(format!("{outcome}:{cache_state}"));
        }
    }
    cases
}

