    #[test]
    fn extracts_public_modules_from_rust_entrypoint() {
        let modules = public_modules_declared_in_source(
            r#"
pub mod widget;
pub(crate) mod private;
pub mod nested {
}
"#,
        );

        assert!(modules.contains("widget"));
        assert!(modules.contains("nested"));
        assert!(!modules.contains("private"));
    }

    #[test]
    fn parses_public_and_private_rust_import_roots() {
        let file = syn::parse_file(
            r#"
use serde::{Deserialize, Serialize};
pub use widget::Widget;
pub use external_crate::Thing;
"#,
        )
        .unwrap();

        let imports = collect_rust_imports(&file);

        assert!(imports
            .iter()
            .any(|import| import.root == "serde" && !import.is_public));
        assert!(imports
            .iter()
            .any(|import| import.root == "widget" && import.is_public));
        assert!(imports
            .iter()
            .any(|import| import.root == "external_crate" && import.is_public));
    }

    #[test]
    fn classifies_local_and_external_rust_imports() {
        let local_modules = BTreeSet::from(["widget".to_string()]);

        assert_eq!(
            rust_import_root_kind("widget", &local_modules),
            RustImportRootKind::LocalModule
        );
        assert_eq!(
            rust_import_root_kind("serde", &local_modules),
            RustImportRootKind::External
        );
        assert_eq!(
            rust_import_root_kind("std", &local_modules),
            RustImportRootKind::Standard
        );
        assert_eq!(
            rust_import_root_kind("crate", &local_modules),
            RustImportRootKind::SelfQualified
        );
    }

    #[test]
    fn rust_source_boundaries_accept_bin_importing_own_library_crate() {
        let root = unique_test_dir("rust-own-crate-import");
        fs::create_dir_all(root.join("src")).unwrap();
        fs::write(
            root.join("Cargo.toml"),
            r#"[package]
name = "checkout-boundary"
version = "0.1.0"
edition = "2021"

[lib]
path = "src/lib.rs"
"#,
        )
        .unwrap();
        fs::write(
            root.join("src/lib.rs"),
            r#"pub enum CheckoutBoundaryState { AwaitingInput, Completed }
pub enum CheckoutBoundaryCommand { Run }
pub enum CheckoutBoundaryInput { Command(CheckoutBoundaryCommand) }
pub enum CheckoutBoundaryEvent { Completed }
pub enum CheckoutBoundaryReply { Accepted }
pub enum CheckoutBoundaryRejection { Rejected }
pub struct CheckoutBoundaryTransition { rejection: Option<CheckoutBoundaryRejection> }
pub enum CheckoutBoundaryTransitionRecord { Accepted }
pub struct CheckoutBoundaryMachine;

pub fn transition(
    _state: CheckoutBoundaryState,
    _input: CheckoutBoundaryInput,
) -> CheckoutBoundaryTransition {
    CheckoutBoundaryTransition { rejection: None }
}

pub fn run() {}
"#,
        )
        .unwrap();
        fs::write(
            root.join("src/main.rs"),
            "use checkout_boundary::run;\nfn main() { run(); }\n",
        )
        .unwrap();
        fs::write(
            root.join("implementation.yaml"),
            r#"spec: rms/implementation/v0.1
module: "checkout-boundary"
binding: rust
source:
  root: .
  public_entrypoint: src/lib.rs
commands:
  build: cargo build --manifest-path Cargo.toml
  verify: cargo test --manifest-path Cargo.toml
toolchain:
  cargo_manifest: Cargo.toml
  package: checkout-boundary
dependencies:
  allowed_external_crates: []
architecture:
  shape: boundary-adapter
  public_modules: []
  machine:
    name: CheckoutBoundaryMachine
    mode: boundary-machine
    transition_signature: state-and-input
    types:
      state: CheckoutBoundaryState
      input: CheckoutBoundaryInput
      command: CheckoutBoundaryCommand
      event: CheckoutBoundaryEvent
      reply: CheckoutBoundaryReply
      rejection: CheckoutBoundaryRejection
      transition: CheckoutBoundaryTransition
      transition_record: CheckoutBoundaryTransitionRecord
    states: [AwaitingInput, Completed]
    commands: [Run]
    observed_events: []
    events: [Completed]
    effects: []
    effect_results: []
    replies: [Accepted]
    rejections: [Rejected]
    effect_protocols: []
    transition_function: transition
    transitions:
      - from: AwaitingInput
        on: Run
        to: Completed
        events: [Completed]
        reply: Accepted
  roles:
    representation: [src/lib.rs]
    parser: [src/lib.rs]
    transition: [src/lib.rs]
    adapter: [src/lib.rs]
"#,
        )
        .unwrap();
        write_probe_fixture_support(&root);
        let manifest = load_manifest(&root.join("implementation.yaml")).unwrap();
        let mut diagnostics = Vec::new();

        validate_loaded_manifest(&manifest, &mut diagnostics);

        fs::remove_dir_all(&root).unwrap();
        assert!(
            diagnostics
                .iter()
                .all(|diagnostic| diagnostic.check != "implementation.rust.imports.declared"),
            "{:#?}",
            diagnostics
        );
        assert_no_error_diagnostics(&diagnostics);
    }

    #[test]
    fn parses_swift_imports_and_public_reexports() {
        let imports = collect_swift_imports(
            r#"
import Foundation
import struct ExternalKit.Widget
@_exported import PublicKit
"#,
        );

        assert!(imports
            .iter()
            .any(|import| import.module == "Foundation" && !import.is_public_reexport));
        assert!(imports
            .iter()
            .any(|import| import.module == "ExternalKit" && !import.is_public_reexport));
        assert!(imports
            .iter()
            .any(|import| import.module == "PublicKit" && import.is_public_reexport));
    }

