    #[test]
    fn init_scaffold_generates_valid_system_artifacts() {
        let root = unique_test_dir("init");

        run_init(
            &root,
            "example-system",
            "Demonstrate RMS initialization.",
            "0.1.0",
            &[String::from("example")],
        )
        .unwrap();

        let mut diagnostics = Vec::new();
        for file in ["system.yaml", "context-map.yaml"] {
            let manifest = load_manifest(&root.join(file)).unwrap();
            validate_loaded_manifest(&manifest, &mut diagnostics);
        }

        let agents = fs::read_to_string(root.join("AGENTS.md")).unwrap();
        let gitignore = fs::read_to_string(root.join(".gitignore")).unwrap();
        let config_text = fs::read_to_string(root.join(".rms/config.yaml")).unwrap();
        let config = load_workbench_config(&root).unwrap().unwrap();
        let git_initialized = root.join(".git").is_dir();
        for (relative_path, contents) in INIT_AGENT_SKILLS {
            let generated =
                fs::read_to_string(root.join(".agents").join("skills").join(relative_path))
                    .unwrap();
            assert_eq!(generated, *contents);
        }

        fs::remove_dir_all(&root).unwrap();
        assert!(diagnostics.is_empty(), "{diagnostics:#?}");
        assert!(git_initialized);
        assert_eq!(agents, INIT_AGENTS_MD);
        assert_eq!(
            agents
                .lines()
                .filter_map(|line| line.strip_prefix("## "))
                .collect::<Vec<_>>(),
            [
                "RMS Self-Application Boundary",
                "Authority",
                "Start / Route",
                "Change Gate",
                "Hard Boundaries",
                "Completion",
            ]
        );
        assert!(agents.lines().count() <= 70);
        assert!(agents.len() <= 8 * 1024);
        assert!(agents.contains("rms next \"<exact change task>\" --root . --ai"));
        assert!(agents.contains("Do not invoke RMS for read-only investigation"));
        assert!(agents.contains("stop before editing"));
        assert!(agents.contains(COMMIT_AUTHORITY_POLICY));
        assert!(agents.contains(BOOTSTRAP_PENDING_AUTHORIZED_COMMIT));
        assert!(agents.contains(CANDIDATE_PENDING_AUTHORIZED_COMMIT));
        assert!(agents.contains("New or adopted systems follow `rms init [--adopt]`"));
        assert!(agents.contains("schema-constrained extraction"));
        assert!(agents.contains("--route-receipt"));
        assert!(agents.contains("recommended standalone or recursive scaffold"));
        assert!(agents.contains("focused native and RMS proof"));
        assert!(agents.contains("authorized candidate commit"));
        assert!(agents.contains("rms check --changes --root ."));
        assert!(agents.contains("rms check --committed --root ."));
        assert!(gitignore.contains(".rms/runs/"));
        assert!(gitignore.contains(".rms/cache/"));
        assert!(gitignore.contains(".rms/evidence/"));
        assert!(gitignore.contains(".rms/hunts/"));
        assert!(gitignore.contains(".rms/dogfood/"));
        assert!(config_text.contains("# write_scope: module"));
        assert!(config_text.contains("# timeout_seconds: 900"));
        assert_eq!(config.value.ai.default_provider.as_deref(), Some("codex"));
        assert_eq!(config.value.ai.codex.sandbox.as_deref(), Some("read-only"));
        assert_eq!(config.value.workspace.coverage, WorkspaceCoverage::Complete);
        assert_eq!(
            config.value.runs.directory.as_deref(),
            Some(Path::new(".rms/runs"))
        );
    }

    #[test]
    fn init_reuses_parent_git_worktree_without_nested_repository() {
        let root = unique_test_dir("init-parent-git");
        fs::create_dir_all(&root).unwrap();
        let initialized = Command::new("git")
            .current_dir(&root)
            .arg("init")
            .output()
            .unwrap();
        assert!(initialized.status.success());
        let child = root.join("child");

        run_init(
            &child,
            "nested-system",
            "Exercise nested RMS initialization.",
            "0.1.0",
            &[String::from("nested")],
        )
        .unwrap();

        let worktree = Command::new("git")
            .current_dir(&child)
            .args(["rev-parse", "--show-toplevel"])
            .output()
            .unwrap();
        let discovered = PathBuf::from(String::from_utf8_lossy(&worktree.stdout).trim());
        let expected = root.canonicalize().unwrap();
        let nested_repository = child.join(".git").exists();

        fs::remove_dir_all(&root).unwrap();
        assert!(worktree.status.success());
        assert_eq!(discovered, expected);
        assert!(!nested_repository);
    }

    #[test]
    fn init_reports_bootstrap_pending_authorized_commit() {
        let root = unique_test_dir("init-authorized-provenance");

        run_init(
            &root,
            "authorized-provenance",
            "Prepare provenance without granting commit authority.",
            "0.1.0",
            &[String::from("core")],
        )
        .unwrap();

        let completion = init_completion_lines();
        assert_eq!(completion[0], BOOTSTRAP_PENDING_AUTHORIZED_COMMIT);
        assert_eq!(completion[1], COMMIT_AUTHORITY_POLICY);
        assert_eq!(
            completion[2],
            "onboarding order: init -> authorized bootstrap commit -> `rms design --root . --task \"<exact user task>\" --ai` -> recommended scaffold with `--route-receipt`"
        );
        assert!(root.join(".git").is_dir());
        assert!(source_revision(&root).is_none());
        let head = Command::new("git")
            .current_dir(&root)
            .args(["rev-parse", "--verify", "HEAD"])
            .output()
            .unwrap();
        assert!(!head.status.success());

        let next = build_next_report(&root, None, "design a core capability").unwrap();
        assert_eq!(next.result, NextResult::DesignRequired);
        assert_eq!(
            next.completion.pending_state,
            Some(BOOTSTRAP_PENDING_AUTHORIZED_COMMIT)
        );
        let declare = &next.steps[1].steps;
        let bootstrap_index = declare
            .iter()
            .position(|step| step.description == BOOTSTRAP_PENDING_AUTHORIZED_COMMIT)
            .unwrap();
        let design_index = declare
            .iter()
            .position(|step| {
                step.args
                    .first()
                    .is_some_and(|argument| argument == "design")
            })
            .unwrap();
        assert!(bootstrap_index < design_index);

        let guidance = fs::read_to_string(root.join("AGENTS.md")).unwrap();
        ensure_document_markers(
            "generated AGENTS.md",
            &guidance,
            &[
                "rms init [--adopt]",
                "authorized bootstrap commit",
                "rms design",
                "recommended standalone or recursive scaffold",
            ],
        )
        .unwrap();
        assert!(guidance.contains(BOOTSTRAP_PENDING_AUTHORIZED_COMMIT));
        assert!(guidance.contains(COMMIT_AUTHORITY_POLICY));
        assert!(!completion
            .iter()
            .any(|line| line.contains("production-ready")));

        fs::remove_dir_all(&root).unwrap();
    }

    #[test]
    fn init_adopt_preserves_existing_documents_and_creates_only_missing_artifacts() {
        let root = unique_test_dir("init-adopt-documents");
        fs::create_dir_all(&root).unwrap();
        let glossary = b"# Existing Language\n\nA project-owned glossary.\n";
        let agents = b"# Existing Agent Instructions\n\nKeep this project policy.\n";
        let gitignore = b"vendor/\n";
        fs::write(root.join("GLOSSARY.md"), glossary).unwrap();
        fs::write(root.join("AGENTS.md"), agents).unwrap();
        fs::write(root.join(".gitignore"), gitignore).unwrap();

        run_init_with_adopt(
            &root,
            "adopted-system",
            "Adopt an existing project safely.",
            "0.1.0",
            &[String::from("adopted")],
            true,
        )
        .unwrap();

        assert_eq!(fs::read(root.join("GLOSSARY.md")).unwrap(), glossary);
        let adopted_agents = fs::read(root.join("AGENTS.md")).unwrap();
        let adopted_gitignore = fs::read(root.join(".gitignore")).unwrap();
        assert!(adopted_agents.starts_with(agents));
        assert!(adopted_gitignore.starts_with(gitignore));
        assert_eq!(
            String::from_utf8_lossy(&adopted_agents)
                .matches(RMS_MANAGED_AGENTS_START)
                .count(),
            1
        );
        assert_eq!(
            String::from_utf8_lossy(&adopted_gitignore)
                .matches(RMS_MANAGED_GITIGNORE_START)
                .count(),
            1
        );
        assert!(String::from_utf8_lossy(&adopted_gitignore).contains(".rms/hunts/"));
        assert!(String::from_utf8_lossy(&adopted_gitignore).contains(".rms/evidence/"));
        assert!(root.join("system.yaml").is_file());
        assert!(root.join("context-map.yaml").is_file());
        assert!(root.join(".rms/config.yaml").is_file());
        assert!(root.join(".agents/skills/README.md").is_file());
        assert!(root.join(".git").is_dir());
        let adoption = build_adoption_status(&root, None).unwrap();
        assert_eq!(adoption.coverage, "progressive");
        assert!(adoption
            .certifies
            .contains("discovered RMS modules and their declared dependency closures"));

        run_agent_sync(&root, AgentTarget::Codex).unwrap();
        let synced_agents = fs::read(root.join("AGENTS.md")).unwrap();
        assert!(synced_agents.starts_with(agents));
        assert_eq!(
            String::from_utf8_lossy(&synced_agents)
                .matches(RMS_MANAGED_AGENTS_START)
                .count(),
            1
        );

        fs::remove_dir_all(&root).unwrap();
    }

