    #[test]
    fn adoption_complete_rejects_unowned_production_paths() {
        let root = unique_test_dir("adoption-unowned-production");
        fs::create_dir_all(root.join("Sources/Legacy")).unwrap();
        fs::write(
            root.join("Sources/Legacy/Legacy.swift"),
            "struct Legacy {}\n",
        )
        .unwrap();
        run_init_with_adopt(
            &root,
            "progressive-system",
            "Adopt one module closure progressively.",
            "0.1.0",
            &[],
            true,
        )
        .unwrap();

        let progressive = build_adoption_status(&root, None).unwrap();
        let complete = build_adoption_status(&root, Some(WorkspaceCoverage::Complete)).unwrap();

        fs::remove_dir_all(&root).unwrap();
        assert_eq!(progressive.result, "pass");
        assert_eq!(progressive.coverage, "progressive");
        assert_eq!(complete.result, "blocked");
        assert!(complete
            .diagnostics
            .iter()
            .any(|item| item.check == "adoption.unowned-production-path"));
    }

    #[test]
    fn progressive_committed_check_executes_one_root_audit_and_projects_each_closure() {
        let root = unique_test_dir("progressive-single-root-audit");
        run_init(
            &root,
            "progressive-system",
            "Certify multiple adopted module closures.",
            "0.1.0",
            &[],
        )
        .unwrap();
        for name in ["first-owner", "second-owner"] {
            run_add_module(
                add_module_request(
                    &root.join("modules").join(name),
                    name,
                    "Own one independent decision boundary.",
                    "library",
                    &[],
                    Some(ScaffoldShape::DomainEngine),
                    None,
                ),
                &no_provider_options(),
            )
            .unwrap();
        }
        let first = root.join("modules/first-owner/module.yaml");
        let second = root.join("modules/second-owner/module.yaml");
        let audit_calls = std::cell::Cell::new(0usize);
        let audit = AuditReport {
            result: "pass".to_string(),
            root: root.display().to_string(),
            strict: true,
            source_revision: "git:fixture".to_string(),
            checks: vec![
                audit_check(
                    "provenance.source-revision",
                    "provenance",
                    "pass",
                    &root,
                    "fixture revision",
                ),
                audit_check("first-proof", "proof", "pass", &first, "first closure"),
                audit_check("second-proof", "proof", "pass", &second, "second closure"),
            ],
            verification_targets: vec![first.display().to_string(), second.display().to_string()],
        };

        let report = build_progressive_workspace_check_report_with_audit(
            &root,
            CheckMode::Committed,
            None,
            || {
                audit_calls.set(audit_calls.get() + 1);
                Ok(audit)
            },
        )
        .unwrap();

        assert_eq!(audit_calls.get(), 1);
        let module_reports = report.details["module_reports"].as_array().unwrap();
        assert_eq!(module_reports.len(), 2);
        for module_report in module_reports {
            let requested = module_report["requested_module"].as_str().unwrap();
            let checks = module_report["audit"]["checks"].as_array().unwrap();
            assert!(checks
                .iter()
                .any(|check| check["id"] == "provenance.source-revision"));
            assert!(checks
                .iter()
                .any(|check| check["id"]
                    == format!("{}-proof", requested.trim_end_matches("-owner"))));
            assert!(!checks.iter().any(|check| {
                check["id"]
                    == if requested == "first-owner" {
                        "second-proof"
                    } else {
                        "first-proof"
                    }
            }));
        }

        fs::remove_dir_all(&root).unwrap();
    }

    #[test]
    fn changes_check_rejects_static_proof_debt_before_the_candidate_commit() {
        let root = unique_test_dir("changes-static-proof-debt");
        run_init(
            &root,
            "candidate-proof-system",
            "Reject unresolved candidate evidence before commit.",
            "0.1.0",
            &[],
        )
        .unwrap();
        let module_root = root.join("modules/candidate-owner");
        run_add_module(
            add_module_request(
                &module_root,
                "candidate-owner",
                "Own one candidate decision.",
                "library",
                &[],
                Some(ScaffoldShape::DomainEngine),
                Some("rust"),
            ),
            &no_provider_options(),
        )
        .unwrap();

        let module_path = module_root.join("module.yaml");
        let mut module = load_manifest(&module_path).unwrap().value;
        let unresolved_property: YamlValue = serde_yaml::from_str(
            r#"id: candidate-proof-property
proves: transition-trace
kind: semantic
input_space:
  strategy: generated
  generator: verification/generators/missing#generate
operation: {kind: semantic-function, name: transition-model}
oracle: [the transition remains valid]
evidence: {path: verification/properties/candidate-proof.md}
counterexamples: {path: verification/counterexamples/candidate-proof}
realizations:
  - profile: smoke
    strategy: generated-property
    command: properties
    generator: verification/generators/missing#generate
    runner: verification/properties/missing#run_property
"#,
        )
        .unwrap();
        module
            .as_mapping_mut()
            .expect("generated module mapping")
            .insert(
                yaml_key("properties"),
                YamlValue::Sequence(vec![unresolved_property]),
            );
        fs::write(&module_path, serde_yaml::to_string(&module).unwrap()).unwrap();

        let report =
            build_module_scoped_check_report(&root, &module_path, CheckMode::Changes).unwrap();

        fs::remove_dir_all(&root).unwrap();
        assert_eq!(report.result, CheckResult::Fail);
        assert!(report.reasons.iter().any(|reason| {
            reason.contains("property.runner-missing")
                && reason.contains("candidate-proof-property")
        }));
        assert!(report.reasons.iter().any(|reason| {
            reason.contains("property.generator-missing")
                && reason.contains("candidate-proof-property")
        }));
    }

    #[test]
    fn progressive_check_reuses_shared_verification_successes_and_failures() {
        let cache = CapturedVerificationCache::new(None);
        let success_calls = std::cell::Cell::new(0usize);
        let failure_calls = std::cell::Cell::new(0usize);
        let success = Path::new("shared/implementation.yaml");
        let failure = Path::new("shared/failing-implementation.yaml");

        for _ in 0..2 {
            assert_eq!(
                cache
                    .get_or_run(success, || {
                        success_calls.set(success_calls.get() + 1);
                        Ok("verified once".to_string())
                    })
                    .unwrap(),
                "verified once"
            );
            assert!(cache
                .get_or_run(failure, || {
                    failure_calls.set(failure_calls.get() + 1);
                    bail!("failed once")
                })
                .unwrap_err()
                .to_string()
                .contains("failed once"));
        }

        assert_eq!(success_calls.get(), 1);
        assert_eq!(failure_calls.get(), 1);
    }

    #[test]
    fn module_scoped_committed_proof_ignores_outside_dirt_but_runs_strict_audit() {
        if Command::new("git").arg("--version").output().is_err() {
            return;
        }

        let root = unique_test_dir("module-scoped-adoption-proof");
        run_init(
            &root,
            "progressive-system",
            "Certify one adopted module closure.",
            "0.1.0",
            &[],
        )
        .unwrap();
        let module_root = root.join("modules/owned-decisions");
        run_add_module(
            add_module_request(
                &module_root,
                "owned-decisions",
                "Own one progressively adopted decision boundary.",
                "library",
                &[],
                Some(ScaffoldShape::DomainEngine),
                None,
            ),
            &no_provider_options(),
        )
        .unwrap();
        for args in [
            vec!["config", "user.email", "rms@example.test"],
            vec!["config", "user.name", "RMS Test"],
            vec!["add", "-A"],
            vec!["commit", "-m", "baseline"],
        ] {
            let status = Command::new("git")
                .args(&args)
                .current_dir(&root)
                .status()
                .unwrap();
            assert!(status.success(), "git {} failed", args.join(" "));
        }

        fs::create_dir_all(root.join("Sources/Legacy")).unwrap();
        fs::write(
            root.join("Sources/Legacy/Unowned.swift"),
            "struct Unowned {}\n",
        )
        .unwrap();
        let outside = build_module_scoped_check_report(
            &root,
            &module_root.join("module.yaml"),
            CheckMode::Committed,
        )
        .unwrap();
        assert_eq!(outside.result, CheckResult::Fail, "{outside:#?}");
        assert!(outside.warnings.iter().any(|warning| warning.contains(
            "outside the certified module closure and did not invalidate this scoped proof"
        )));
        assert!(outside
            .reasons
            .iter()
            .any(|reason| reason.contains("semantic.revision-missing")));
        assert!(outside.details["audit"]["checks"]
            .as_array()
            .is_some_and(|checks| !checks.is_empty()));
        assert_eq!(
            outside.details["out_of_scope_changed_paths"],
            json!(["Sources/Legacy/Unowned.swift"])
        );

        fs::write(module_root.join("uncommitted-role.txt"), "candidate\n").unwrap();
        let inside = build_module_scoped_check_report(
            &root,
            &module_root.join("module.yaml"),
            CheckMode::Committed,
        )
        .unwrap();
        assert_eq!(inside.result, CheckResult::Fail, "{inside:#?}");
        assert!(inside.reasons.iter().any(
            |reason| reason.contains("scoped committed proof requires a clean module closure")
        ));

        fs::remove_dir_all(&root).unwrap();
    }

