    #[test]
    fn spec_apply_property_set_and_remove_revise_canonical_semantics() {
        let root = unique_test_dir("spec-apply-property-set-remove");
        fs::create_dir_all(&root).unwrap();
        fs::write(
            root.join("module.yaml"),
            r#"spec: rms/module/v0.1
module:
  name: property-revision
  version: 0.1.0
  kind: library
  purpose: Prove property revision semantics.
profiles: [core]
owns: { concepts: [], data: [], decisions: [] }
provides: { commands: [], queries: [], events: [], capabilities: [] }
requires: { modules: [], capabilities: [] }
invariants: []
effects: []
compatibility: { policy: backward-compatible-within-major }
verification: { laws: [], contracts: [], scenarios: [], boundaries: [] }
"#,
        )
        .unwrap();

        fs::write(
            root.join("implementation.yaml"),
            r#"spec: rms/implementation/v0.1
module: property-revision
binding: executable
source: { root: ., public_entrypoint: run.sh }
commands: { build: 'true', verify: 'true', properties: 'true' }
architecture:
  shape: domain-engine
  machine:
    name: PropertyRevisionMachine
    mode: stateless-decision-machine
    transition_signature: input-only
    types:
      state: PropertyRevisionState
      command: PropertyRevisionCommand
      event: PropertyRevisionEvent
      reply: PropertyRevisionReply
      rejection: PropertyRevisionRejection
      transition: PropertyRevisionTransition
      transition_record: PropertyRevisionTransitionRecord
    states: [Ready]
    commands: [Check]
    observed_events: []
    events: []
    effects: []
    effect_results: []
    replies: [Checked]
    rejections: [Rejected]
    effect_protocols: []
    transition_function: transition
    stateless_justification: This fixture has no lifecycle or effects.
    transitions:
      - from: Ready
        on: Check
        to: Ready
        case: Check
        reply: Checked
  roles: {}
"#,
        )
        .unwrap();
        fs::create_dir_all(root.join("src")).unwrap();
        fs::write(root.join("run.sh"), "#!/usr/bin/env sh\nexit 0\n").unwrap();
        fs::write(
            root.join("src/property.rs"),
            "fn generate_values() -> Vec<u8> { (0..8).collect() }\nfn check_generated_values() { for value in generate_values() { assert!(value < 8); } }\n",
        )
        .unwrap();

        run_spec_apply(
            &root.join("module.yaml"),
            None,
            Some(
                r#"spec: rms/semantic-change/v0.1
module: module.yaml
properties:
  add:
    - id: values-remain-valid
      proves: value-validity
      kind: property
      input_space: { values: fixed examples }
      oracle: [every value is valid]
      evidence:
        kind: property
        path: verification/properties/values_remain_valid.md
      realizations:
        - profile: smoke
          strategy: deterministic-corpus
          command: properties
          runner: run.sh#check_values
"#,
            ),
            None,
            false,
        )
        .unwrap();

        run_spec_apply(
            &root.join("module.yaml"),
            None,
            Some(
                r#"spec: rms/semantic-change/v0.1
module: module.yaml
properties:
  set:
    - id: values-remain-valid
      proves: value-validity
      kind: property
      input_space: { values: generated examples }
      oracle: [every generated value is valid]
      evidence:
        kind: property
        path: verification/properties/values_remain_valid.md
      realizations:
        - profile: ci
          strategy: generated-property
          command: properties
          generator: src/property.rs#generate_values
          runner: src/property.rs#check_generated_values
"#,
            ),
            None,
            false,
        )
        .unwrap();

        let revised = fs::read_to_string(root.join("module.yaml")).unwrap();
        let revised_implementation = fs::read_to_string(root.join("implementation.yaml")).unwrap();
        let revised_evidence =
            fs::read_to_string(root.join("verification/properties/values_remain_valid.md"))
                .unwrap();
        assert_eq!(revised.matches("id: values-remain-valid").count(), 1);
        assert!(revised.contains("strategy: generated-property"));
        assert!(revised.contains("generator: src/property.rs#generate_values"));
        assert!(revised.contains("runner: src/property.rs#check_generated_values"));
        assert_eq!(
            revised_implementation
                .matches("id: values-remain-valid")
                .count(),
            1
        );
        assert!(revised_implementation.contains("generator: src/property.rs#generate_values"));
        assert!(revised_implementation.contains("runner: src/property.rs#check_generated_values"));
        assert!(revised_evidence.contains("every generated value is valid"));
        assert!(!revised_evidence.contains("every value is valid"));

        let first_change = fs::read_dir(root.join("verification/changes"))
            .unwrap()
            .filter_map(|entry| entry.ok().map(|entry| entry.path()))
            .find(|path| {
                fs::read_to_string(path)
                    .is_ok_and(|contents| contents.contains("values: fixed examples"))
            })
            .unwrap();
        let original_property: SemanticPropertyChange = serde_yaml::from_str(
            r#"id: values-remain-valid
proves: value-validity
kind: property
input_space: { values: fixed examples }
oracle: [every value is valid]
evidence: { kind: property, path: verification/properties/values_remain_valid.md }
realizations:
  - profile: smoke
    strategy: deterministic-corpus
    command: properties
    runner: run.sh#check_values
"#,
        )
        .unwrap();
        let stale_obligation = render_semantic_property_evidence(&original_property);
        fs::write(
            root.join("verification/properties/values_remain_valid.md"),
            &stale_obligation,
        )
        .unwrap();
        let replay_change = format!(
            r#"spec: rms/semantic-change/v0.1
module: module.yaml
supersedes: [{}]
properties:
  set:
    - id: values-remain-valid
      proves: value-validity
      kind: property
      input_space: {{ values: generated examples }}
      oracle: [every generated value is valid]
      evidence:
        kind: property
        path: verification/properties/values_remain_valid.md
      realizations:
        - profile: ci
          strategy: generated-property
          command: properties
          generator: src/property.rs#generate_values
          runner: src/property.rs#check_generated_values
"#,
            display_relative(&root, &first_change)
        );
        run_spec_apply(
            &root.join("module.yaml"),
            None,
            Some(&replay_change),
            None,
            true,
        )
        .unwrap();
        fs::write(
            root.join("verification/properties/values_remain_valid.md"),
            &revised_evidence,
        )
        .unwrap();

        run_spec_apply(
            &root.join("module.yaml"),
            None,
            Some(
                r#"spec: rms/semantic-change/v0.1
module: module.yaml
properties:
  set:
    - id: values-remain-valid
      proves: value-validity
      kind: fuzz
      input_space: { values: generated examples }
      oracle: [every generated value is valid]
      evidence:
        kind: fuzz
        path: verification/properties/values_remain_valid.md
      realizations:
        - profile: ci
          strategy: generated-property
          command: properties
          generator: src/property.rs#generate_values
          runner: src/property.rs#check_generated_values
"#,
            ),
            None,
            false,
        )
        .unwrap();

        let fuzz_module = load_manifest(&root.join("module.yaml")).unwrap();
        let fuzz_implementation = load_manifest(&root.join("implementation.yaml")).unwrap();
        assert!(get_path(&fuzz_module.value, &["properties"])
            .and_then(YamlValue::as_sequence)
            .is_none_or(Vec::is_empty));
        assert_eq!(
            get_path(&fuzz_module.value, &["fuzz_targets"])
                .and_then(YamlValue::as_sequence)
                .and_then(|items| items.first())
                .and_then(|item| get_str(item, &["id"])),
            Some("values-remain-valid")
        );
        assert!(get_path(
            &fuzz_implementation.value,
            &["architecture", "reliability", "properties"]
        )
        .and_then(YamlValue::as_sequence)
        .is_none_or(Vec::is_empty));
        assert_eq!(
            get_path(
                &fuzz_implementation.value,
                &["architecture", "reliability", "fuzz_targets"]
            )
            .and_then(YamlValue::as_sequence)
            .and_then(|items| items.first())
            .and_then(|item| get_str(item, &["id"])),
            Some("values-remain-valid")
        );
        let fuzz_evidence =
            fs::read_to_string(root.join("verification/properties/values_remain_valid.md"))
                .unwrap();
        assert!(fuzz_evidence.starts_with("# Fuzz Evidence Obligation"));

        let concrete_evidence = "# Observed property proof\n\nCommand/tool: exact runner\n\nObserved result: pass\n\nSource revision: fixture\n";
        fs::write(
            root.join("verification/properties/values_remain_valid.md"),
            concrete_evidence,
        )
        .unwrap();
        let module_before_unsafe_set = fs::read_to_string(root.join("module.yaml")).unwrap();
        let unsafe_set = r#"spec: rms/semantic-change/v0.1
module: module.yaml
properties:
  set:
    - id: values-remain-valid
      proves: value-validity
      kind: fuzz
      input_space: { values: generated examples }
      oracle: [every generated value remains valid after revision]
      evidence:
        kind: fuzz
        path: verification/properties/values_remain_valid.md
      realizations:
        - profile: ci
          strategy: generated-property
          command: properties
          generator: src/property.rs#generate_values
          runner: src/property.rs#check_generated_values
"#;
        let unsafe_error = run_spec_apply(
            &root.join("module.yaml"),
            None,
            Some(unsafe_set),
            None,
            true,
        )
        .unwrap_err()
        .to_string();
        assert!(unsafe_error.contains("RMS semantic change rejected"));
        assert_eq!(
            fs::read_to_string(root.join("module.yaml")).unwrap(),
            module_before_unsafe_set
        );
        assert_eq!(
            fs::read_to_string(root.join("verification/properties/values_remain_valid.md"))
                .unwrap(),
            concrete_evidence
        );

        run_spec_apply(
            &root.join("module.yaml"),
            None,
            Some(
                r#"spec: rms/semantic-change/v0.1
module: module.yaml
properties:
  remove: [values-remain-valid]
"#,
            ),
            None,
            false,
        )
        .unwrap();

        let removed = fs::read_to_string(root.join("module.yaml")).unwrap();
        let removed_implementation = fs::read_to_string(root.join("implementation.yaml")).unwrap();
        fs::remove_dir_all(&root).unwrap();
        assert!(!removed.contains("id: values-remain-valid"));
        assert!(!removed.contains("verification/properties/values_remain_valid.md"));
        assert!(!removed_implementation.contains("id: values-remain-valid"));
    }

    #[test]
    fn property_realizations_require_generators_runners_operations_and_oracles() {
        let root = unique_test_dir("property-realization-runner");
        fs::create_dir_all(root.join("src")).unwrap();
        fs::create_dir_all(root.join("verification/properties")).unwrap();
        fs::write(
            root.join("src/property.rs"),
            "pub fn generate_values() -> Vec<u8> { (0..32).collect() }\npub fn fixed_values() -> Vec<u8> { vec![0, 1, 2] }\npub fn normalize_value(value: u8) -> u8 { value }\npub fn check_values() { for value in generate_values() { let normalized = normalize_value(value); assert!(normalized < 32); } }\npub fn check_fixed_values() { for value in fixed_values() { let normalized = normalize_value(value); assert!(normalized < 3); } }\n",
        )
        .unwrap();
        fs::write(
            root.join("verification/properties/property.md"),
            "# Observed property proof\n\nCommand/tool: `cargo test property`\n\nObserved result: 3 generated cases passed.\n\nSource revision: git:test\n",
        )
        .unwrap();
        let value: YamlValue = serde_yaml::from_str(
            r#"spec: rms/implementation/v0.1
module: property-runner
binding: rust
source: { root: ., public_entrypoint: src/property.rs }
commands:
  build: cargo check
  verify: cargo test
  properties: cargo test "${RMS_PROPERTY_RUNNER##*#}"
architecture:
  shape: domain-engine
  reliability:
    properties:
      - id: valid-runner
        proves: value-validity
        input_space: generated values
        oracle: [values remain valid]
        evidence: verification/properties/property.md
        realizations:
          - profile: smoke
            strategy: generated-property
            command: properties
            generator: src/property.rs#generate_values
            runner: src/property.rs#check_values
      - id: missing-generator
        proves: value-validity
        input_space: generated values
        oracle: [values remain valid]
        evidence: verification/properties/property.md
        realizations:
          - profile: smoke
            strategy: generated-property
            command: properties
            runner: src/property.rs#check_values
      - id: missing-runner
        proves: value-validity
        input_space: generated values
        oracle: [values remain valid]
        evidence: verification/properties/property.md
        realizations:
          - profile: smoke
            strategy: generated-property
            command: properties
            generator: src/property.rs#generate_values
            runner: ''
      - id: missing-runner-symbol
        proves: value-validity
        input_space: generated values
        oracle: [values remain valid]
        evidence: verification/properties/property.md
        realizations:
          - profile: smoke
            strategy: generated-property
            command: properties
            generator: src/property.rs#generate_values
            runner: src/property.rs#not_present
      - id: fixed-generator
        proves: value-validity
        input_space: generated values
        oracle: [values remain valid]
        evidence: verification/properties/property.md
        realizations:
          - profile: smoke
            strategy: generated-property
            command: properties
            generator: src/property.rs#fixed_values
            runner: src/property.rs#check_fixed_values
  machine: {}
  roles:
    representation: [src/lib.rs]
    transition: [src/lib.rs]
"#,
        )
        .unwrap();
        let manifest = LoadedManifest {
            path: root.join("implementation.yaml"),
            value,
        };
        let mut diagnostics = Vec::new();
        validate_property_implementation(&manifest, &mut diagnostics);

        fs::remove_dir_all(&root).unwrap();
        assert!(diagnostics
            .iter()
            .any(|diagnostic| diagnostic.check == "property.generator-missing"));
        assert!(diagnostics
            .iter()
            .any(|diagnostic| diagnostic.check == "property.runner-missing"));
        assert!(diagnostics.iter().any(|diagnostic| {
            diagnostic.check == "evidence.property-realization-fixed-corpus"
                && diagnostic.message.contains("fixed-generator")
        }));
        assert!(
            !diagnostics.iter().any(|diagnostic| {
                diagnostic.message.contains("valid-runner")
                    && matches!(
                        diagnostic.check.as_str(),
                        "property.generator-missing"
                            | "property.runner-missing"
                            | "property.runner-does-not-call-generator"
                            | "property.runner-does-not-call-operation"
                            | "property.runner-has-no-oracle"
                    )
            }),
            "{diagnostics:#?}"
        );
    }

