    #[test]
    fn rust_batch_proof_requires_an_exact_passed_test_from_an_unfiltered_suite() {
        let batch = RustBatchProofEvidence {
            verify_command: "cargo test --manifest-path Cargo.toml".to_string(),
            output: concat!(
                "test tests::exact_runner_extra ... ok\n",
                "test tests::exact_runner ... ok\n",
                "test behavioral_contract::tests::closed_contract ... ok\n",
                "test tests::ignored_runner ... ignored\n",
                "test tests::failed_runner ... FAILED\n",
            )
            .to_string(),
        };
        let property_command =
            "cargo test --manifest-path Cargo.toml \"${RMS_PROPERTY_RUNNER##*#}\"";

        assert!(is_unfiltered_cargo_test(&batch.verify_command));
        assert!(!is_unfiltered_cargo_test(
            "cargo test --manifest-path Cargo.toml exact_runner"
        ));
        assert!(batch
            .exact_pass_line(property_command, "src/main.rs#exact_runner")
            .is_some());
        assert!(batch
            .exact_pass_line(
                property_command,
                "src/behavioral_contract.rs#closed_contract"
            )
            .is_some());
        assert!(batch
            .exact_pass_line(property_command, "src/main.rs#exact_runner_extra_suffix")
            .is_none());
        assert!(batch
            .exact_pass_line(property_command, "src/main.rs#ignored_runner")
            .is_none());
        assert!(batch
            .exact_pass_line(property_command, "src/main.rs#failed_runner")
            .is_none());
        assert!(batch
            .exact_pass_line("sh scripts/property.sh", "src/main.rs#exact_runner")
            .is_none());
    }

    #[test]
    fn property_run_executes_each_shared_command_realization() {
        let root = unique_test_dir("property-shared-command");
        fs::create_dir_all(root.join("scripts")).unwrap();
        fs::create_dir_all(root.join(".rms/cache")).unwrap();
        fs::create_dir_all(root.join("verification/properties")).unwrap();
        fs::write(
            root.join("scripts/properties.sh"),
            "#!/bin/sh\nset -eu\nprintf '%s|%s\\n' \"$RMS_PROPERTY_ID\" \"$RMS_PROPERTY_RUNNER\" >> .rms/cache/property-runs.log\n",
        )
        .unwrap();
        fs::write(
            root.join("verification/properties/shared.md"),
            "# Shared property proof\n\nCommand/tool: `rms property run implementation.yaml --profile smoke`\n\nObserved result: both exact runners executed.\n\nSource revision: git:test\n",
        )
        .unwrap();
        fs::write(
            root.join("implementation.yaml"),
            r#"spec: rms/implementation/v0.1
module: shared-property-command
binding: executable
source: { root: ., public_entrypoint: scripts/properties.sh }
commands:
  build: sh -n scripts/properties.sh
  verify: sh -n scripts/properties.sh
  properties: sh scripts/properties.sh "${RMS_PROPERTY_RUNNER}"
toolchain: { runner: shell }
architecture:
  shape: domain-engine
  reliability:
    properties:
      - id: first-property
        proves: first-law
        input_space: finite first cases
        oracle: [first runner exits successfully]
        evidence: verification/properties/shared.md
        realizations:
          - { profile: smoke, strategy: deterministic-corpus, command: properties, runner: scripts/properties.sh#first_runner }
      - id: second-property
        proves: second-law
        input_space: finite second cases
        oracle: [second runner exits successfully]
        evidence: verification/properties/shared.md
        realizations:
          - { profile: smoke, strategy: deterministic-corpus, command: properties, runner: scripts/properties.sh#second_runner }
  machine: {}
  roles: {}
"#,
        )
        .unwrap();

        let report = execute_property_realizations(
            &root.join("implementation.yaml"),
            PropertyProfile::Smoke,
            false,
            30,
        )
        .unwrap();
        let first_log = fs::read_to_string(root.join(".rms/cache/property-runs.log")).unwrap();
        let resumed = execute_property_realizations(
            &root.join("implementation.yaml"),
            PropertyProfile::Smoke,
            false,
            30,
        )
        .unwrap();
        let resumed_log = fs::read_to_string(root.join(".rms/cache/property-runs.log")).unwrap();
        fs::write(
            root.join("scripts/semantic-input.txt"),
            "source digest changed\n",
        )
        .unwrap();
        let changed = execute_property_realizations(
            &root.join("implementation.yaml"),
            PropertyProfile::Smoke,
            false,
            30,
        )
        .unwrap();
        let changed_log = fs::read_to_string(root.join(".rms/cache/property-runs.log")).unwrap();

        fs::remove_dir_all(&root).unwrap();
        assert_eq!(report.commands.len(), 2);
        assert_eq!(resumed.commands.len(), 2);
        assert_eq!(changed.commands.len(), 2);
        assert!(report
            .commands
            .iter()
            .all(|command| command.status == "pass"));
        assert!(first_log.contains("first-property|scripts/properties.sh#first_runner"));
        assert!(first_log.contains("second-property|scripts/properties.sh#second_runner"));
        assert_eq!(resumed_log.lines().count(), 2);
        assert_eq!(changed_log.lines().count(), 4);
    }

    #[test]
    fn selected_test_count_rejects_zero_and_parses_supported_runners() {
        assert!(proof_command_is_test_backed(
            "swift test --package-path . --filter exact"
        ));
        assert!(proof_command_is_test_backed(
            "xcodebuild test -only-testing:AppTests/Exact"
        ));
        assert!(!proof_command_is_test_backed("sh scripts/property.sh"));
        assert_eq!(
            selected_test_count(
                "Test Suite 'Selected tests' passed\n\t Executed 0 tests, with 0 failures\n",
                "warning: No matching test cases were run\n",
            ),
            Some(0)
        );
        assert_eq!(
            selected_test_count("test result: ok. 3 passed; 0 failed\n", "",),
            Some(3)
        );
        assert_eq!(selected_test_count("", "Ran 2 tests in 0.1s\n"), Some(2));
        assert_eq!(selected_test_count("4 passed in 0.2s\n", ""), Some(4));
        assert_eq!(
            selected_test_count(
                "Test Suite 'Selected tests' passed\nExecuted 0 tests, with 0 failures\n✔ Test acceptedOutgoingBeepBackendJoinPromotesPendingOriginBeforeProjection() passed after 0.001 seconds.\n✔ Test run with 1 test in 1 suite passed after 0.001 seconds.\n",
                "",
            ),
            Some(1)
        );
    }

