    #[test]
    fn strict_audit_fresh_scaffold_has_no_placeholder_evidence() {
        let root = unique_test_dir("strict-audit-scaffold");
        run_add_module(
            add_module_request(
                &root,
                "audit-example",
                "Exercise strict production audit.",
                "library",
                &["core".to_string()],
                Some(ScaffoldShape::DomainEngine),
                Some("rust"),
            ),
            &no_provider_options(),
        )
        .unwrap();
        record_generated_traces(&root);

        let strict = build_audit_report(&root, true).unwrap();
        let relaxed = build_audit_report(&root, false).unwrap();

        fs::remove_dir_all(&root).unwrap();
        assert_eq!(strict.result, "fail");
        assert!(strict
            .checks
            .iter()
            .all(|check| check.id != "evidence.placeholder"));
        assert!(strict
            .checks
            .iter()
            .any(|check| { check.id == "provenance.source-revision" && check.result == "fail" }));
        assert_ne!(relaxed.result, "fail");
    }

