    #[test]
    fn semantic_revision_detects_direct_canonical_manifest_drift() {
        let root = unique_test_dir("semantic-revision-drift");
        fs::create_dir_all(root.join("verification/changes")).unwrap();
        let record = root.join("verification/changes/initial.yaml");
        fs::write(&record, "spec: rms/semantic-change/v0.1\n").unwrap();
        fs::write(
            root.join("module.yaml"),
            r#"spec: rms/module/v0.1
module:
  name: revision-example
  version: 0.1.0
  kind: library
  purpose: Verify canonical semantic revisions.
profiles: [core]
owns:
  concepts: []
  data: []
  decisions: []
provides:
  commands: []
  queries: []
  events: []
  capabilities: []
requires:
  modules: []
  capabilities: []
invariants: []
effects: []
compatibility:
  policy: backward-compatible-within-major
verification:
  laws: []
  contracts: []
  scenarios: []
  boundaries: []
"#,
        )
        .unwrap();
        fs::write(
            root.join("implementation.yaml"),
            r#"spec: rms/implementation/v0.1
module: revision-example
binding: executable
source:
  root: .
  public_entrypoint: implementation.yaml
commands:
  build: "true"
  verify: "true"
architecture:
  shape: domain-engine
  machine:
    name: RevisionExampleMachine
    mode: stateless-decision-machine
    transition_signature: input-only
    types:
      state: RevisionExampleState
      command: RevisionExampleCommand
      event: RevisionExampleEvent
      reply: RevisionExampleReply
      rejection: RevisionExampleRejection
      transition: RevisionExampleTransition
      transition_record: RevisionExampleTransitionRecord
    states: [Ready]
    commands: [Check]
    observed_events: []
    events: [Checked]
    effects: []
    effect_results: []
    replies: [Accepted]
    rejections: [Rejected]
    effect_protocols: []
    transition_function: transition
    transitions:
      - from: Ready
        on: Check
        to: Ready
        case: Check
        events: [Checked]
        reply: Accepted
    stateless_justification: checking a revision has no lifecycle
  roles:
    representation: [implementation.yaml]
    transition: [implementation.yaml]
"#,
        )
        .unwrap();
        let mut implementation = load_manifest(&root.join("implementation.yaml")).unwrap();
        seal_implementation_semantics(
            &mut implementation,
            &record,
            SemanticRevisionAuthority::SpecApply,
        )
        .unwrap();

        let implementation = load_manifest(&root.join("implementation.yaml")).unwrap();
        let mut checks = Vec::new();
        append_semantic_revision_audit_check(&implementation, true, &mut checks);
        assert!(
            checks
                .iter()
                .any(|check| check.id == "semantic.revision-integrity" && check.result == "pass"),
            "{checks:#?}"
        );

        let mut implementation = load_manifest(&root.join("implementation.yaml")).unwrap();
        set_yaml_string_path(
            &mut implementation.value,
            &["x-rms", "semantic_revision", "applied_by"],
            SemanticRevisionAuthority::RepositoryMaintainerSeal.label(),
        );
        write_yaml_manifest(&implementation).unwrap();
        let implementation = load_manifest(&root.join("implementation.yaml")).unwrap();
        let mut checks = Vec::new();
        append_semantic_revision_audit_check(&implementation, true, &mut checks);
        assert!(checks.iter().any(|check| {
            check.id == "semantic.revision-authority-invalid" && check.result == "fail"
        }));

        fs::create_dir_all(root.join("verification/laws")).unwrap();
        fs::write(
            root.join("verification/laws/self_application.md"),
            "Repository maintainers independently seal this RMS self-development module.\n",
        )
        .unwrap();
        let mut module = load_manifest(&root.join("module.yaml")).unwrap();
        set_yaml_string_path(&mut module.value, &["module", "name"], "rms-cli");
        set_yaml_string_path(
            &mut module.value,
            &["x-rms", "self_application", "scope"],
            "rms-self-development",
        );
        set_yaml_string_path(
            &mut module.value,
            &["x-rms", "self_application", "semantic_revision_authority"],
            SemanticRevisionAuthority::RepositoryMaintainerSeal.label(),
        );
        set_yaml_string_path(
            &mut module.value,
            &["x-rms", "self_application", "evidence"],
            "verification/laws/self_application.md",
        );
        let commands = ensure_yaml_sequence_path(&mut module.value, &["provides", "commands"]);
        for name in [
            "apply-semantic-change",
            "audit-rms-project",
            "prepare-rms-release",
        ] {
            commands.push(yaml_mapping_value([
                ("name", YamlValue::String(name.to_string())),
                (
                    "contract",
                    YamlValue::String(format!("contracts/{name}.v1.yaml")),
                ),
            ]));
        }
        write_yaml_manifest(&module).unwrap();
        let mut implementation = load_manifest(&root.join("implementation.yaml")).unwrap();
        seal_implementation_semantics(
            &mut implementation,
            &record,
            SemanticRevisionAuthority::RepositoryMaintainerSeal,
        )
        .unwrap();
        let implementation = load_manifest(&root.join("implementation.yaml")).unwrap();
        let mut checks = Vec::new();
        append_semantic_revision_audit_check(&implementation, true, &mut checks);
        assert!(
            checks
                .iter()
                .any(|check| check.id == "semantic.revision-integrity" && check.result == "pass"),
            "{checks:#?}"
        );

        let original_record = fs::read_to_string(&record).unwrap();
        fs::write(
            &record,
            format!("{original_record}# direct record surgery\n"),
        )
        .unwrap();
        let implementation = load_manifest(&root.join("implementation.yaml")).unwrap();
        let mut checks = Vec::new();
        append_semantic_revision_audit_check(&implementation, true, &mut checks);
        assert!(checks.iter().any(|check| {
            check.id == "semantic.revision-record-drift" && check.result == "fail"
        }));
        fs::write(&record, original_record).unwrap();

        let mut module = load_manifest(&root.join("module.yaml")).unwrap();
        append_unique_yaml_string_path(
            &mut module.value,
            &["owns", "decisions"],
            "direct-manifest-surgery",
        );
        write_yaml_manifest(&module).unwrap();
        let implementation = load_manifest(&root.join("implementation.yaml")).unwrap();
        let mut checks = Vec::new();
        append_semantic_revision_audit_check(&implementation, true, &mut checks);

        fs::remove_dir_all(&root).unwrap();
        assert!(checks
            .iter()
            .any(|check| check.id == "semantic.revision-drift" && check.result == "fail"));
    }

    #[test]
    fn spec_apply_auto_chains_and_seals_module_only_semantic_revisions() {
        let root = unique_test_dir("semantic-revision-auto-chain");
        fs::create_dir_all(&root).unwrap();
        fs::write(
            root.join("module.yaml"),
            r#"spec: rms/module/v0.1
module:
  name: revision-chain
  version: 0.1.0
  kind: composite
  purpose: Verify append-only semantic revision history.
profiles: [core]
owns:
  concepts: []
  data: []
  decisions: []
provides:
  commands: []
  queries: []
  events: []
  capabilities: []
requires:
  modules: []
  capabilities: []
invariants: []
effects: []
compatibility:
  policy: backward-compatible-within-major
verification:
  laws: []
  contracts: []
  scenarios: []
  boundaries: []
"#,
        )
        .unwrap();

        for (id, evidence) in [
            ("first-revision", "verification/laws/first.md"),
            ("second-revision", "verification/laws/second.md"),
        ] {
            let change = format!(
                r#"spec: rms/semantic-change/v0.1
intent:
  summary: Add {id}.
laws:
  add:
    - id: {id}
      statement: {id} remains explicit.
      kind: invariant
      authority: parser
      enforced_by: semantic-revision-test
evidence:
  add:
    - kind: law
      proves: {id}
      path: {evidence}
"#
            );
            run_spec_apply(&root.join("module.yaml"), None, Some(&change), None, false).unwrap();
        }

        let module = load_manifest(&root.join("module.yaml")).unwrap();
        let latest = get_str(
            &module.value,
            &["x-rms", "semantic_revision", "change_record"],
        )
        .unwrap()
        .to_string();
        let latest_path = root.join(&latest);
        let latest_change: SemanticChange =
            serde_yaml::from_str(&fs::read_to_string(&latest_path).unwrap()).unwrap();
        assert_eq!(latest_change.supersedes.len(), 1, "{latest_change:#?}");
        assert!(root.join(&latest_change.supersedes[0]).is_file());
        assert!(get_str(
            &module.value,
            &["x-rms", "semantic_revision", "change_record_digest"]
        )
        .is_some());

        let mut checks = Vec::new();
        append_module_semantic_revision_audit_check(&module, true, &mut checks);
        assert!(checks
            .iter()
            .any(|check| check.id == "semantic.revision-integrity" && check.result == "pass"));

        fs::remove_dir_all(&root).unwrap();
    }

