    #[test]
    fn git_changed_paths_include_nested_untracked_module_files() {
        let root = unique_test_dir("nested-untracked-paths");
        fs::create_dir_all(&root).unwrap();
        let status = Command::new("git")
            .current_dir(&root)
            .args(["init", "--quiet"])
            .status()
            .unwrap();
        assert!(status.success());
        fs::create_dir_all(root.join("modules/new/src")).unwrap();
        fs::write(
            root.join("modules/new/module.yaml"),
            "spec: rms/module/v0.1\n",
        )
        .unwrap();
        fs::write(root.join("modules/new/src/lib.rs"), "pub fn run() {}\n").unwrap();

        let paths = read_git_changed_paths(&root, None).unwrap();

        fs::remove_dir_all(&root).unwrap();
        assert!(paths
            .iter()
            .any(|path| { path.status == "??" && path.path == "modules/new/module.yaml" }));
        assert!(paths
            .iter()
            .any(|path| { path.status == "??" && path.path == "modules/new/src/lib.rs" }));
    }

    #[test]
    fn release_input_digest_uses_tracked_and_visible_untracked_files() {
        if Command::new("git").arg("--version").output().is_err() {
            return;
        }
        let root = unique_test_dir("release-input-git-files");
        fs::create_dir_all(&root).unwrap();
        run_git(&root, &["init", "--quiet"]).unwrap();
        fs::write(root.join(".gitignore"), "ignored/\n").unwrap();
        fs::write(root.join("tracked.txt"), "tracked\n").unwrap();
        run_git(&root, &["add", ".gitignore", "tracked.txt"]).unwrap();
        fs::create_dir_all(root.join("ignored")).unwrap();
        fs::write(root.join("ignored/cache.bin"), "first ignored value\n").unwrap();

        let baseline = release_input_digest(&root, false).unwrap();
        fs::write(root.join("ignored/cache.bin"), "second ignored value\n").unwrap();
        assert_eq!(release_input_digest(&root, false).unwrap(), baseline);

        fs::write(root.join("visible-untracked.txt"), "visible input\n").unwrap();
        assert_ne!(release_input_digest(&root, false).unwrap(), baseline);

        fs::remove_dir_all(&root).unwrap();
    }

    #[test]
    fn audit_scope_excludes_examples_from_repo_root_by_default() {
        assert!(!audit_path_str_in_scope(
            Path::new("."),
            "examples/rust/implementation.yaml",
            false
        ));
        assert!(audit_path_str_in_scope(
            Path::new("."),
            "examples/rust/implementation.yaml",
            true
        ));
        assert!(audit_path_str_in_scope(
            Path::new("examples/rust"),
            "implementation.yaml",
            false
        ));
        assert!(audit_path_str_in_scope(
            Path::new("."),
            "tooling/rust/rms/implementation.yaml",
            false
        ));
        assert!(!audit_path_str_in_scope(
            Path::new("/workspace/rms"),
            "/workspace/rms/examples/rust/implementation.yaml",
            false
        ));
        assert!(audit_path_str_in_scope(
            Path::new("/workspace/rms"),
            "/workspace/rms/tooling/rust/rms/implementation.yaml",
            false
        ));
    }

