    #[test]
    fn implementation_verify_smoke_phase_fails_when_declared_runner_symbol_is_missing() {
        let root = unique_test_dir("verify-implementation-property-symbol");
        fs::create_dir_all(root.join("src")).unwrap();
        fs::write(
            root.join("src/lib.rs"),
            "pub fn decide() -> bool { true }\n",
        )
        .unwrap();
        fs::write(
            root.join("property-evidence.md"),
            "# Property evidence\n\nPromise: the decision is true.\n\nCommand/tool: rms verify.\n\nObserved result: fixture execution is expected to fail before this proof runs.\n\nSource revision: test fixture.\n",
        )
        .unwrap();
        fs::write(
            root.join("implementation.yaml"),
            r#"spec: rms/implementation/v0.1
module: verify-property
binding: rust
source: {root: ., public_entrypoint: src/lib.rs}
commands: {build: "true", verify: "true", properties: "true"}
architecture:
  shape: domain-engine
  machine:
    name: VerifyPropertyMachine
    mode: stateless-decision-machine
    transition_signature: input-only
    stateless_justification: This proof fixture has no lifecycle or effects.
    types:
      state: VerifyPropertyState
      command: VerifyPropertyCommand
      event: VerifyPropertyEvent
      reply: VerifyPropertyReply
      rejection: VerifyPropertyRejection
      transition: VerifyPropertyTransition
      transition_record: VerifyPropertyTransitionRecord
    states: [Ready]
    commands: [Check]
    observed_events: []
    events: []
    effects: []
    effect_results: []
    replies: [Checked]
    rejections: [Rejected]
    effect_protocols: []
    transition_function: decide
    transitions:
      - from: Ready
        on: Check
        to: Ready
        case: check_decision
        reply: Checked
  reliability:
    properties:
      - id: decision-property
        proves: decision-law
        kind: semantic
        input_space: {values: [true]}
        operation: decide
        oracle: [the decision is true]
        evidence: {path: property-evidence.md}
        realizations:
          - profile: smoke
            strategy: deterministic-corpus
            command: properties
            runner: src/lib.rs#missing_property
  roles:
    representation: [src/lib.rs]
    transition: [src/lib.rs]
"#,
        )
        .unwrap();

        let implementation_path = root.join("implementation.yaml");
        let manifest = load_manifest(&implementation_path).unwrap();
        let failure = verify_implementation_smoke_properties(
            &implementation_path,
            &manifest,
            false,
            DEFAULT_PROOF_TIMEOUT_SECONDS,
            None,
        )
        .unwrap_err()
        .to_string();

        fs::remove_dir_all(&root).unwrap();
        assert!(failure.contains("property.runner-missing"), "{failure}");
    }

    #[test]
    fn add_capability_scaffolds_recursive_tree_that_verifies() {
        let root = unique_test_dir("add-capability-tree");
        run_init(
            &root,
            "capability-fixture",
            "Exercise recursive capability scaffolding.",
            "0.1.0",
            &["fixture".to_string()],
        )
        .unwrap();

        run_add_capability_tree(AddCapabilityTreeRequest {
            path: root.join("modules/play-game"),
            name: "play-game".to_string(),
            purpose: "Expose playable game capability.".to_string(),
            public_command: Some("play-game".to_string()),
            domain_child: Some("play-game-rules".to_string()),
            domain_shape: None,
            boundary_child: Some("play-game-cli".to_string()),
            domain_command: Some("resolve-move".to_string()),
            domain_binding: Some("rust".to_string()),
            boundary_binding: Some("js".to_string()),
            surface: None,
        })
        .unwrap();
        record_generated_traces(&root.join("modules/play-game-rules"));
        record_generated_traces(&root.join("modules/play-game-cli"));

        let parent = fs::read_to_string(root.join("modules/play-game/module.yaml")).unwrap();
        let domain = fs::read_to_string(root.join("modules/play-game-rules/module.yaml")).unwrap();
        let parent_scenario_evidence = fs::read_to_string(
            root.join("modules/play-game/verification/scenarios/composed_capability.md"),
        )
        .unwrap();
        let boundary = fs::read_to_string(root.join("modules/play-game-cli/module.yaml")).unwrap();
        let domain_implementation =
            fs::read_to_string(root.join("modules/play-game-rules/implementation.yaml")).unwrap();
        let boundary_implementation =
            fs::read_to_string(root.join("modules/play-game-cli/implementation.yaml")).unwrap();
        let provider_capability = load_manifest(
            &root.join("modules/play-game-rules/contracts/resolve-move-capability.v1.yaml"),
        )
        .unwrap();
        let consumer_capability = load_manifest(
            &root.join("modules/play-game-cli/contracts/resolve-move-capability.v1.yaml"),
        )
        .unwrap();
        let has_parent_export_evidence = root
            .join("modules/play-game/verification/contracts/parent_export.md")
            .exists();
        let has_transition_trace_evidence = root
            .join("modules/play-game-rules/verification/laws/transition_trace.md")
            .exists();
        let has_accepted_rejected_evidence = root
            .join("modules/play-game-rules/verification/scenarios/accepted_rejected.md")
            .exists();
        let has_reusable_package_evidence = root
            .join("modules/play-game-rules/verification/scenarios/reusable_package.md")
            .exists();
        let has_malformed_input_evidence = root
            .join("modules/play-game-cli/verification/boundaries/malformed_input.md")
            .exists();
        let has_parser_contract_evidence = root
            .join("modules/play-game-cli/verification/contracts/parser_to_domain_command.md")
            .exists();
        let report = compose_system(&root).unwrap();
        let graph_diagnostics = semantic_graph::semantic_system_graph_diagnostics(&root).unwrap();
        let mut diagnostics = Vec::new();
        let mut semantic_diagnostics = Vec::new();
        for file in [
            "modules/play-game/module.yaml",
            "modules/play-game-rules/module.yaml",
            "modules/play-game-cli/module.yaml",
        ] {
            let manifest = load_manifest(&root.join(file)).unwrap();
            validate_loaded_manifest(&manifest, &mut diagnostics);
            validate_semantic_module_completeness(&manifest, &mut semantic_diagnostics);
        }
        run_verify(&root.join("modules/play-game/module.yaml"), false).unwrap();

        fs::remove_dir_all(&root).unwrap();
        assert!(parent.contains("kind: \"composite\""));
        assert!(parent.contains("composition:"));
        assert!(parent.contains("name: \"play-game-rules\""));
        assert!(parent.contains("name: \"play-game-cli\""));
        assert!(domain.contains("capabilities:"));
        assert!(domain.contains("name: \"resolve-move\""));
        assert!(domain.contains("name: \"resolve-move-capability\""));
        assert!(domain.contains("contract: contracts/resolve-move-capability.v1.yaml"));
        assert!(boundary.contains("contract: contracts/resolve-move-capability.v1.yaml"));
        assert_eq!(
            get_str(&provider_capability.value, &["kind"]),
            Some("capability")
        );
        assert_eq!(
            get_str(&consumer_capability.value, &["kind"]),
            Some("capability")
        );
        assert!(domain.contains("x-rms:"));
        assert!(domain.contains("reusable: true"));
        assert!(domain.contains("verification/scenarios/reusable_package.md"));
        assert!(parent_scenario_evidence.contains("public-command-is-child-backed"));
        assert!(boundary.contains("name: \"resolve-move-capability\""));
        assert!(
            domain_implementation.contains("name: \"PlayGameMachine\"")
                || domain_implementation.contains("name: PlayGameMachine")
        );
        assert!(!domain_implementation.contains("PlayGameRulesMachine"));
        assert!(
            boundary_implementation.contains("name: \"PlayGameBoundaryMachine\"")
                || boundary_implementation.contains("name: PlayGameBoundaryMachine")
        );
        assert!(domain_implementation.contains("public_behavior_bindings:"));
        assert!(domain_implementation.contains("id: resolve-move-public"));
        assert!(domain_implementation.contains("id: resolve-move-capability-public"));
        assert!(domain_implementation.contains("semantic_function: transition-model"));
        assert!(boundary_implementation.contains("public_behavior_bindings:"));
        assert!(boundary_implementation.contains("id: play-game-public"));
        assert!(boundary_implementation.contains("dependency_behavior_bindings:"));
        assert!(boundary_implementation.contains("id: resolve-move-provider"));
        assert!(boundary_implementation.contains("consumer: src/adapter.mjs#handleBoundaryInput"));
        assert!(boundary_implementation.contains("provider_module: play-game-rules"));
        assert!(boundary_implementation
            .contains("provider_contract: contracts/resolve-move-capability.v1.yaml"));
        assert!(has_parent_export_evidence);
        assert!(has_transition_trace_evidence);
        assert!(has_accepted_rejected_evidence);
        assert!(has_reusable_package_evidence);
        assert!(has_malformed_input_evidence);
        assert!(has_parser_contract_evidence);
        assert_eq!(report.result, ComposeResult::Pass, "{:#?}", report.findings);
        assert_no_error_diagnostics(&diagnostics);
        assert!(
            diagnostics
                .iter()
                .all(|diagnostic| diagnostic.check != "evidence.placeholder"),
            "{diagnostics:#?}"
        );
        assert!(
            semantic_diagnostics
                .iter()
                .all(|diagnostic| diagnostic.check != "semantic.law-without-evidence"),
            "{semantic_diagnostics:#?}"
        );
        assert!(
            graph_diagnostics.iter().all(|diagnostic| {
                !matches!(
                    diagnostic.check.as_str(),
                    "semantic.public-binding-missing"
                        | "semantic.public-binding-invalid"
                        | "semantic.public-input-unreachable"
                        | "semantic.required-capability-binding-missing"
                )
            }),
            "{graph_diagnostics:#?}"
        );
    }

    #[test]
    fn invariant_accepts_concrete_evidence_from_its_enforcing_semantic_function() {
        let root = unique_test_dir("semantic-function-invariant-evidence");
        fs::create_dir_all(root.join("verification/laws")).unwrap();
        fs::write(
            root.join("verification/laws/driver_effect_cycle.md"),
            "Observed: generated driver histories passed.\n",
        )
        .unwrap();
        fs::write(
            root.join("module.yaml"),
            r#"spec: rms/module/v0.1
module: { name: evidence-fixture, version: 0.1.0, kind: library, purpose: Evidence fixture. }
invariants:
  - id: driver-owns-effect-cycle
    statement: The driver owns progression.
    authority: composition
    enforced_by: machine-driver
"#,
        )
        .unwrap();
        fs::write(
            root.join("implementation.yaml"),
            r#"spec: rms/implementation/v0.1
module: module.yaml
binding: python
semantic_functions:
  - id: machine-driver
    symbol: src/driver.py#run_machine
    kind: interpreter
    purity: effectful
    discharges:
      invariants: [driver-owns-effect-cycle]
    evidence:
      laws: [verification/laws/driver_effect_cycle.md]
"#,
        )
        .unwrap();

        let module = load_manifest(&root.join("module.yaml")).unwrap();
        let invariant = get_path(&module.value, &["invariants"])
            .and_then(YamlValue::as_sequence)
            .and_then(|invariants| invariants.first())
            .unwrap();
        assert!(semantic_invariant_has_evidence(
            &module,
            invariant,
            "driver-owns-effect-cycle"
        ));

        fs::remove_file(root.join("verification/laws/driver_effect_cycle.md")).unwrap();
        assert!(!semantic_invariant_has_evidence(
            &module,
            invariant,
            "driver-owns-effect-cycle"
        ));
        fs::remove_dir_all(root).unwrap();
    }

