    #[test]
    fn next_classifies_repository_kinds_and_not_applicable_artifacts() {
        let root = unique_test_dir("next-repository-kinds");
        let system_root = root.join("system-root");
        let module_root = root.join("module-root");
        let system_container = root.join("system-container");
        let multi_system = root.join("multi-system");
        let module_workspace = root.join("module-workspace");
        let uninitialized = root.join("uninitialized");
        for path in [
            &system_root,
            &module_root,
            &system_container,
            &multi_system,
            &module_workspace,
            &uninitialized,
        ] {
            fs::create_dir_all(path).unwrap();
        }
        write_profile_manifest(&system_root.join("system.yaml"), "rms/system/v0.1", None);
        write_profile_manifest(
            &module_root.join("module.yaml"),
            "rms/module/v0.1",
            Some("direct-module"),
        );
        write_profile_manifest(
            &system_container.join("app/system.yaml"),
            "rms/system/v0.1",
            None,
        );
        write_profile_manifest(
            &multi_system.join("alpha/system.yaml"),
            "rms/system/v0.1",
            None,
        );
        write_profile_manifest(
            &multi_system.join("beta/system.yaml"),
            "rms/system/v0.1",
            None,
        );
        write_profile_manifest(
            &module_workspace.join("modules/alpha/module.yaml"),
            "rms/module/v0.1",
            Some("alpha"),
        );

        assert_eq!(
            build_repository_profile(&system_root).unwrap().report.kind,
            RepositoryKind::SystemRoot
        );
        assert_eq!(
            build_repository_profile(&module_root).unwrap().report.kind,
            RepositoryKind::ModuleRoot
        );
        assert_eq!(
            build_repository_profile(&system_container)
                .unwrap()
                .report
                .kind,
            RepositoryKind::SystemContainer
        );
        let multi = build_repository_profile(&multi_system).unwrap().report;
        assert_eq!(multi.kind, RepositoryKind::MultiSystemWorkspace);
        assert!(multi
            .canonical_files
            .iter()
            .filter(|item| matches!(item.name.as_str(), "system.yaml" | "context-map.yaml"))
            .all(|item| item.status == "not-applicable"));
        assert_eq!(
            build_repository_profile(&module_workspace)
                .unwrap()
                .report
                .kind,
            RepositoryKind::ModuleWorkspace
        );
        assert_eq!(
            build_repository_profile(&uninitialized)
                .unwrap()
                .report
                .kind,
            RepositoryKind::Uninitialized
        );

        let workspace = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../..");
        let actual = build_repository_profile(&workspace).unwrap().report;
        fs::remove_dir_all(&root).unwrap();
        assert_eq!(actual.kind, RepositoryKind::MultiSystemWorkspace);
        assert!(actual
            .canonical_files
            .iter()
            .filter(|item| matches!(item.name.as_str(), "system.yaml" | "context-map.yaml"))
            .all(|item| item.status == "not-applicable"));
    }

    #[test]
    fn next_repository_profile_requires_current_behavioral_contracts() {
        let root = unique_test_dir("next-current-contract-spec");
        let contracts = root.join("contracts");
        fs::create_dir_all(&contracts).unwrap();
        fs::write(
            contracts.join("do-work.yaml"),
            "spec: rms/contract/v0.2\nname: do-work\nversion: 1\nkind: command\nmeaning: Do work.\n",
        )
        .unwrap();

        let current = build_repository_profile(&root).unwrap();
        assert!(!current
            .diagnostics
            .iter()
            .any(|diagnostic| diagnostic.check == "repository.canonical-spec"));

        fs::write(
            contracts.join("do-work.yaml"),
            "spec: rms/contract/v0.1\nname: do-work\nversion: 1\nkind: command\nmeaning: Do work.\n",
        )
        .unwrap();
        let legacy = build_repository_profile(&root).unwrap();
        assert!(legacy.diagnostics.iter().any(|diagnostic| {
            diagnostic.check == "repository.canonical-spec"
                && diagnostic
                    .message
                    .contains("expects spec `rms/contract/v0.2|v0.3`")
        }));

        fs::remove_dir_all(&root).unwrap();
    }

    #[test]
    fn next_selects_owner_deterministically_without_guessing() {
        let direct_root = unique_test_dir("next-direct-root-owner");
        fs::create_dir_all(direct_root.join("nested")).unwrap();
        write_profile_manifest(
            &direct_root.join("module.yaml"),
            "rms/module/v0.1",
            Some("direct-owner"),
        );
        write_profile_manifest(
            &direct_root.join("nested/other.module.yaml"),
            "rms/module/v0.1",
            Some("other-owner"),
        );
        let direct_profile = build_repository_profile(&direct_root).unwrap();
        let direct = resolve_next_owner(
            &direct_root,
            None,
            "make dragons sparkle",
            &direct_profile.modules,
            false,
        )
        .unwrap();
        assert_eq!(direct.status(), OwnerStatus::Selected);
        assert_eq!(direct.reason, "direct root module");
        assert_eq!(
            direct.selected_module().map(|module| module.name.as_str()),
            Some("direct-owner")
        );
        fs::remove_dir_all(&direct_root).unwrap();

        let sole_root = unique_test_dir("next-sole-top-level-owner");
        fs::create_dir_all(sole_root.join("modules/only")).unwrap();
        write_profile_manifest(
            &sole_root.join("modules/only/module.yaml"),
            "rms/module/v0.1",
            Some("sole-owner"),
        );
        let sole_profile = build_repository_profile(&sole_root).unwrap();
        let sole = resolve_next_owner(
            &sole_root,
            None,
            "make dragons sparkle",
            &sole_profile.modules,
            false,
        )
        .unwrap();
        assert_eq!(sole.status(), OwnerStatus::Selected);
        assert_eq!(sole.reason, "sole top-level module");
        assert_eq!(
            sole.selected_module().map(|module| module.name.as_str()),
            Some("sole-owner")
        );
        fs::remove_dir_all(&sole_root).unwrap();

        let root = unique_test_dir("next-owner-selection");
        fs::create_dir_all(&root).unwrap();
        write_profile_manifest(
            &root.join("alpha.module.yaml"),
            "rms/module/v0.1",
            Some("alpha-payments"),
        );
        write_profile_manifest(
            &root.join("beta.module.yaml"),
            "rms/module/v0.1",
            Some("beta-games"),
        );
        let profile = build_repository_profile(&root).unwrap();

        let explicit = resolve_next_owner(
            &root,
            Some(&root.join("beta.module.yaml")),
            "change payments",
            &profile.modules,
            false,
        )
        .unwrap();
        assert_eq!(explicit.status(), OwnerStatus::Selected);
        assert_eq!(
            explicit
                .selected_module()
                .map(|module| module.name.as_str()),
            Some("beta-games")
        );

        let unique = resolve_next_owner(
            &root,
            None,
            "change alpha payments",
            &profile.modules,
            false,
        )
        .unwrap();
        assert_eq!(unique.status(), OwnerStatus::Selected);
        assert_eq!(
            unique.selected_module().map(|module| module.name.as_str()),
            Some("alpha-payments")
        );

        let no_match =
            resolve_next_owner(&root, None, "make dragons sparkle", &profile.modules, false)
                .unwrap();
        assert_eq!(no_match.status(), OwnerStatus::Ambiguous);
        assert!(no_match.selected_module().is_none());

        fs::write(
            root.join("alpha.module.yaml"),
            next_module_source("alpha", "Own shared reporting"),
        )
        .unwrap();
        fs::write(
            root.join("beta.module.yaml"),
            next_module_source("beta", "Own shared reporting"),
        )
        .unwrap();
        let tied_profile = build_repository_profile(&root).unwrap();
        let tied = resolve_next_owner(
            &root,
            None,
            "change shared reporting",
            &tied_profile.modules,
            false,
        )
        .unwrap();
        assert_eq!(tied.status(), OwnerStatus::Ambiguous);
        assert_eq!(tied.candidates[0].score, tied.candidates[1].score);
        fs::remove_dir_all(&root).unwrap();

        let recursive = route_capability_fixture("next-recursive-owner");
        let recursive_profile = build_repository_profile(&recursive).unwrap();
        let routed = resolve_next_owner(
            &recursive,
            Some(&recursive.join("modules/play-game/module.yaml")),
            "change invalid move rules and transition invariants",
            &recursive_profile.modules,
            false,
        )
        .unwrap();
        assert_eq!(routed.status(), OwnerStatus::Selected);
        assert_eq!(
            routed.selected_module().map(|module| module.name.as_str()),
            Some("play-game")
        );
        assert_eq!(routed.route.len(), 1);

        let exact_child = resolve_next_owner_for_task(
            &recursive,
            None,
            "migrate the machine probe description",
            "machine-probe-description play-game-domain rms-v0-2",
            &recursive_profile.modules,
            false,
        )
        .unwrap();
        assert_eq!(exact_child.status(), OwnerStatus::Selected);
        assert_eq!(
            exact_child
                .selected_module()
                .map(|module| module.name.as_str()),
            Some("play-game-domain")
        );
        assert_eq!(
            exact_child.reason,
            "structured intent subject exactly names canonical module"
        );
        assert_eq!(exact_child.route.len(), 1);

        let humanized_child = resolve_next_owner_for_task(
            &recursive,
            None,
            "In Play Game domain, change the BeginRequest transition.",
            "begin-request play-game",
            &recursive_profile.modules,
            false,
        )
        .unwrap();
        assert_eq!(humanized_child.status(), OwnerStatus::Selected);
        assert_eq!(
            humanized_child
                .selected_module()
                .map(|module| module.name.as_str()),
            Some("play-game-domain")
        );
        assert_eq!(
            humanized_child.reason,
            "task exactly names canonical module"
        );
        assert_eq!(humanized_child.route.len(), 1);

        let composite_export_reconciliation = resolve_next_owner_for_task(
            &recursive,
            None,
            "In composite module play-game, update the exported play-game command contract to exactly match the current provided contract of its exported play-game-boundary child; preserve composition, ownership, and runtime.",
            "play-game play-game-boundary",
            &recursive_profile.modules,
            false,
        )
        .unwrap();
        assert_eq!(
            composite_export_reconciliation.status(),
            OwnerStatus::Selected
        );
        assert_eq!(
            composite_export_reconciliation
                .selected_module()
                .map(|module| module.name.as_str()),
            Some("play-game")
        );
        assert_eq!(
            composite_export_reconciliation.reason,
            "task explicitly reconciles a composite export contract"
        );
        assert_eq!(composite_export_reconciliation.route.len(), 1);

        let exact_parent_path = resolve_next_owner_for_task(
            &recursive,
            None,
            "Caller-owned canonical owner decision: modules/play-game/module.yaml is the sole owner; play-game-boundary remains the execution owner.",
            "play-game play-game-boundary",
            &recursive_profile.modules,
            false,
        )
        .unwrap();
        assert_eq!(exact_parent_path.status(), OwnerStatus::Selected);
        assert_eq!(
            exact_parent_path
                .selected_module()
                .map(|module| module.name.as_str()),
            Some("play-game")
        );
        assert_eq!(
            exact_parent_path.reason,
            "task exactly names a canonical artifact owned by the module"
        );
        assert_eq!(exact_parent_path.route.len(), 1);

        let multiple_humanized_children = resolve_next_owner_for_task(
            &recursive,
            None,
            "Change Play Game domain and Play Game boundary together.",
            "play-game",
            &recursive_profile.modules,
            false,
        )
        .unwrap();
        assert_eq!(multiple_humanized_children.status(), OwnerStatus::Ambiguous);
        assert!(multiple_humanized_children.selected_module().is_none());
        assert_eq!(multiple_humanized_children.candidates.len(), 2);

        let multiple_exact_children = resolve_next_owner(
            &recursive,
            None,
            "play-game-domain play-game-boundary",
            &recursive_profile.modules,
            false,
        )
        .unwrap();
        assert_eq!(multiple_exact_children.status(), OwnerStatus::Ambiguous);
        assert!(multiple_exact_children.selected_module().is_none());
        assert_eq!(multiple_exact_children.candidates.len(), 2);
        fs::remove_dir_all(&recursive).unwrap();

        let cycle_root = unique_test_dir("next-recursive-cycle");
        fs::create_dir_all(&cycle_root).unwrap();
        write_recursive_parent(&cycle_root, "alpha", "beta", "internal", false);
        write_recursive_parent(&cycle_root, "beta", "alpha", "internal", false);
        let cycle = route_next_owner(
            &cycle_root,
            "change alpha rules",
            cycle_root.join("alpha.module.yaml"),
            "recursive route".to_string(),
            Vec::new(),
        )
        .unwrap();
        fs::remove_dir_all(&cycle_root).unwrap();
        assert_eq!(cycle.status(), OwnerStatus::Ambiguous);
        assert_eq!(cycle.route.len(), 1);
    }

    #[test]
    fn next_selects_unique_leaf_declared_owner_and_reports_duplicate_ownership() {
        let root = route_capability_fixture("next-declared-leaf-owner");
        let domain_path = root.join("modules/play-game-domain/module.yaml");
        let boundary_path = root.join("modules/play-game-boundary/module.yaml");
        let mut domain = load_manifest(&domain_path).unwrap();
        set_yaml_sequence_path(
            &mut domain.value,
            &["owns", "decisions"],
            vec![
                YamlValue::String("retained ptt gesture lifecycle".to_string()),
                YamlValue::String("receiver readiness retry eligibility".to_string()),
            ],
        );
        write_yaml_manifest(&domain).unwrap();

        let task = "Reuse and extend the existing retained PTT gesture contract. Retain exactly one PTT hold for at most 1000 ms when secure-media preparation matches the contact and conversation.";
        let profile = build_repository_profile(&root).unwrap();
        let selected = resolve_next_owner_for_task(
            &root,
            None,
            task,
            "retained-ptt-gesture-contract secure-media-preparation",
            &profile.modules,
            false,
        )
        .unwrap();
        assert_eq!(selected.status(), OwnerStatus::Selected);
        assert_eq!(
            selected
                .selected_module()
                .map(|module| module.name.as_str()),
            Some("play-game-domain")
        );
        assert_eq!(
            selected.reason,
            "task uniquely evolves an exact declared ownership phrase"
        );
        assert!(declared_ownership_candidates(
            "Preserve the existing retained PTT gesture contract unchanged.",
            &profile.modules
        )
        .is_empty());

        let mut boundary = load_manifest(&boundary_path).unwrap();
        set_yaml_sequence_path(
            &mut boundary.value,
            &["owns", "decisions"],
            vec![YamlValue::String(
                "retained ptt gesture lifecycle".to_string(),
            )],
        );
        write_yaml_manifest(&boundary).unwrap();
        let duplicate_profile = build_repository_profile(&root).unwrap();
        let ambiguous = resolve_next_owner_for_task(
            &root,
            None,
            task,
            "retained-ptt-gesture-contract secure-media-preparation",
            &duplicate_profile.modules,
            false,
        )
        .unwrap();
        assert_eq!(ambiguous.status(), OwnerStatus::Ambiguous);
        assert!(ambiguous.selected_module().is_none());
        assert_eq!(ambiguous.candidates.len(), 2);
        assert!(ambiguous
            .warnings
            .iter()
            .any(|warning| warning.contains("duplicate or overlapping declared ownership")));
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn next_classifies_prospective_task_lanes_independent_of_git_diff() {
        for (task, expected) in [
            ("inspect and explain this module", TaskLane::ReadOnly),
            (
                "fetch, rebase, and push the Git branch",
                TaskLane::RepositoryOperation,
            ),
            ("design a new billing capability module", TaskLane::Design),
            (
                "change the contract invariant and transition",
                TaskLane::Semantic,
            ),
            ("add a CLI screen and form", TaskLane::Surface),
            (
                "change the public contract for the CLI endpoint",
                TaskLane::SemanticPlusSurface,
            ),
            (
                "fix the parser bug in existing code",
                TaskLane::ImplementationCandidate,
            ),
            ("make it delightful", TaskLane::Undetermined),
        ] {
            assert_eq!(classify_prospective_task(task).lane, expected, "{task}");
        }

        let undetermined_root = copy_minimal_fixture("next-undetermined");
        let undetermined =
            build_next_report(&undetermined_root, None, "make it delightful").unwrap();
        fs::remove_dir_all(&undetermined_root).unwrap();
        assert_eq!(undetermined.result, NextResult::DesignRequired);
        assert!(undetermined
            .steps
            .iter()
            .flat_map(|group| &group.steps)
            .all(|step| !step.args.iter().any(|argument| argument == "implement")));

        let root = copy_minimal_fixture("next-dirty-diff");
        let before = build_next_report(&root, None, "fix the existing implementation bug").unwrap();
        fs::write(root.join("unrelated-notes.txt"), "dirty unrelated work\n").unwrap();
        let after = build_next_report(&root, None, "fix the existing implementation bug").unwrap();
        fs::remove_dir_all(&root).unwrap();
        assert_eq!(
            before.task_classification.lane,
            after.task_classification.lane
        );
        assert_eq!(
            before.owner.selected_module().map(|module| &module.path),
            after.owner.selected_module().map(|module| &module.path)
        );
        assert_eq!(
            serde_json::to_value(&before.steps).unwrap(),
            serde_json::to_value(&after.steps).unwrap()
        );
    }

    #[test]
    fn next_surface_projects_v2_and_repository_operations() {
        let root = copy_minimal_fixture("next-stable-report");
        let before_tree = snapshot_test_tree(&root);
        let task = "change CLI contract; echo 'boom'\nthen continue";
        let first = build_next_report(&root, None, task).unwrap();
        let second = build_next_report(&root, None, task).unwrap();
        let first_surface = project_next_report(&first, false).unwrap();
        let second_surface = project_next_report(&second, false).unwrap();
        let detailed_surface = project_next_report(&first, true).unwrap();
        let json_first = serde_json::to_string_pretty(&first_surface).unwrap();
        let text_first = render_next_surface_report(&first_surface, None);
        let text_second = render_next_surface_report(&second_surface, None);
        let after_tree = snapshot_test_tree(&root);

        let mut stable_first = serde_json::to_value(&first_surface).unwrap();
        let mut stable_second = serde_json::to_value(&second_surface).unwrap();
        for value in [&mut stable_first, &mut stable_second] {
            value.as_object_mut().unwrap().remove("run_id");
            value.as_object_mut().unwrap().remove("receipt_id");
            value.as_object_mut().unwrap().remove("receipt_path");
        }
        assert_eq!(stable_first, stable_second);
        assert_ne!(text_first, text_second);
        assert_ne!(before_tree, after_tree);
        assert!(Path::new(&first_surface.receipt_path).is_file());
        assert!(Path::new(&second_surface.receipt_path).is_file());
        assert_eq!(first_surface.envelope.schema, "rms.surface/v2");
        assert_eq!(first_surface.envelope.command, "next");
        assert!(first_surface.envelope.reasons.len() <= 3);
        assert!(first_surface.envelope.details.is_none());
        assert!(detailed_surface.envelope.details.is_some());
        let detailed_json = serde_json::to_value(&detailed_surface).unwrap();
        assert!(detailed_json["details"].get("steps").is_none());
        for action in detailed_json["steps"].as_array().unwrap() {
            assert!(matches!(
                action["authorization"].as_str(),
                Some("none" | "host-required")
            ));
            if action["kind"] == "command" {
                assert!(action["args"].is_array());
            } else {
                assert!(action.get("args").is_none());
            }
        }
        assert!(json_first.contains("semantic-plus-surface"));
        assert!(!json_first.contains("runtime_activation"));
        assert!(!text_first.contains("# RMS Next"));
        assert!(text_first.contains("rms check --committed"));
        assert!(!json_first.contains("\"cwd\""));
        assert_eq!(
            first_surface
                .envelope
                .next_action
                .as_ref()
                .and_then(|action| action.args())
                .and_then(|args| args.first())
                .map(String::as_str),
            Some("context")
        );
        assert!(!first_surface.steps.iter().any(|action| {
            action
                .args()
                .is_some_and(|args| args.first().is_some_and(|argument| argument == "explain"))
        }));
        for action in &first_surface.steps {
            assert_ne!(action.program(), Some("git"));
            assert_ne!(action.program(), Some("codex"));
            assert_ne!(action.program(), Some("claude"));
        }
        let native_proof = first_surface
            .steps
            .iter()
            .find(|action| action.program() == Some("sh"))
            .unwrap();
        let native_args = native_proof.args().unwrap();
        assert!(native_args[1].starts_with("cd -- "));
        assert!(Command::new("sh")
            .args(native_args)
            .current_dir(std::env::temp_dir())
            .status()
            .unwrap()
            .success());
        let task_step = first_surface
            .steps
            .iter()
            .find(|action| {
                action
                    .args()
                    .is_some_and(|args| args.iter().any(|argument| argument == task))
            })
            .unwrap();
        assert!(task_step.display().unwrap().contains("'\\''boom"));
        assert!(first_surface.steps.iter().any(|action| {
            action.kind() == "manual"
                && action.authorization().is_host_required()
                && action.program().is_none()
        }));

        let repository_operation =
            build_next_report(&root, None, "fetch, rebase, and push the Git branch").unwrap();
        let repository_surface = project_next_report(&repository_operation, false).unwrap();
        assert_eq!(repository_operation.result, NextResult::NoRmsChange);
        assert_eq!(
            repository_operation.task_classification.lane,
            TaskLane::RepositoryOperation
        );
        assert_eq!(repository_surface.lane, "repository-operation");
        assert!(
            repository_surface.envelope.warnings.is_empty(),
            "unexpected repository-operation warnings: {:#?}",
            repository_surface.envelope.warnings
        );
        assert!(repository_surface
            .steps
            .iter()
            .all(|action| action.kind() == "manual"));
        assert!(!repository_surface.steps.iter().any(|action| {
            action
                .args()
                .unwrap_or_default()
                .iter()
                .any(|arg| matches!(arg.as_str(), "design" | "spec" | "gate" | "audit" | "check"))
        }));
        assert_eq!(
            classify_prospective_task("teach rms next to recommend commits").lane,
            TaskLane::Semantic
        );
        for task in [
            "install the RMS CLI",
            "synchronize the Codex plugin skills",
            "check Git status",
            "fetch origin",
            "commit the candidate",
            "rebase onto origin/main",
            "merge the feature branch",
            "push main",
            "can we install it?",
            "please install dependencies",
            "can we commit, rebase, merge, and push?",
        ] {
            assert_eq!(
                classify_prospective_task(task).lane,
                TaskLane::RepositoryOperation,
                "{task}"
            );
        }
        for task in [
            "add push notifications",
            "implement fetch customer profiles from API",
            "handle transaction commit failures",
            "implement rebase support in RMS",
            "fix code, commit, and push",
            "fix bug and push branch",
            "upgrade the API contract to v2",
            "install a new CLI command",
            "configure RMS command behavior",
            "synchronize RMS contract semantics",
            "install a payment capability",
            "install a payment-provider integration",
            "commit a database transaction",
            "push notifications to users",
            "fetch API data from provider",
            "merge duplicate customer records",
            "pull records from storage",
        ] {
            assert_ne!(
                classify_prospective_task(task).lane,
                TaskLane::RepositoryOperation,
                "semantic intent was mistaken for a repository operation: {task}"
            );
        }

        let fresh = unique_test_dir("next-fresh-repository-operation");
        fs::create_dir_all(&fresh).unwrap();
        let fresh_operation = build_next_report(&fresh, None, "install the RMS CLI").unwrap();
        assert_eq!(
            fresh_operation.repository.kind,
            RepositoryKind::Uninitialized
        );
        assert_eq!(fresh_operation.result, NextResult::NoRmsChange);
        assert!(fresh_operation.completion.order.is_empty());
        assert!(fresh_operation.completion.pending_state.is_none());
        fs::remove_dir_all(&fresh).unwrap();
        fs::remove_dir_all(&root).unwrap();
    }

    #[test]
    fn check_facade_delegates_modes_and_preserves_authority() {
        assert_eq!(
            CheckMode::from_flags(false, false, false),
            CheckMode::Project
        );
        assert_eq!(
            CheckMode::from_flags(true, false, false),
            CheckMode::Environment
        );
        assert_eq!(
            CheckMode::from_flags(false, true, false),
            CheckMode::Changes
        );
        assert_eq!(
            CheckMode::from_flags(false, false, true),
            CheckMode::Committed
        );
        assert_eq!(
            aggregate_check_results([CheckResult::Pass, CheckResult::ReviewRequired]),
            CheckResult::ReviewRequired
        );
        assert_eq!(
            aggregate_check_results([CheckResult::Pass, CheckResult::Fail]),
            CheckResult::Fail
        );
        assert_eq!(check_exit_code(CheckResult::Pass), 0);
        assert_eq!(check_exit_code(CheckResult::ReviewRequired), 1);
        assert_eq!(check_exit_code(CheckResult::Fail), 1);

        let root = copy_minimal_fixture("check-facade");
        let project = build_project_check_report(&root).unwrap();
        let environment = build_environment_check_report(&root).unwrap();
        assert_eq!(project.mode, CheckMode::Project);
        assert_eq!(
            project
                .components
                .iter()
                .map(|component| component.id.as_str())
                .collect::<Vec<_>>(),
            ["validate", "compose"]
        );
        assert_eq!(environment.mode, CheckMode::Environment);
        assert_eq!(environment.components[0].id, "diagnose");

        let gate = GateReport {
            result: GateResult::Pass,
            root: root.display().to_string(),
            diff: None,
            source_revision: Some("git:fixture".to_string()),
            impact_result: ImpactResult::NoRmsImpact,
            affected_modules: Vec::new(),
            executable_checks: vec![GateCheck {
                command: "shared gate fixture".to_string(),
                status: GateCheckStatus::Pass,
                message: Some("pass".to_string()),
            }],
            manual_checks: Vec::new(),
        };
        let changes = changes_check_report_from_gate(&root, gate);
        assert_eq!(changes.mode, CheckMode::Changes);
        assert_eq!(changes.result, CheckResult::Pass);
        let candidate = changes.next_action.as_ref().unwrap();
        assert_eq!(candidate.kind(), "manual");
        assert!(candidate.authorization().is_host_required());
        assert!(candidate.program().is_none());
        assert!(candidate.args().is_none());

        let audit = AuditReport {
            result: "pass".to_string(),
            root: root.display().to_string(),
            strict: true,
            source_revision: "git:fixture".to_string(),
            checks: vec![audit_check(
                "fixture.pass",
                "fixture",
                "pass",
                &root,
                "shared strict audit fixture",
            )],
            verification_targets: Vec::new(),
        };
        let committed = committed_check_report_from_audit(&root, audit);
        assert_eq!(committed.mode, CheckMode::Committed);
        assert_eq!(committed.result, CheckResult::Pass);
        assert!(committed.next_action.is_none());

        let failed_gate = changes_check_report_from_gate(
            &root,
            GateReport {
                result: GateResult::Fail,
                root: root.display().to_string(),
                diff: None,
                source_revision: Some("git:fixture".to_string()),
                impact_result: ImpactResult::ReviewRequired,
                affected_modules: vec!["example".to_string()],
                executable_checks: vec![GateCheck {
                    command: "shared failing gate fixture".to_string(),
                    status: GateCheckStatus::Fail,
                    message: Some("failed".to_string()),
                }],
                manual_checks: Vec::new(),
            },
        );
        assert_eq!(failed_gate.result, CheckResult::Fail);
        assert_eq!(failed_gate.components[0].id, "gate");
        let mut failed_audit = committed_check_report_from_audit(
            &root,
            AuditReport {
                result: "fail".to_string(),
                root: root.display().to_string(),
                strict: true,
                source_revision: "git:fixture".to_string(),
                checks: vec![audit_check(
                    "fixture.fail",
                    "fixture",
                    "fail",
                    &root,
                    "shared strict audit failure",
                )],
                verification_targets: Vec::new(),
            },
        );
        assert_eq!(failed_audit.result, CheckResult::Fail);
        assert_eq!(failed_audit.components[0].id, "audit-strict");
        failed_audit.reasons = (1..=6)
            .map(|index| format!("missing representative case {index}"))
            .collect();
        let compact_gaps = project_check_report(&failed_audit, false);
        assert_eq!(compact_gaps.envelope.reasons.len(), 4);
        assert!(compact_gaps.envelope.reasons[3]
            .contains("3 additional reason(s) omitted from compact output"));
        let detailed_gaps = project_check_report(&failed_audit, true);
        assert_eq!(detailed_gaps.envelope.reasons.len(), 6);
        assert_eq!(
            detailed_gaps.envelope.reasons[5],
            "missing representative case 6"
        );

        for report in [&project, &environment, &changes, &committed] {
            let compact = project_check_report(report, false);
            let detailed = project_check_report(report, true);
            assert_eq!(compact.envelope.schema, "rms.surface/v2");
            assert_eq!(compact.envelope.command, "check");
            assert_eq!(compact.mode, report.mode.label());
            assert!(compact.envelope.details.is_none());
            assert!(detailed.envelope.details.is_some());
        }

        let conflict = primary_cli_command()
            .try_get_matches_from(["rms", "check", "--changes", "--committed"])
            .unwrap_err();
        assert_eq!(conflict.kind(), clap::error::ErrorKind::ArgumentConflict);

        let failing_root = copy_minimal_fixture("check-facade-failing");
        fs::remove_dir_all(failing_root.join("verification")).unwrap();
        assert_eq!(
            build_project_check_report(&failing_root).unwrap().result,
            CheckResult::Fail
        );
        assert_eq!(
            build_environment_check_report(&failing_root)
                .unwrap()
                .result,
            CheckResult::Fail
        );
        assert!(
            build_check_report(&failing_root.join("unreadable-root"), CheckMode::Project).is_err()
        );
        fs::remove_dir_all(&failing_root).unwrap();
        fs::remove_dir_all(&root).unwrap();
    }

