    #[test]
    fn machine_apply_declares_distinct_observed_event_type_and_closed_variant() {
        let root = unique_test_dir("machine-observed-event-type");
        run_add_module(
            add_module_request(
                &root,
                "observed-event-machine",
                "Exercise a distinct observed event representation.",
                "library",
                &[],
                Some(ScaffoldShape::DomainEngine),
                Some("swift"),
            ),
            &no_provider_options(),
        )
        .unwrap();
        let implementation = root.join("implementation.yaml");
        let mut declared = load_manifest(&implementation).unwrap();
        set_yaml_string_sequence_path(
            &mut declared.value,
            &["architecture", "machine", "observed_events"],
            &["Observed".to_string()],
        );
        write_yaml_manifest(&declared).unwrap();
        let representation = root.join("Sources/ObservedEventMachine/Representation.swift");
        let mut representation_source = fs::read_to_string(&representation).unwrap();
        representation_source
            .push_str("\npublic enum ExampleObservedEvent: Equatable { case observed }\n");
        fs::write(&representation, representation_source).unwrap();
        let before = load_manifest(&implementation).unwrap();
        assert_eq!(
            machine_semantic_variant_type(&before.value, "observed_event"),
            get_str(
                &before.value,
                &["architecture", "machine", "types", "event"]
            )
        );
        let before_diagnostics = collect_validation_diagnostics(
            &root,
            vec![root.join("module.yaml")],
            Vec::new(),
            Vec::new(),
            Vec::new(),
            vec![implementation.clone()],
            Vec::new(),
        )
        .unwrap();
        assert!(before_diagnostics.iter().any(|diagnostic| {
            diagnostic.check == "structure.declared-variant-not-represented"
                && diagnostic.message.contains("Observed")
        }));
        initialize_test_git_repository(&root);
        let repair = build_next_report(
            &root,
            Some(&root.join("module.yaml")),
            "repair the machine binding declaration for the distinct observed event representation",
        )
        .unwrap();
        assert_eq!(repair.result, NextResult::Ready);
        assert_eq!(repair.owner.status(), OwnerStatus::Selected);
        assert!(repair.blockers.is_empty());
        assert!(repair
            .warnings
            .iter()
            .any(|warning| warning.contains("owner-local machine-binding")));
        assert!(validate_route_receipt(
            &root,
            Path::new(&repair.receipt_path),
            "machine-apply",
            &implementation,
            None,
        )
        .is_ok());
        assert!(validate_route_receipt(
            &root,
            Path::new(&repair.receipt_path),
            "spec-apply",
            &implementation,
            None,
        )
        .is_err());
        let mode = get_str(&before.value, &["architecture", "machine", "mode"])
            .unwrap()
            .to_string();
        let change = format!(
            "spec: rms/machine-change/v0.1\nmodule: implementation.yaml\nmachine:\n  mode: {mode}\n  types:\n    observed_event: ExampleObservedEvent\n"
        );
        run_machine_apply(&implementation, None, Some(&change), None, false).unwrap();
        let after = load_manifest(&implementation).unwrap();
        assert_eq!(
            machine_semantic_variant_type(&after.value, "observed_event"),
            Some("ExampleObservedEvent")
        );
        assert!(get_string_array(
            &after.value,
            &["architecture", "representation", "closed_variants"]
        )
        .contains(&"ExampleObservedEvent".to_string()));
        let diagnostics = collect_validation_diagnostics(
            &root,
            vec![root.join("module.yaml")],
            Vec::new(),
            Vec::new(),
            Vec::new(),
            vec![implementation],
            Vec::new(),
        )
        .unwrap();
        assert!(!diagnostics.iter().any(|diagnostic| {
            diagnostic.check == "structure.declared-variant-not-represented"
                && diagnostic.message.contains("Observed")
        }));
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn legacy_binding_migration_routes_plans_applies_and_validates_end_to_end() {
        let (root, module, implementation) =
            legacy_machine_migration_fixture("legacy-machine-migration-end-to-end");
        let representation_path = root.join("Sources/LegacyMachine/Representation.swift");
        let representation = fs::read_to_string(&representation_path).unwrap();
        let representation = representation.replacen(
            "public enum LegacyMachineState: Equatable {",
            "public enum LegacyMachineState: Equatable {\n    public static let initial: LegacyMachineState = .ready",
            1,
        );
        assert!(representation.contains("public static let initial"));
        fs::write(&representation_path, representation).unwrap();
        initialize_test_git_repository(&root);
        let report =
            build_next_report(&root, Some(&module), "repair the legacy machine binding").unwrap();
        assert_eq!(report.result, NextResult::Ready);
        assert!(validate_route_receipt(
            &root,
            Path::new(&report.receipt_path),
            "machine-apply",
            &implementation,
            None,
        )
        .is_ok());

        let legacy = load_manifest(&implementation).unwrap();
        let prompt = render_machine_plan_prompt(
            &legacy,
            &root,
            "Declare the existing Ready initial state and required pure Swift probe adapter.",
        )
        .unwrap();
        assert!(prompt.contains("commands: null"));
        assert!(prompt.contains("initial_state: null"));
        assert!(prompt.contains("probe: null"));
        assert!(prompt.contains("roles.add[].kind: probe_adapter"));

        let change_yaml = r#"spec: rms/machine-change/v0.1
module: implementation.yaml
commands:
  probe: 'swift test --package-path . --filter "${RMS_PROBE_RUNNER##*#}"'
machine:
  mode: stateless-decision-machine
  initial_state: Ready
  transition_signature: input-only
probe:
  protocol: rms/machine-probe/v0.2
  command: probe
  runner: Tests/LegacyMachineTests/MachineProbeTests.swift#testProbeMachine
  initial_state_function: Sources/LegacyMachine/Representation.swift#LegacyMachineState.initial
roles:
  add:
    - kind: probe_adapter
      path: Tests/LegacyMachineTests/MachineProbeTests.swift
  remove: []
"#;
        let parsed = parse_machine_change(None, Some(change_yaml), None).unwrap();
        assert_eq!(parsed.machine.initial_state.as_deref(), Some("Ready"));
        assert_eq!(
            parsed.probe.as_ref().map(|probe| probe.command.as_str()),
            Some("probe")
        );

        let before = fs::read_to_string(&implementation).unwrap();
        run_machine_apply(&implementation, None, Some(change_yaml), None, true).unwrap();
        assert_eq!(fs::read_to_string(&implementation).unwrap(), before);
        run_machine_apply(&implementation, None, Some(change_yaml), None, false).unwrap();

        let applied = load_manifest(&implementation).unwrap();
        assert!(binding_symbol_reference_exists(
            implementation.parent().unwrap(),
            &applied,
            "Sources/LegacyMachine/Representation.swift#LegacyMachineState.initial"
        ));
        assert_eq!(
            get_str(
                &applied.value,
                &["architecture", "machine", "initial_state"]
            ),
            Some("Ready")
        );
        assert_eq!(
            get_str(&applied.value, &["architecture", "probe", "command"]),
            Some("probe")
        );
        assert_eq!(
            get_str(&applied.value, &["commands", "probe"]),
            Some("swift test --package-path . --filter \"${RMS_PROBE_RUNNER##*#}\"")
        );
        assert!(structure_role_paths(&applied, "probe_adapter")
            .iter()
            .any(|path| path == "Tests/LegacyMachineTests/MachineProbeTests.swift"));
        let diagnostics = collect_validation_diagnostics(
            &root,
            vec![module],
            Vec::new(),
            Vec::new(),
            Vec::new(),
            vec![implementation],
            Vec::new(),
        )
        .unwrap();
        assert_no_error_diagnostics(&diagnostics);

        fs::remove_dir_all(root).unwrap();
    }

