    #[test]
    fn semantic_plan_repair_prompt_teaches_boundary_authority_and_async_output_repairs() {
        let diagnostics = vec![
            error_diagnostic(
                "contract.clause-id-duplicate",
                Path::new("contracts/apns-delivery.v1.yaml"),
                "contract `apns-delivery` repeats clause or case id `malformed-input`",
            ),
            error_diagnostic(
                "semantic.binding-dependency-add-exists",
                Path::new("implementation.yaml"),
                "local binding dependency `apns-delivery-decisions` already exists; use `binding_dependencies.set` to replace the complete set",
            ),
            error_diagnostic(
                "semantic.authority-invalid",
                Path::new("module.yaml"),
                "authority `apns-provider-client-authority` requires a unique stable id, kind privileged|unsafe|foreign, capabilities, and rationale",
            ),
            error_diagnostic(
                "machine-change.transition-output-missing",
                Path::new("implementation.yaml"),
                "command transition `DeliverApnsWake` must declare `reply`, `rejection`, or `no_reply_justification`",
            ),
            error_diagnostic(
                "semantic.function-purity",
                Path::new("module.yaml"),
                "semantic function `boundary-driver` kind `transition` must be pure",
            ),
            error_diagnostic(
                "schema.validate",
                Path::new("implementation.yaml"),
                "\"apns-provider-client\" does not match \"^[A-Za-z_][A-Za-z0-9_]*$\" at `/architecture/machine/resource_protocols/0/resource`",
            ),
            error_diagnostic(
                "semantic.capability-binding-missing",
                Path::new("module.yaml"),
                "implemented provided capability requires its public behavior binding",
            ),
            error_diagnostic(
                "semantic.function-contract-missing",
                Path::new("implementation.yaml"),
                "semantic function discharges an unknown contract name instead of its path",
            ),
            error_diagnostic(
                "surface.surface",
                Path::new("implementation.yaml"),
                "unsupported surface `Swift public API`",
            ),
        ];
        let repair = render_spec_plan_repair_prompt(
            "bounded schema context",
            "spec: rms/semantic-change/v0.1\n",
            &diagnostics,
        );

        assert!(repair
            .contains("every identifier in one `semantics.behavior` object is globally unique"));
        assert!(repair.contains("complete set of RMS module ids"));
        assert!(repair.contains("kind` is exactly `privileged`, `unsafe`, or `foreign`"));
        assert!(repair.contains("no_reply_justification: effect result is pending"));
        assert!(repair.contains("canonical transition semantic function is always `kind: transition` and `purity: pure`"));
        assert!(repair.contains("Resource protocol identifier repair rule"));
        assert!(repair.contains("except for `semantic.binding-dependency-add-exists`"));
        assert!(repair.contains("Public capability binding repair rule"));
        assert!(repair.contains("`public_kind: capability`"));
        assert!(repair.contains("exact module-relative contract path"));
        assert!(repair.contains("Runnable surface repair rule"));
        assert!(repair.contains("Do not emit a `surfaces` change for a Swift public API"));
        assert!(repair.contains("Original bounded schema context"));
    }

