        let program = root.join("fake-semantic-plan-codex.sh");
        write_test_file(
            &program,
            r#"#!/bin/sh
set -eu
cat >/dev/null
printf '%s\n' 'provider returned without a structured response' >&2
exit 0
"#,
        );
        let mut permissions = fs::metadata(&program).unwrap().permissions();
        permissions.set_mode(0o755);
