    #[test]
    fn trace_bundle_diagnoses_first_bad_transition() {
        let root = unique_test_dir("trace-diagnose");
        fs::create_dir_all(&root).unwrap();
        let bundle = root.join("trace.yaml");
        fs::write(
            &bundle,
            r#"spec: rms/trace-bundle/v0.1
machine: BookingMachine
journal:
  - id: t1
    state_before: Held
    input: Confirm
    output:
      next_state: Confirmed
      events: []
      commands: []
      effects: []
      reply: Accepted
      rejection: null
    state_after: Confirmed
    source:
      function: transition
      branch: Confirm
  - id: t2
    state_before: Held
    input: Cancel
    output:
      next_state: Cancelled
      events: []
      commands: []
      effects: []
      reply: Accepted
    state_after: Cancelled
    source:
      function: transition
      branch: Cancel
"#,
        )
        .unwrap();

        let report = build_trace_report(&bundle).unwrap();

        fs::remove_dir_all(&root).unwrap();
        assert_eq!(report.result, "fail");
        assert!(report.diagnostics.iter().any(|diagnostic| {
            diagnostic.check == "trace.timeline-discontinuity" && diagnostic.record_index == Some(1)
        }));
        let first_bad = report.first_bad_transition.expect("first bad transition");
        assert_eq!(first_bad.index, 1);
        assert!(first_bad.reason.contains("trace.timeline-discontinuity"));
    }

    #[test]
    fn trace_bundle_reports_declared_first_bad_transition() {
        let root = unique_test_dir("trace-declared-first-bad");
        fs::create_dir_all(&root).unwrap();
        let bundle = root.join("trace.yaml");
        fs::write(
            &bundle,
            r#"spec: rms/trace-bundle/v0.1
machine: BookingMachine
records:
  - id: t1
    state_before: Held
    input: Confirm
    output:
      next_state: Confirmed
      events: []
      commands: []
      effects: []
      reply: Accepted
      rejection: null
    state_after: Confirmed
    source:
      function: transition
      branch: Confirm
  - id: t2
    state_before: Confirmed
    input: Cancel
    output:
      next_state: Confirmed
      events:
        - tag: CommandRejected
          rejection: IllegalTransition
      commands: []
      effects: []
      reply:
        tag: Rejected
        rejection: IllegalTransition
      rejection: IllegalTransition
    state_after: Confirmed
    source:
      function: transition
      branch: IllegalTransition
first_bad_transition:
  index: 1
  state_after_replay: Confirmed
"#,
        )
        .unwrap();

        let report = build_trace_report(&bundle).unwrap();

        fs::remove_dir_all(&root).unwrap();
        assert_eq!(report.result, "pass");
        let first_bad = report.first_bad_transition.expect("first bad transition");
        assert_eq!(first_bad.index, 1);
        assert_eq!(first_bad.reason, "declared by trace bundle metadata");
        assert!(first_bad
            .source
            .as_deref()
            .unwrap_or("")
            .contains("IllegalTransition"));
    }

