    #[test]
    fn non_ready_routes_never_select_an_owner() {
        for result in generate_non_ready_route_cases() {
            let selected = RouteModuleSummary {
                name: "candidate".to_string(),
                path: "/repository/modules/candidate/module.yaml".to_string(),
                kind: "tool".to_string(),
                shape: "boundary-adapter".to_string(),
                visibility: Some("public".to_string()),
            };
            let mut owner = OwnerResolution::selected(
                "tentative match".to_string(),
                selected,
                Vec::new(),
                vec!["candidate".to_string()],
                Vec::new(),
            );
            let mut context = NextContext {
                files: vec![ReadinessItem {
                    name: "candidate".to_string(),
                    path: "/repository/modules/candidate/module.yaml".to_string(),
                    status: "present".to_string(),
                }],
                implementation: Some(
                    "/repository/modules/candidate/implementation.yaml".to_string(),
                ),
                declared_roles: vec![DeclaredRolePath {
                    role: "boundary".to_string(),
                    path: "/repository/modules/candidate/src/boundary.rs".to_string(),
                }],
                edit_authority: "candidate".to_string(),
            };

            enforce_non_ready_ownerlessness(result, &mut owner, &mut context);

            assert_eq!(owner.status(), OwnerStatus::None);
            assert!(owner.selected_module().is_none());
            assert!(owner.route.is_empty());
            assert_eq!(owner.candidates.len(), 1);
            assert!(context.files.is_empty());
            assert!(context.implementation.is_none());
            assert!(context.declared_roles.is_empty());
            assert!(context.edit_authority.contains("no owner-scoped"));
            let steps = build_next_steps(
                Path::new("/repository"),
                "task",
                result,
                &RepositoryProfile {
                    kind: RepositoryKind::SystemRoot,
                    root: "/repository".to_string(),
                    has_project_content: true,
                    system_manifests: Vec::new(),
                    module_manifests: Vec::new(),
                    top_level_modules: Vec::new(),
                    canonical_files: Vec::new(),
                },
                &undetermined_task_classification(),
                &owner,
                &context,
                None,
                None,
            )
            .unwrap();
            assert!(steps.iter().flat_map(|group| &group.steps).all(|step| {
                step.description.contains("no declaration")
                    || !step.description.contains("selected owner")
            }));
        }
    }

    #[cfg(unix)]
    fn write_fake_codex(root: &Path, mode: &str) -> (PathBuf, PathBuf, PathBuf) {
        use std::os::unix::fs::PermissionsExt;
        let program = root.join("fake-codex.sh");
        let counter = root.join("provider-count.txt");
        let invocation = root.join("provider-invocation.txt");
        let valid = r#"{"spec":"rms/intent-model/v0.1","operation":"implementation-change","change_scope":"existing-module","subjects":["cache-task"],"facts":{"domain_decisions":{"disposition":"absent","basis":"inferred","source_quote":null,"rationale":"not requested"},"lifecycle":{"disposition":"absent","basis":"inferred","source_quote":null,"rationale":"not requested"},"effects":{"disposition":"absent","basis":"inferred","source_quote":null,"rationale":"not requested"},"runnable_surface":{"disposition":"absent","basis":"inferred","source_quote":null,"rationale":"not requested"},"reuse":{"disposition":"absent","basis":"inferred","source_quote":null,"rationale":"not requested"}},"responsibilities":[],"surface_kinds":[],"binding_preferences":[],"open_questions":[]}"#;
        let script = format!(
            r#"#!/bin/sh
set -eu
output=""
execution_root=""
invocation_file='{}'
{{
  printf 'args='
  printf ' <%s>' "$@"
  printf '\n'
}} > "$invocation_file"
while [ "$#" -gt 0 ]; do
  case "$1" in
    --cd) execution_root="$2"; shift 2 ;;
    --output-last-message) output="$2"; shift 2 ;;
    *) shift ;;
  esac
done
printf 'execution_root=%s\n' "$execution_root" >> "$invocation_file"
counter_file='{}'
count=0
if [ -f "$counter_file" ]; then count=$(sed -n '1p' "$counter_file"); fi
count=$((count + 1))
printf '%s\n' "$count" > "$counter_file"
case '{}' in
  incompatible) printf '%s\n' 'unknown option --output-schema' >&2; exit 2 ;;
  quota) printf '%s\n' "ERROR: You've hit your usage limit. Visit settings to purchase more credits or try again tomorrow." >&2; exit 1 ;;
  readonly-state) printf '%s\n' 'failed to open state db: attempt to write a readonly database' >&2; exit 1 ;;
  invalid) response='{{"invalid":true}}' ;;
  repair) if [ "$count" -eq 1 ]; then response='{{"invalid":true}}'; else response='{}'; fi ;;
  slow) sleep 1; response='{}' ;;
  *) response='{}' ;;
esac
printf '%s\n' "$response" > "$output"
"#,
            invocation.display(),
            counter.display(),
            mode,
            valid,
            valid,
            valid,
        );
        write_test_file(&program, &script);
        let mut permissions = fs::metadata(&program).unwrap().permissions();
        permissions.set_mode(0o755);
        fs::set_permissions(&program, permissions).unwrap();
        (program, counter, invocation)
    }

    #[cfg(unix)]
    #[test]
    fn provider_pipeline_repairs_caches_refreshes_and_deduplicates() {
        let root = unique_test_dir("provider-pipeline");
        fs::create_dir_all(&root).unwrap();
        let (program, counter, invocation) = write_fake_codex(&root, "success");
        let mut options = no_provider_options();
        options.provider = Provider::Codex;
        options.run_root = PathBuf::from(".rms/runs");
        options.provider_timeout_seconds = 5;

        let first = extract_provider_intent_with_program(
            &root,
            "next",
            "cache task",
            &options,
            false,
            &program,
        )
        .unwrap();
        assert_eq!(fs::read_to_string(&counter).unwrap().trim(), "1");
        let recorded_invocation = fs::read_to_string(&invocation).unwrap();
        let execution_root = recorded_invocation
            .lines()
            .find_map(|line| line.strip_prefix("execution_root="))
            .map(PathBuf::from)
            .expect("provider execution root");
        assert_ne!(execution_root, root);
        assert!(
            !execution_root.exists(),
            "temporary provider workspace leaked"
        );
        for argument in [
            "<--ephemeral>",
            "<--ignore-user-config>",
            "<--ignore-rules>",
            "<--skip-git-repo-check>",
            "<shell_tool>",
            "<unified_exec>",
            "<plugins>",
        ] {
            assert!(recorded_invocation.contains(argument), "{argument}");
        }
        assert!(!recorded_invocation.contains("<--profile>"));

        let profiled_root = unique_test_dir("provider-profile");
        fs::create_dir_all(&profiled_root).unwrap();
        let (profiled_program, _, profiled_invocation) =
            write_fake_codex(&profiled_root, "success");
        let mut profiled_options = options.clone();
        profiled_options.profile = Some("cheaper".to_string());
        extract_provider_intent_with_program(
            &profiled_root,
            "next",
            "profiled cache task",
            &profiled_options,
            false,
            &profiled_program,
        )
        .unwrap();
        let profiled_invocation = fs::read_to_string(profiled_invocation).unwrap();
        assert!(profiled_invocation.contains("<--profile> <cheaper>"));
        for artifact in [
            "request.yaml",
            "prompt.md",
            "intent-schema.json",
            "response.md",
            "attempt-1-response.md",
            "normalized-intent.json",
            "intent-diagnostics.json",
            "provider.json",
        ] {
            assert!(first.run_dir.join(artifact).is_file(), "{artifact}");
        }
        let second = extract_provider_intent_with_program(
            &root,
            "next",
            "cache task",
            &options,
            false,
            &program,
        )
        .unwrap();
        assert_eq!(fs::read_to_string(&counter).unwrap().trim(), "1");
        assert!(fs::read_to_string(second.run_dir.join("provider.json"))
            .unwrap()
            .contains("\"cache\": \"hit\""));
        extract_provider_intent_with_program(&root, "next", "cache task", &options, true, &program)
            .unwrap();
        assert_eq!(fs::read_to_string(&counter).unwrap().trim(), "2");

        let repair_root = unique_test_dir("provider-repair");
        fs::create_dir_all(&repair_root).unwrap();
        let (repair_program, repair_counter, _) = write_fake_codex(&repair_root, "repair");
        let repair = extract_provider_intent_with_program(
            &repair_root,
            "design",
            "cache task",
            &options,
            false,
            &repair_program,
        )
        .unwrap();
        assert_eq!(fs::read_to_string(repair_counter).unwrap().trim(), "2");
        assert!(repair.run_dir.join("attempt-2-response.md").is_file());

        let invalid_root = unique_test_dir("provider-invalid");
        fs::create_dir_all(&invalid_root).unwrap();
        let (invalid_program, _, _) = write_fake_codex(&invalid_root, "invalid");
        assert!(extract_provider_intent_with_program(
            &invalid_root,
            "next",
            "cache task",
            &options,
            false,
            &invalid_program,
        )
        .is_err());
        let cache_entries = fs::read_dir(invalid_root.join(DEFAULT_INTENT_CACHE_ROOT))
            .unwrap()
            .filter_map(Result::ok)
            .filter(|entry| entry.file_type().is_ok_and(|kind| kind.is_dir()))
            .count();
        assert_eq!(cache_entries, 0);

        let incompatible_root = unique_test_dir("provider-incompatible");
        fs::create_dir_all(&incompatible_root).unwrap();
        let (incompatible_program, _, _) = write_fake_codex(&incompatible_root, "incompatible");
        let error = extract_provider_intent_with_program(
            &incompatible_root,
            "next",
            "cache task",
            &options,
            false,
            &incompatible_program,
        )
        .unwrap_err()
        .to_string();
        assert!(error.contains("upgrade Codex"), "{error}");
        let failure_run = fs::read_dir(incompatible_root.join(".rms/runs"))
            .unwrap()
            .filter_map(Result::ok)
            .max_by_key(|entry| entry.file_name())
            .unwrap()
            .path();
        for artifact in [
            "request.yaml",
            "prompt.md",
            "intent-schema.json",
            "response.md",
            "attempt-1-response.md",
            "normalized-intent.json",
            "intent-diagnostics.json",
            "provider.json",
            "route.json",
            "route-receipt.json",
        ] {
            assert!(failure_run.join(artifact).is_file(), "{artifact}");
        }
        assert!(!failure_run.join("attempt-2-response.md").exists());
        let failure_receipt: RouteReceipt =
            serde_json::from_slice(&fs::read(failure_run.join("route-receipt.json")).unwrap())
                .unwrap();
        assert_eq!(
            failure_receipt.payload.route_result,
            "provider-incompatible"
        );
        assert!(failure_receipt.payload.owner_module.is_none());
        assert!(failure_receipt.payload.allowed_action_families.is_empty());
        let failure_route: JsonValue =
            serde_json::from_slice(&fs::read(failure_run.join("route.json")).unwrap()).unwrap();
        assert_eq!(failure_route["owner"]["status"], "none");
        assert!(failure_route["summary"]
            .as_str()
            .unwrap()
            .contains("selected no owner"));
        assert!(failure_run.join("caller-intent-template.yaml").is_file());
        assert!(failure_route["recovery"]["command"]
            .as_str()
            .unwrap()
            .contains("--intent-file"));

        for (mode, expected_result) in [
            ("quota", "provider-quota-exhausted"),
            ("readonly-state", "provider-state-read-only"),
        ] {
            let failure_root = unique_test_dir(&format!("provider-{mode}"));
            fs::create_dir_all(&failure_root).unwrap();
            let (failure_program, _, _) = write_fake_codex(&failure_root, mode);
            let failure = extract_provider_intent_with_program(
                &failure_root,
                "next",
                "urgent deterministic defect",
                &options,
                false,
                &failure_program,
            )
            .unwrap_err()
            .to_string();
            assert!(failure.contains("selected no owner"), "{failure}");
            let failure_run = fs::read_dir(failure_root.join(".rms/runs"))
                .unwrap()
                .filter_map(Result::ok)
                .max_by_key(|entry| entry.file_name())
                .unwrap()
                .path();
            let receipt: RouteReceipt =
                serde_json::from_slice(&fs::read(failure_run.join("route-receipt.json")).unwrap())
                    .unwrap();
            assert_eq!(receipt.payload.route_result, expected_result);
            assert!(receipt.payload.owner_module.is_none());
            assert!(receipt.payload.allowed_action_families.is_empty());
            let route: JsonValue =
                serde_json::from_slice(&fs::read(failure_run.join("route.json")).unwrap()).unwrap();
            assert_eq!(route["owner"]["status"], "none");
            assert_eq!(
                route["recovery"]["mode"],
                "intentional-caller-authored-typed-intent"
            );
            assert!(route["recovery"]["command"]
                .as_str()
                .unwrap()
                .contains("caller-intent-template.yaml"));
            let template =
                fs::read_to_string(failure_run.join("caller-intent-template.yaml")).unwrap();
            parse_intent_model_source(&template).unwrap();
            fs::remove_dir_all(failure_root).unwrap();
        }

        let concurrent_root = unique_test_dir("provider-concurrent");
        fs::create_dir_all(&concurrent_root).unwrap();
        let (slow_program, slow_counter, _) = write_fake_codex(&concurrent_root, "slow");
        let first_root = concurrent_root.clone();
        let second_root = concurrent_root.clone();
        let first_program = slow_program.clone();
        let second_program = slow_program.clone();
        let first_options = options.clone();
        let second_options = options.clone();
        let one = thread::spawn(move || {
            extract_provider_intent_with_program(
                &first_root,
                "next",
                "cache task",
                &first_options,
                false,
                &first_program,
            )
            .unwrap()
        });
        let two = thread::spawn(move || {
            extract_provider_intent_with_program(
                &second_root,
                "next",
                "cache task",
                &second_options,
                false,
                &second_program,
            )
            .unwrap()
        });
        one.join().unwrap();
        two.join().unwrap();
        assert_eq!(fs::read_to_string(slow_counter).unwrap().trim(), "1");

        for path in [
            root,
            repair_root,
            invalid_root,
            incompatible_root,
            concurrent_root,
            profiled_root,
        ] {
            fs::remove_dir_all(path).unwrap();
        }
    }

    #[test]
    fn hunt_posture_derives_boundary_and_reusable_obligations_with_closed_exceptions() {
        let root = unique_test_dir("hunt-posture");
        fs::create_dir_all(&root).unwrap();
        write_test_file(
            &root.join("module.yaml"),
            r#"spec: rms/module/v0.1
module:
  name: hunt-posture
  version: 0.1.0
  kind: library
  purpose: Exercise risk-derived hunt obligations.
profiles: [core, boundary]
verification:
  hunt_exceptions: []
"#,
        );
        write_test_file(
            &root.join("implementation.yaml"),
            r#"spec: rms/implementation/v0.1
module: hunt-posture
binding: rust
source: { root: ., public_entrypoint: src/lib.rs }
commands: { properties: "true" }
distribution: { reusable: true }
architecture:
  shape: boundary-adapter
  reliability:
    properties:
      - id: generated-boundary
        proves: boundary-law
        kind: property
        input_space: generated inputs
        operation: parse
        oracle: [parsing is total]
        evidence: { path: evidence.md }
        counterexamples: { path: counterexamples }
        realizations:
          - profile: smoke
            strategy: generated-property
            command: properties
            generator: src/lib.rs#cases
            runner: src/lib.rs#property
"#,
        );
        let module = load_manifest(&root.join("module.yaml")).unwrap();
        let mut diagnostics = Vec::new();
        validate_hunt_posture(&module, &mut diagnostics);
        let messages = diagnostics
            .iter()
            .map(|diagnostic| diagnostic.message.as_str())
            .collect::<Vec<_>>();
        assert!(messages
            .iter()
            .any(|message| message.contains("boundary-fuzz")));
        assert!(messages
            .iter()
            .any(|message| message.contains("oracle-mutation")));

        let mut module = module;
        set_yaml_sequence_path(
            &mut module.value,
            &["verification", "hunt_exceptions"],
            vec![
                serde_yaml::from_str(
                    "{ obligation: boundary-fuzz, reason: finite generated grammar is completely enumerated }",
                )
                .unwrap(),
                serde_yaml::from_str(
                    "{ obligation: oracle-mutation, reason: fixture has no reusable semantic oracle to mutate }",
                )
                .unwrap(),
            ],
        );
        write_yaml_manifest(&module).unwrap();
        let module = load_manifest(&root.join("module.yaml")).unwrap();
        let mut diagnostics = Vec::new();
        validate_hunt_posture(&module, &mut diagnostics);
        assert!(
            diagnostics
                .iter()
                .all(|diagnostic| diagnostic.check != "structure.hunt-lane-missing"),
            "{diagnostics:#?}"
        );
        fs::remove_dir_all(root).unwrap();
    }

